fn validator(byte: u8) -> [u8; 32] {
    [byte; 32]
}

fn signature(byte: u8) -> [u8; 96] {
    [byte; 96]
}

fn head_block(state_root: [u8; 32]) -> Block {
    Block {
        header: BlockHeader {
            chain_id: 7,
            height: 3,
            round: 3,
            proposer: validator(1),
            parent_hash: [2; 32],
            parent_state_root: [1; 32],
            tx_root: body_root(&BlockBody { items: vec![] }),
            event_root: [3; 32],
            state_root,
            qc: QuorumCertificate {
                view: 2,
                block_hash: [4; 32],
                signatures: vec![Signature {
                    validator: validator(1),
                    bytes: signature(7),
                }],
            },
            timestamp_ms: 1_000,
        },
        body: BlockBody { items: vec![] },
    }
}

fn signing_key(byte: u8) -> SigningKey {
    SigningKey::from_bytes(&[byte; 32])
}

fn seed_account_policy_usdc(engine: &mut SingleNodeEngine, account_id: u64, amount: u64) {
    let mut address = [0_u8; 20];
    address[12..].copy_from_slice(&account_id.to_be_bytes());
    engine
        .apply_committed_state_updates(
            [
                (account_evm_address_state_key(account_id), address.to_vec()),
                (
                    evm_address_account_state_key(address),
                    account_id.to_be_bytes().to_vec(),
                ),
                (
                    policy_usdc_balance_state_key(address),
                    U256::from(amount).to_be_bytes::<32>().to_vec(),
                ),
            ],
            std::iter::empty(),
        )
        .expect("policy USDC seed should update committed state");
}

fn seed_policy_usdc_for_address(engine: &mut SingleNodeEngine, address: [u8; 20], amount: u64) {
    engine
        .apply_committed_state_updates(
            [(
                policy_usdc_balance_state_key(address),
                U256::from(amount).to_be_bytes::<32>().to_vec(),
            )],
            std::iter::empty(),
        )
        .expect("policy USDC seed should update committed state");
}

fn list_delegation_for_real_capital(
    engine: &mut SingleNodeEngine,
    delegation: &Delegation,
    listed_for_discovery: bool,
    deposit_enabled: bool,
) -> crate::vaults::VaultId {
    let vault_id = crate::vaults::vault_id_for_delegation(&delegation.delegation_id);
    engine
        .test_upsert_real_capital_listing(RealCapitalListing {
            vault_id,
            delegation_id: delegation.delegation_id,
            serving_agent: delegation.agent,
            mode: VaultRealCapitalMode::CappedPilot,
            pilot_min_serving_agent_tier: None,
            tier0_pilot_exception: true,
            deposit_enabled,
            listed_for_discovery,
            caps: ListingCaps {
                per_principal_micro_usdc: 1_000_000_000,
                total_vault_tvl_micro_usdc: 1_000_000_000,
            },
            pilot_principal_allowlist: None,
            listed_at_block: engine.head().header.height,
            last_updated_block: engine.head().header.height,
            last_updated_governance_action: [9; 32],
        })
        .expect("test real-capital listing should seed");
    vault_id
}

fn encode_address_arg(selector: [u8; 4], address: [u8; 20]) -> Vec<u8> {
    let mut calldata = Vec::with_capacity(36);
    calldata.extend_from_slice(&selector);
    calldata.extend_from_slice(&[0_u8; 12]);
    calldata.extend_from_slice(&address);
    calldata
}

fn encode_u256_arg(selector: [u8; 4], amount: U256) -> Vec<u8> {
    let mut calldata = Vec::with_capacity(36);
    calldata.extend_from_slice(&selector);
    calldata.extend_from_slice(&amount.to_be_bytes::<32>());
    calldata
}

fn signed_evm_usdc_deposit_raw_tx(
    secret_byte: u8,
    nonce: u64,
    amount: u64,
) -> (kombat_chain_consensus::Hash, [u8; 20], Vec<u8>, Vec<u8>) {
    use alloy_consensus::{
        crypto::secp256k1::{public_key_to_address, sign_message},
        SignableTransaction, TxEip1559, TxEnvelope,
    };
    use alloy_eips::Encodable2718;
    use alloy_primitives::{Bytes as AlloyBytes, TxKind, B256, U256 as AlloyU256};
    use secp256k1::{PublicKey, Secp256k1, SecretKey};

    let calldata = encode_u256_arg([0x6a, 0xc6, 0x11, 0x85], U256::from(amount));
    let secp = Secp256k1::new();
    let secret_bytes = [secret_byte; 32];
    let secret = SecretKey::from_slice(&secret_bytes).expect("secret should decode");
    let public_key = PublicKey::from_secret_key(&secp, &secret);
    let sender = public_key_to_address(public_key).into_array();
    let tx = TxEip1559 {
        chain_id: 7,
        nonce,
        gas_limit: 200_000,
        max_fee_per_gas: 0,
        max_priority_fee_per_gas: 0,
        to: TxKind::Call(evm_usdc_system_address_bytes().into()),
        value: AlloyU256::ZERO,
        access_list: Default::default(),
        input: AlloyBytes::from(calldata.clone()),
    };
    let signature = sign_message(B256::from_slice(&secret_bytes), tx.signature_hash())
        .expect("transaction should sign");
    let signed_tx = tx.into_signed(signature);
    let envelope: TxEnvelope = signed_tx.into();
    let raw_tx = envelope.encoded_2718();
    let decoded = decode_raw_evm_transaction(&raw_tx).expect("raw tx should decode");
    (decoded.tx_hash, sender, raw_tx, calldata)
}

fn consensus_signature_bytes(byte: u8, message: &[u8]) -> [u8; 96] {
    let mut bytes = [0_u8; 96];
    bytes[..64].copy_from_slice(&signing_key(byte).sign(message).to_bytes());
    bytes
}

