fn network_bootstrap_config() -> super::NetworkBootstrapConfig {
    let validator_set = load_validator_set_from_str(&format!(
        r#"
epoch = 7

[[validators]]
validator_id = "0x{}"
consensus_pubkey = "0x{}"
network_pubkey = "0x1111"
rpc_endpoints = ["https://validator-9.testnet.0x26.xyz/api"]
region = "eu-west"
operator_name = "validator-nine"
enabled = true

[validators.bond]
asset = "USDC"
amount = 100
status = "Active"

[[validators]]
validator_id = "0x0808080808080808080808080808080808080808080808080808080808080808"
consensus_pubkey = "0x{}"
network_pubkey = "0x2222"
rpc_endpoints = ["https://validator-8.testnet.0x26.xyz/api"]
region = "eu-central"
operator_name = "validator-eight"
enabled = true

[validators.bond]
asset = "USDC"
amount = 100
status = "Active"
"#,
        hex::encode(validator(9)),
        hex::encode(signing_key(9).verifying_key().to_bytes()),
        hex::encode(signing_key(8).verifying_key().to_bytes())
    ))
    .expect("validator set should parse");
    let bootstrap_peers =
        bootstrap_validator(&validator_set, validator(9)).expect("bootstrap should succeed");
    let local_validator = bootstrap_peers.local.clone();
    super::NetworkBootstrapConfig {
        validator_set,
        bootstrap_peers,
        local_validator: Some(local_validator),
        public_rpc_url: Some("https://validator-9.testnet.0x26.xyz/api".into()),
    }
}

