fn follower_network_fixture_with_leader_endpoints(
    leader_endpoints: &[&str],
) -> (SingleNodeEngine, super::NetworkBootstrapConfig) {
    let round = 1_u64;
    let base_validator_set = load_validator_set_from_str(&format!(
        r#"
epoch = 7

[[validators]]
validator_id = "0x{}"
consensus_pubkey = "0x{}"
network_pubkey = "0x1111"
rpc_endpoints = ["http://127.0.0.1:1"]
region = "eu-west"
operator_name = "validator-nine"
enabled = true

[validators.bond]
asset = "USDC"
amount = 100
status = "Active"

[[validators]]
validator_id = "0x{}"
consensus_pubkey = "0x{}"
network_pubkey = "0x2222"
rpc_endpoints = ["{}"]
region = "eu-central"
operator_name = "validator-eight"
enabled = true

[validators.bond]
asset = "USDC"
amount = 100
status = "Active"
"#,
        hex::encode(validator(9)),
        hex::encode(signing_key(9).verifying_key().to_bytes()),
        hex::encode(validator(8)),
        hex::encode(signing_key(8).verifying_key().to_bytes()),
        "http://127.0.0.1:1"
    ))
    .expect("validator set should parse");
    let elected_leader = select_leader_for_validator_set(round, 7, &base_validator_set)
        .expect("leader selection should succeed");
    let leader_endpoints_toml = format!(
        "[{}]",
        leader_endpoints
            .iter()
            .map(|endpoint| format!("\"{endpoint}\""))
            .collect::<Vec<_>>()
            .join(", ")
    );
    let validator_set = load_validator_set_from_str(&format!(
        r#"
epoch = 7

[[validators]]
validator_id = "0x{}"
consensus_pubkey = "0x{}"
network_pubkey = "0x1111"
rpc_endpoints = {}
region = "eu-west"
operator_name = "validator-nine"
enabled = true

[validators.bond]
asset = "USDC"
amount = 100
status = "Active"

[[validators]]
validator_id = "0x{}"
consensus_pubkey = "0x{}"
network_pubkey = "0x2222"
rpc_endpoints = {}
region = "eu-central"
operator_name = "validator-eight"
enabled = true

[validators.bond]
asset = "USDC"
amount = 100
status = "Active"
    "#,
        hex::encode(validator(9)),
        hex::encode(signing_key(9).verifying_key().to_bytes()),
        if elected_leader == validator(9) {
            &leader_endpoints_toml
        } else {
            "[\"http://127.0.0.1:1\"]"
        },
        hex::encode(validator(8)),
        hex::encode(signing_key(8).verifying_key().to_bytes()),
        if elected_leader == validator(8) {
            &leader_endpoints_toml
        } else {
            "[\"http://127.0.0.1:1\"]"
        }
    ))
    .expect("validator set should parse");
    let local_validator_id = if elected_leader == validator(8) {
        validator(9)
    } else {
        validator(8)
    };
    let local_signing_key = if local_validator_id == validator(9) {
        [9; 32]
    } else {
        [8; 32]
    };
    let bootstrap_peers =
        bootstrap_validator(&validator_set, local_validator_id).expect("bootstrap should work");
    let local_validator = bootstrap_peers.local.clone();
    let engine = SingleNodeEngine::new_with_validator_set(
        SingleNodeConfig {
            chain_id: 7,
            validator_id: local_validator_id,
            consensus_signing_key: local_signing_key,
            genesis_timestamp_ms: 1_000,
            genesis_state_root: [3; 32],
            pacemaker: kombat_chain_consensus::PacemakerConfig {
                base_timeout_ms: 300,
                max_timeout_ms: 20_000,
                max_exponent: 6,
                max_clock_skew_ms: 1_000,
            },
        },
        Some(&validator_set),
    );
    (
        engine,
        super::NetworkBootstrapConfig {
            validator_set,
            bootstrap_peers,
            local_validator: Some(local_validator),
            public_rpc_url: None,
        },
    )
}

fn observer_network_fixture_with_leader_endpoints(
    leader_endpoints: &[&str],
) -> (SingleNodeEngine, super::NetworkBootstrapConfig) {
    let (mut engine, mut network_bootstrap) =
        follower_network_fixture_with_leader_endpoints(leader_endpoints);
    engine.clear_local_validator_binding();
    network_bootstrap.local_validator = None;
    network_bootstrap.bootstrap_peers.peers = network_bootstrap
        .validator_set
        .active_validators()
        .iter()
        .map(kombat_chain_network::ValidatorPeer::from)
        .collect();
    (engine, network_bootstrap)
}

fn observer_network_fixture_with_validator_endpoints(
    validator_nine_endpoints: &[&str],
    validator_eight_endpoints: &[&str],
) -> (SingleNodeEngine, super::NetworkBootstrapConfig) {
    let validator_set = load_validator_set_from_str(&format!(
        r#"
epoch = 7

[[validators]]
validator_id = "0x{}"
consensus_pubkey = "0x{}"
network_pubkey = "0x1111"
rpc_endpoints = [{}]
region = "eu-west"
operator_name = "validator-nine"
enabled = true

[validators.bond]
asset = "USDC"
amount = 100
status = "Active"

[[validators]]
validator_id = "0x{}"
consensus_pubkey = "0x{}"
network_pubkey = "0x2222"
rpc_endpoints = [{}]
region = "eu-central"
operator_name = "validator-eight"
enabled = true

[validators.bond]
asset = "USDC"
amount = 100
status = "Active"
"#,
        hex::encode(validator(9)),
        hex::encode(signing_key(9).verifying_key().to_bytes()),
        validator_nine_endpoints
            .iter()
            .map(|endpoint| format!("\"{endpoint}\""))
            .collect::<Vec<_>>()
            .join(", "),
        hex::encode(validator(8)),
        hex::encode(signing_key(8).verifying_key().to_bytes()),
        validator_eight_endpoints
            .iter()
            .map(|endpoint| format!("\"{endpoint}\""))
            .collect::<Vec<_>>()
            .join(", "),
    ))
    .expect("validator set should parse");
    let bootstrap_peers =
        bootstrap_validator(&validator_set, validator(9)).expect("bootstrap should work");
    let mut engine = SingleNodeEngine::new_with_validator_set(
        SingleNodeConfig {
            chain_id: 7,
            validator_id: validator(9),
            consensus_signing_key: [9; 32],
            genesis_timestamp_ms: 1_000,
            genesis_state_root: [3; 32],
            pacemaker: kombat_chain_consensus::PacemakerConfig {
                base_timeout_ms: 300,
                max_timeout_ms: 20_000,
                max_exponent: 6,
                max_clock_skew_ms: 1_000,
            },
        },
        Some(&validator_set),
    );
    engine.clear_local_validator_binding();
    (
        engine,
        super::NetworkBootstrapConfig {
            validator_set: validator_set.clone(),
            bootstrap_peers: super::BootstrapPeers {
                local: bootstrap_peers.local,
                peers: validator_set
                    .active_validators()
                    .iter()
                    .map(kombat_chain_network::ValidatorPeer::from)
                    .collect(),
            },
            local_validator: None,
            public_rpc_url: None,
        },
    )
}

