fn timeout_ready_single_node_engine() -> (SingleNodeEngine, super::NetworkBootstrapConfig) {
    let mut engine = single_node_engine();
    let network_bootstrap = network_bootstrap_config();
    let validator_verifiers =
        super::network_validator_verifiers(&network_bootstrap).expect("validator set should work");
    let head = engine.head().clone();
    let local_signature = engine
        .sign_current_head_qc(block_hash(&head), head.header.round)
        .expect("local qc signature should exist");
    let signing_bytes = quorum_certificate_signing_bytes(&QuorumCertificate {
        view: head.header.round,
        block_hash: block_hash(&head),
        signatures: vec![],
    })
    .expect("qc signing bytes should exist");
    let follower_signature = Signature {
        validator: validator(8),
        bytes: consensus_signature_bytes(8, &signing_bytes),
    };
    let head_qc = assemble_quorum_certificate(
        &head,
        vec![local_signature, follower_signature],
        &validator_verifiers,
    )
    .expect("head qc should assemble");
    engine
        .install_head_qc(head_qc, &validator_verifiers)
        .expect("engine should accept quorum qc");
    (engine, network_bootstrap)
}

fn spawn_mock_json_rpc_server(
    response: JsonRpcResponse,
) -> (String, std::thread::JoinHandle<String>) {
    let listener = TcpListener::bind("127.0.0.1:0").expect("listener should bind");
    let address = listener.local_addr().expect("listener addr should exist");
    let join = std::thread::spawn(move || loop {
        let (mut stream, _) = listener.accept().expect("client should connect");
        let request = read_http_request(&mut stream).expect("request should parse");
        if request.method == "GET"
            && matches!(
                request.path.as_str(),
                "/network/bootstrap" | "/network/ping"
            )
        {
            let body = json!({
                "chain_id": 7,
                "current_round": 1,
                "head_height": 0,
                "head_hash_hex": format!("0x{}", hex::encode([0_u8; 32])),
            })
            .to_string();
            let raw_response = format!(
                "HTTP/1.1 200 OK\r\nContent-Type: application/json\r\nContent-Length: {}\r\n\r\n{}",
                body.len(),
                body
            );
            stream
                .write_all(raw_response.as_bytes())
                .expect("bootstrap response should write");
            continue;
        }

        let body = serde_json::to_string(&response).expect("response should serialize");
        let raw_response = format!(
            "HTTP/1.1 200 OK\r\nContent-Type: application/json\r\nContent-Length: {}\r\n\r\n{}",
            body.len(),
            body
        );
        stream
            .write_all(raw_response.as_bytes())
            .expect("response should write");
        break request.body;
    });
    (format!("http://{}", address), join)
}

