fn spawn_mock_json_rpc_server_first_post_disconnect_then_response(
    response: JsonRpcResponse,
) -> (String, std::thread::JoinHandle<Vec<HttpRequest>>) {
    let listener = TcpListener::bind("127.0.0.1:0").expect("listener should bind");
    let address = listener.local_addr().expect("listener addr should exist");
    let join = std::thread::spawn(move || {
        let mut posts = Vec::new();
        loop {
            let (mut stream, _) = listener.accept().expect("client should connect");
            let request = read_http_request(&mut stream).expect("request should parse");
            if request.method == "GET"
                && matches!(
                    request.path.as_str(),
                    "/network/bootstrap" | "/network/ping"
                )
            {
                let body = json!({
                    "chain_id": 7,
                    "current_round": 1,
                    "head_height": 0,
                    "head_hash_hex": format!("0x{}", hex::encode([0_u8; 32])),
                })
                .to_string();
                let raw_response = format!(
	                        "HTTP/1.1 200 OK\r\nContent-Type: application/json\r\nContent-Length: {}\r\n\r\n{}",
	                        body.len(),
	                        body
	                    );
                stream
                    .write_all(raw_response.as_bytes())
                    .expect("bootstrap response should write");
                continue;
            }

            if request.path.starts_with("/network/") {
                let body = r#"{"error":"test endpoint does not provide network control plane"}"#;
                let raw_response = format!(
	                        "HTTP/1.1 500 Internal Server Error\r\nContent-Type: application/json\r\nContent-Length: {}\r\n\r\n{}",
	                        body.len(),
	                        body
	                    );
                stream
                    .write_all(raw_response.as_bytes())
                    .expect("network error response should write");
                continue;
            }

            posts.push(request);
            if posts.len() == 1 {
                // Simulate the ambiguous transport case: the leader may have accepted the
                // write, but the submitter receives no response and must retry idempotently.
                continue;
            }

            let body = serde_json::to_string(&response).expect("response should serialize");
            let raw_response = format!(
                "HTTP/1.1 200 OK\r\nContent-Type: application/json\r\nContent-Length: {}\r\n\r\n{}",
                body.len(),
                body
            );
            stream
                .write_all(raw_response.as_bytes())
                .expect("response should write");
            break posts;
        }
    });
    (format!("http://{}", address), join)
}

