fn spawn_mock_x402_facilitator() -> (String, std::thread::JoinHandle<Vec<HttpRequest>>) {
    let listener = TcpListener::bind("127.0.0.1:0").expect("listener should bind");
    listener
        .set_nonblocking(true)
        .expect("listener should be nonblocking");
    let address = listener.local_addr().expect("listener addr should exist");
    let join = std::thread::spawn(move || {
        let deadline = Instant::now() + Duration::from_secs(2);
        let mut requests = Vec::new();
        while requests.len() < 2 && Instant::now() < deadline {
            match listener.accept() {
                Ok((mut stream, _)) => {
                    let request =
                        read_http_request(&mut stream).expect("facilitator request should parse");
                    let body = match request.path.as_str() {
                        "/verify" => json!({
                            "isValid": true,
                            "payer": "0x0000000000000000000000000000000000000003",
                        }),
                        "/settle" => json!({
                            "success": true,
                            "transaction": "0xsettled",
                            "network": "eip155:84532",
                            "amount": "1000",
                        }),
                        other => panic!("unexpected facilitator path: {other}"),
                    }
                    .to_string();
                    let raw_response = format!(
                        "HTTP/1.1 200 OK\r\nContent-Type: application/json\r\nContent-Length: {}\r\n\r\n{}",
                        body.len(),
                        body
                    );
                    stream
                        .write_all(raw_response.as_bytes())
                        .expect("facilitator response should write");
                    requests.push(request);
                }
                Err(error) if error.kind() == std::io::ErrorKind::WouldBlock => {
                    std::thread::sleep(Duration::from_millis(10));
                }
                Err(error) => panic!("facilitator accept failed: {error}"),
            }
        }
        requests
    });
    (format!("http://{}", address), join)
}

