#[test]
fn x402_header_values_round_trip() {
    let encoded = encode_x402_header_value(&json!({
        "x402Version": X402_VERSION,
        "accepts": [],
    }))
    .expect("x402 header should encode");
    let decoded = decode_x402_header_value(&encoded).expect("x402 header should decode");
    assert_eq!(decoded["x402Version"], json!(X402_VERSION));
    assert_eq!(decoded["accepts"], json!([]));
}

#[test]
fn json_rpc_x402_missing_payment_returns_402_challenge() {
    let server = JsonRpcHttpServer::new(Arc::new(Mutex::new(single_node_engine())))
        .with_x402_config(Some(test_x402_config(&[], true)));
    let response = server
        .handle_json_http_request_with_headers(&chain_info_request_body(42), &BTreeMap::new());

    assert_eq!(response.status.as_u16(), 402);
    let challenge = response
        .headers
        .get(X402_PAYMENT_REQUIRED_HEADER)
        .expect("payment challenge header should exist");
    let decoded = decode_x402_header_value(challenge).expect("challenge should decode");
    assert_eq!(decoded["x402Version"], json!(X402_VERSION));
    assert_eq!(decoded["resource"]["mimeType"], json!("application/json"));
    assert_eq!(decoded["accepts"][0]["amount"], json!("1000"));

    let rpc: JsonRpcResponse =
        serde_json::from_str(&response.body).expect("json-rpc body should decode");
    let error = rpc
        .error
        .expect("missing payment should return json-rpc error");
    assert_eq!(error.code, -32042);
    assert_eq!(error.message, "payment required");
}

#[test]
fn json_rpc_x402_accepts_unverified_payment_for_configured_tests() {
    let config = test_x402_config(&[], true);
    let payment_payload = json!({
        "x402Version": X402_VERSION,
        "accepted": config.accepts[0],
        "payload": {
            "signature": "test-signature",
        },
    });
    let mut headers = BTreeMap::new();
    headers.insert(
        X402_PAYMENT_SIGNATURE_HEADER_LOWER.into(),
        encode_x402_header_value(&payment_payload).expect("payment should encode"),
    );
    let server = JsonRpcHttpServer::new(Arc::new(Mutex::new(single_node_engine())))
        .with_x402_config(Some(config));

    let response =
        server.handle_json_http_request_with_headers(&chain_info_request_body(43), &headers);

    assert_eq!(response.status.as_u16(), 200);
    let payment_response = response
        .headers
        .get(X402_PAYMENT_RESPONSE_HEADER)
        .expect("payment response header should exist");
    let decoded =
        decode_x402_header_value(payment_response).expect("payment response should decode");
    assert_eq!(decoded["success"], json!(true));
    assert_eq!(decoded["verified"], json!(false));

    let rpc: JsonRpcResponse =
        serde_json::from_str(&response.body).expect("json-rpc body should decode");
    assert!(rpc.error.is_none());
    assert!(rpc.result.is_some());
}

#[test]
fn json_rpc_x402_unprotected_method_bypasses_payment() {
    let server = JsonRpcHttpServer::new(Arc::new(Mutex::new(single_node_engine())))
        .with_x402_config(Some(test_x402_config(&["kombat_submitIntent"], true)));

    let response = server
        .handle_json_http_request_with_headers(&chain_info_request_body(44), &BTreeMap::new());

    assert_eq!(response.status.as_u16(), 200);
    assert!(!response.headers.contains_key(X402_PAYMENT_REQUIRED_HEADER));
    assert!(!response.headers.contains_key(X402_PAYMENT_RESPONSE_HEADER));
    let rpc: JsonRpcResponse =
        serde_json::from_str(&response.body).expect("json-rpc body should decode");
    assert!(rpc.error.is_none());
}

#[test]
fn json_rpc_x402_verifies_and_settles_with_facilitator() {
    let (facilitator_url, facilitator) = spawn_mock_x402_facilitator();
    let mut config = test_x402_config(&[], false);
    config.facilitator_url = Some(facilitator_url);
    let payment_payload = json!({
        "x402Version": X402_VERSION,
        "accepted": config.accepts[0],
        "payload": {
            "authorization": "signed-payment",
        },
    });
    let mut headers = BTreeMap::new();
    headers.insert(
        X402_PAYMENT_SIGNATURE_HEADER_LOWER.into(),
        encode_x402_header_value(&payment_payload).expect("payment should encode"),
    );
    let server = JsonRpcHttpServer::new(Arc::new(Mutex::new(single_node_engine())))
        .with_x402_config(Some(config));

    let response =
        server.handle_json_http_request_with_headers(&chain_info_request_body(45), &headers);

    assert_eq!(response.status.as_u16(), 200);
    let payment_response = response
        .headers
        .get(X402_PAYMENT_RESPONSE_HEADER)
        .expect("payment response header should exist");
    let decoded =
        decode_x402_header_value(payment_response).expect("payment response should decode");
    assert_eq!(decoded["success"], json!(true));
    assert_eq!(decoded["transaction"], json!("0xsettled"));

    let requests = facilitator
        .join()
        .expect("facilitator thread should complete");
    assert_eq!(requests.len(), 2);
    assert_eq!(requests[0].path, "/verify");
    assert_eq!(requests[1].path, "/settle");
    let verify_body: Value =
        serde_json::from_str(&requests[0].body).expect("verify body should decode");
    assert_eq!(verify_body["x402Version"], json!(X402_VERSION));
    assert_eq!(verify_body["paymentRequirements"]["amount"], json!("1000"));
    assert_eq!(
        verify_body["paymentPayload"]["x402Version"],
        json!(X402_VERSION)
    );
}

fn spawn_mock_peer_transport_bootstrap_server() -> (String, std::thread::JoinHandle<String>) {
    let listener = TcpListener::bind("127.0.0.1:0").expect("listener should bind");
    let address = listener.local_addr().expect("listener addr should exist");
    let join = std::thread::spawn(move || {
        let (mut stream, _) = listener.accept().expect("client should connect");
        let mut magic = [0_u8; PEER_TRANSPORT_MAGIC.len()];
        stream
            .read_exact(&mut magic)
            .expect("peer transport magic should read");
        assert_eq!(magic, *PEER_TRANSPORT_MAGIC);
        let session_open =
            read_peer_transport_request(&mut stream).expect("peer transport request should parse");
        assert_eq!(session_open.path, "/network/session/open");
        let session_open_body: PeerTransportSessionOpenRequest =
            serde_json::from_str(&session_open.body)
                .expect("peer transport session open request should parse");
        assert_eq!(session_open_body.chain_id, Some(7));
        assert!(
            session_open_body
                .validator_id_hex
                .as_deref()
                .is_some_and(|validator_id| validator_id.starts_with("0x")),
            "peer transport session open request should include validator id metadata"
        );
        assert_eq!(session_open_body.current_round, Some(1));
        assert_eq!(session_open_body.current_view, Some(0));
        assert_eq!(session_open_body.head_height, Some(0));
        let opened_head_hash_hex = session_open_body
            .head_hash_hex
            .clone()
            .expect("session open should include head hash");
        assert_eq!(session_open_body.last_committed_round, Some(0));
        assert_eq!(session_open_body.peer_count, Some(1));
        write_peer_transport_response(
            &mut stream,
            &PeerTransportResponse {
                body: Some(
                    json!({
                        "session_id": 1,
                        "chain_id": 7,
                        "validator_id_hex": format!("0x{}", hex::encode([8_u8; 32])),
                        "current_round": 1,
                        "current_view": 0,
                        "head_height": 0,
                        "head_hash_hex": opened_head_hash_hex.clone(),
                        "last_committed_round": 0,
                        "peer_count": 1,
                    })
                    .to_string(),
                ),
                error: None,
            },
        )
        .expect("peer transport session open response should write");
        let request =
            read_peer_transport_request(&mut stream).expect("peer transport request should parse");
        let response_body = if request.path == "/network/session/heartbeat" {
            let heartbeat_request: PeerTransportSessionHeartbeatRequest =
                serde_json::from_str(&request.body)
                    .expect("peer transport heartbeat request should parse");
            assert_eq!(heartbeat_request.chain_id, Some(7));
            assert!(
                heartbeat_request
                    .validator_id_hex
                    .as_deref()
                    .is_some_and(|validator_id| validator_id.starts_with("0x")),
                "peer transport heartbeat request should include validator id metadata"
            );
            assert_eq!(heartbeat_request.current_round, Some(1));
            assert_eq!(heartbeat_request.current_view, Some(0));
            assert_eq!(heartbeat_request.head_height, Some(0));
            assert_eq!(
                heartbeat_request.head_hash_hex,
                Some(opened_head_hash_hex.clone())
            );
            assert_eq!(heartbeat_request.last_committed_round, Some(0));
            assert_eq!(heartbeat_request.peer_count, Some(1));
            json!({
                "alive": true,
                "session_id": 1,
                "chain_id": 7,
                "validator_id_hex": format!("0x{}", hex::encode([8_u8; 32])),
                "current_round": 2,
                "current_view": 1,
                "head_height": 1,
                "head_hash_hex": format!("0x{}", hex::encode([1_u8; 32])),
                "last_committed_round": 1,
                "peer_count": 1,
            })
            .to_string()
        } else {
            json!({
                "chain_id": 7,
                "current_round": 1,
                "head_height": 0,
                "head_hash_hex": format!("0x{}", hex::encode([0_u8; 32])),
                "snapshot_path": Value::Null,
            })
            .to_string()
        };
        write_peer_transport_response(
            &mut stream,
            &PeerTransportResponse {
                body: Some(response_body),
                error: None,
            },
        )
        .expect("peer transport response should write");
        request.path
    });
    (format!("http://{}", address), join)
}

fn authorized_json_rpc_response(
    server: JsonRpcHttpServer,
    request: &JsonRpcRequest,
    token: &str,
) -> JsonRpcResponse {
    let body = serde_json::to_string(request).expect("request should serialize");
    let raw_request = format!(
        "POST / HTTP/1.1\r\nHost: localhost\r\nAuthorization: Bearer {token}\r\nContent-Type: application/json\r\nContent-Length: {}\r\n\r\n{}",
        body.len(),
        body
    );
    let listener = TcpListener::bind("127.0.0.1:0").expect("listener should bind");
    let address = listener.local_addr().expect("listener addr should exist");
    let server_thread = std::thread::spawn(move || {
        let (mut stream, _) = listener.accept().expect("client should connect");
        server
            .handle_http_connection(&mut stream)
            .expect("http connection should succeed");
    });
    let mut client = TcpStream::connect(address).expect("client should connect");
    client
        .write_all(raw_request.as_bytes())
        .expect("request should write");
    let mut raw_response = String::new();
    client
        .read_to_string(&mut raw_response)
        .expect("response should read");
    server_thread.join().expect("server thread should join");
    serde_json::from_str(
        raw_response
            .split_once("\r\n\r\n")
            .expect("http response should contain headers")
            .1,
    )
    .expect("response should parse")
}

fn raw_http_response(server: JsonRpcHttpServer, request: &str) -> Vec<u8> {
    let listener = TcpListener::bind("127.0.0.1:0").expect("listener should bind");
    let address = listener.local_addr().expect("listener addr should exist");
    let server_thread = std::thread::spawn(move || {
        let (mut stream, _) = listener.accept().expect("client should connect");
        server
            .handle_http_connection(&mut stream)
            .expect("http connection should succeed");
    });
    let mut client = TcpStream::connect(address).expect("client should connect");
    client
        .write_all(request.as_bytes())
        .expect("request should write");
    let mut raw_response = Vec::new();
    client
        .read_to_end(&mut raw_response)
        .expect("response should read");
    server_thread.join().expect("server thread should join");
    raw_response
}

fn reserve_local_endpoint() -> String {
    let listener = TcpListener::bind("127.0.0.1:0").expect("listener should bind");
    let address = listener.local_addr().expect("listener addr should exist");
    drop(listener);
    format!("http://{address}")
}

fn wait_for_http_server(endpoint: &str) {
    let address = endpoint
        .strip_prefix("http://")
        .expect("test endpoint should use http scheme");
    let request =
        format!("GET /network/ping HTTP/1.1\r\nHost: {address}\r\nConnection: close\r\n\r\n");
    let deadline = Instant::now() + Duration::from_secs(2);
    loop {
        match TcpStream::connect(address) {
            Ok(mut stream) => {
                stream
                    .set_read_timeout(Some(Duration::from_millis(250)))
                    .expect("readiness read timeout should set");
                stream
                    .set_write_timeout(Some(Duration::from_millis(250)))
                    .expect("readiness write timeout should set");
                stream
                    .write_all(request.as_bytes())
                    .expect("readiness request should write");
                let mut response = Vec::new();
                stream
                    .read_to_end(&mut response)
                    .expect("readiness response should read");
                if response.starts_with(b"HTTP/1.1") {
                    return;
                }
                std::thread::sleep(Duration::from_millis(20));
            }
            Err(_) if Instant::now() < deadline => {
                std::thread::sleep(Duration::from_millis(20));
            }
            Err(error) => panic!("server at {endpoint} did not become ready: {error}"),
        }
        if Instant::now() >= deadline {
            panic!("server at {endpoint} did not become ready before timeout");
        }
    }
}

fn mahi_network_bootstrap_configs(
    endpoints: &[(u8, String)],
) -> BTreeMap<u8, super::NetworkBootstrapConfig> {
    let validators_toml = endpoints
        .iter()
        .map(|(byte, endpoint)| {
            format!(
                r#"
[[validators]]
validator_id = "0x{}"
consensus_pubkey = "0x{}"
network_pubkey = "0x{:04x}"
rpc_endpoints = ["{}"]
region = "test-region-{}"
operator_name = "validator-{}"
enabled = true

[validators.bond]
asset = "USDC"
amount = 100
status = "Active"
"#,
                hex::encode(validator(*byte)),
                hex::encode(signing_key(*byte).verifying_key().to_bytes()),
                byte,
                endpoint,
                byte,
                byte,
            )
        })
        .collect::<Vec<_>>()
        .join("\n");
    let validator_set = load_validator_set_from_str(&format!("epoch = 7\n{validators_toml}"))
        .expect("validator set should parse");
    endpoints
        .iter()
        .map(|(byte, endpoint)| {
            let bootstrap_peers = bootstrap_validator(&validator_set, validator(*byte))
                .expect("bootstrap should succeed");
            let local_validator = bootstrap_peers.local.clone();
            (
                *byte,
                super::NetworkBootstrapConfig {
                    validator_set: validator_set.clone(),
                    bootstrap_peers,
                    local_validator: Some(local_validator),
                    public_rpc_url: Some(endpoint.clone()),
                },
            )
        })
        .collect()
}

fn start_mahi_servers() -> Vec<(u8, JsonRpcHttpServer)> {
    start_mahi_servers_with_engine_setup(|_, _| {})
}

fn start_mahi_servers_with_engine_setup<F>(mut setup_engine: F) -> Vec<(u8, JsonRpcHttpServer)>
where
    F: FnMut(u8, &mut SingleNodeEngine),
{
    let endpoints = [1_u8, 2, 3, 4]
        .into_iter()
        .map(|byte| (byte, reserve_local_endpoint()))
        .collect::<Vec<_>>();
    let configs = mahi_network_bootstrap_configs(&endpoints);
    let mut servers = Vec::new();
    for (byte, endpoint) in endpoints {
        let network_bootstrap = configs
            .get(&byte)
            .expect("bootstrap config should exist")
            .clone();
        let mut engine = SingleNodeEngine::new_with_validator_set(
            SingleNodeConfig {
                chain_id: 7,
                validator_id: validator(byte),
                consensus_signing_key: [byte; 32],
                genesis_timestamp_ms: 1_000,
                genesis_state_root: [3; 32],
                pacemaker: kombat_chain_consensus::PacemakerConfig {
                    base_timeout_ms: 300,
                    max_timeout_ms: 20_000,
                    max_exponent: 6,
                    max_clock_skew_ms: 1_000,
                },
            },
            Some(&network_bootstrap.validator_set),
        );
        setup_engine(byte, &mut engine);
        let server = JsonRpcHttpServer::new_with_config(
            Arc::new(Mutex::new(engine)),
            JsonRpcServerConfig {
                manual_block_production_enabled: false,
                mahi_enabled: true,
                operator_bearer_token: Some("mahi-token".into()),
                peer_relay_bearer_token: None,
                network_bootstrap: Some(network_bootstrap),
                peer_transport_enabled: false,
            },
        );
        let listen_address = endpoint
            .strip_prefix("http://")
            .expect("endpoint should have http scheme")
            .to_string();
        let serve_server = server.clone();
        std::thread::spawn(move || {
            serve_server
                .serve(&listen_address)
                .expect("mahi test server should serve");
        });
        servers.push((byte, server));
    }
    std::thread::sleep(Duration::from_millis(150));
    servers
}

fn single_validator_mahi_bootstrap(byte: u8) -> super::NetworkBootstrapConfig {
    let validator_set = load_validator_set_from_str(&format!(
        r#"
epoch = 7

[[validators]]
validator_id = "0x{}"
consensus_pubkey = "0x{}"
network_pubkey = "0x{}"
rpc_endpoints = ["http://127.0.0.1:1"]
region = "local"
operator_name = "validator-{byte}"
enabled = true

[validators.bond]
asset = "USDC"
amount = 100
status = "Active"
"#,
        hex::encode(validator(byte)),
        hex::encode(signing_key(byte).verifying_key().to_bytes()),
        hex::encode([byte; 2]),
    ))
    .expect("single-validator set should parse");
    let bootstrap_peers =
        bootstrap_validator(&validator_set, validator(byte)).expect("bootstrap should succeed");
    let local_validator = bootstrap_peers.local.clone();
    super::NetworkBootstrapConfig {
        validator_set,
        bootstrap_peers,
        local_validator: Some(local_validator),
        public_rpc_url: None,
    }
}

