fn seed_pnl_funding_position(
    engine: &mut SingleNodeEngine,
    market_id: u64,
    long_account: u64,
    short_account: u64,
) {
    list_fast_funding_pnl_market(engine, market_id);
    for account_id in [long_account, short_account, 44] {
        engine.set_isolated_collateral(market_id, account_id, 50_000);
    }
    engine.update_market_index_price(market_id, 100_000, 1_000);
    engine.update_market_mark_price(market_id, 101_000, 1_000);
    engine
        .submit_order(
            OrderRequest {
                market_id,
                account_id: long_account,
                client_order_id: 1,
                side: OrderSide::Bid,
                quantity_lots: 3,
                kind: OrderKind::Limit {
                    price_ticks: 101_000,
                },
                time_in_force: TimeInForce::Gtc,
                post_only: false,
            },
            1_001,
        )
        .expect("long bid should rest");
    engine
        .submit_order(
            OrderRequest {
                market_id,
                account_id: short_account,
                client_order_id: 2,
                side: OrderSide::Ask,
                quantity_lots: 3,
                kind: OrderKind::Limit {
                    price_ticks: 101_000,
                },
                time_in_force: TimeInForce::Ioc,
                post_only: false,
            },
            1_002,
        )
        .expect("short ask should fill");
}

fn signed_intent(
    signer: &SigningKey,
    nonce: u64,
    expires_at: u64,
    kind: IntentKind,
) -> SignedIntent {
    signed_intent_for_policy(signer, 42, 11, nonce, expires_at, kind)
}

fn signed_intent_for_policy(
    signer: &SigningKey,
    policy_id: u64,
    account: u64,
    nonce: u64,
    expires_at: u64,
    kind: IntentKind,
) -> SignedIntent {
    let intent = Intent {
        chain_id: 7,
        account,
        policy_id,
        nonce,
        expires_at,
        predicate: None,
        kind,
    };
    let session_payload = SessionPayload {
        intent_hash: intent_signing_hash(&intent),
        policy_id,
        chain_id: 7,
    };
    let signature = signer
        .sign(&borsh::to_vec(&session_payload).expect("session payload should serialize"))
        .to_bytes();

    SignedIntent { intent, signature }
}

