fn signed_evm_owner_call_json(
    secret: &secp256k1::SecretKey,
    address: [u8; 20],
    account_id: u64,
    chain_id: u64,
    nonce: u64,
    action_json: OwnerActionJson,
) -> Value {
    use secp256k1::Secp256k1;

    let action = match &action_json {
        OwnerActionJson::CreatePolicy {
            policy_id,
            grantee_hex,
            expires_at,
            terms,
        } => OwnerAction::CreatePolicy {
            policy_id: *policy_id,
            grantee: hex::decode(grantee_hex.trim_start_matches("0x"))
                .expect("grantee hex should decode")
                .try_into()
                .expect("grantee should be 32 bytes"),
            expires_at: *expires_at,
            terms: PolicyTerms {
                gas_budget_per_day: terms.gas_budget_per_day,
                gas_refill_per_day: terms.gas_refill_per_day,
                max_intents_per_second: terms.max_intents_per_second,
                max_intents_per_day: terms.max_intents_per_day,
                max_volume_per_day: terms.max_volume_per_day,
                max_drawdown_pct: terms.max_drawdown_pct,
                ..PolicyTerms::default()
            },
        },
        _ => unreachable!("test helper only supports create_policy"),
    };
    let signer = evm_owner_principal(address);
    let call = OwnerCall {
        signer,
        nonce,
        action,
    };
    let digest = evm_owner_call_eip712_digest(account_id, chain_id, &call)
        .expect("EVM owner call should hash");
    let signature =
        Secp256k1::new().sign_ecdsa_recoverable(&secp256k1::Message::from_digest(digest), secret);
    let (recovery_id, compact) = signature.serialize_compact();
    let mut signature_bytes = Vec::from(compact);
    signature_bytes.push(i32::from(recovery_id) as u8 + 27);

    serde_json::to_value(SignedEvmOwnerCallJson {
        account_id,
        chain_id,
        call: OwnerCallJson {
            signer_hex: encode_hex(&signer),
            nonce,
            action: action_json,
        },
        signature_hex: encode_hex(&signature_bytes),
    })
    .expect("signed EVM owner call should serialize")
}

fn signed_evm_mandate_action_json(
    secret: &secp256k1::SecretKey,
    address: [u8; 20],
    chain_id: u64,
    nonce: u64,
    valid_until_ms: u64,
    action_json: MandateActionJson,
) -> SignedEvmMandateActionJson {
    let owner = evm_owner_principal(address);
    let action =
        super::mandate_action_from_json(owner, &action_json).expect("mandate action should decode");
    let digest = evm_mandate_action_eip712_digest(chain_id, owner, nonce, valid_until_ms, &action)
        .expect("EVM mandate action should hash");
    SignedEvmMandateActionJson {
        chain_id,
        owner_hex: encode_hex(&owner),
        nonce,
        valid_until_ms,
        action: action_json,
        signature_hex: evm_signature_hex(secret, digest),
    }
}

fn signed_evm_delegation_action_json(
    secret: &secp256k1::SecretKey,
    chain_id: u64,
    signer_account_id: u64,
    action: BlockDelegationAction,
    timestamp_ms: u64,
    submitter_nonce: u64,
    valid_until_ms: u64,
) -> SignedEvmDelegationActionJson {
    let action_id =
        super::delegation_action_id_for_submission(&action, timestamp_ms, Some(submitter_nonce));
    let signed = SignedEvmDelegationAction {
        chain_id,
        signer_account_id,
        action_id,
        action: action.clone(),
        timestamp_ms,
        submitter_nonce,
        valid_until_ms,
        signature: Vec::new(),
    };
    let digest =
        evm_delegation_action_eip712_digest(&signed).expect("EVM delegation action should hash");
    SignedEvmDelegationActionJson {
        chain_id,
        signer_account_id,
        action_id_hex: encode_hex(&action_id),
        action_hex: super::encode_borsh_hex(&action),
        timestamp_ms,
        submitter_nonce,
        valid_until_ms,
        signature_hex: evm_signature_hex(secret, digest),
    }
}

