#[test]
fn returns_read_only_contract_call_projection() {
    let store = InMemoryStateStore::new();
    let root = store.committed_root();
    let executor = BlockExecutor::new(7, store);
    let mut service = RpcService::new(7, executor);
    service.set_head(head_block(root));

    let response = service
        .eth_call(&ContractCallRequest {
            caller: [1; 20],
            to: evm_usdc_system_address_bytes(),
            data: encode_address_arg([0x70, 0xa0, 0x82, 0x31], [9; 20]),
            gas_limit: 50_000,
        })
        .expect("eth_call should succeed");

    assert_eq!(response.state_root, root);
    assert!(response.gas_used > 0);
    assert_eq!(response.returned, vec![0_u8; 32]);
}

