#[test]
fn node_rpc_can_seed_policy_usdc_balance_and_minter_role() {
    let mut engine = single_node_engine();
    let address = [0x11; 20];
    let mut service = NodeRpcService::new(&mut engine);

    let balance_response = service
        .set_policy_usdc_balance(address, U256::from(1_250_u64))
        .expect("policy usdc balance seed should succeed");
    assert_eq!(balance_response.balance, "1250");
    let wallet_balances = service.get_wallet_balances(address);
    assert_eq!(wallet_balances.policy_usdc_balance, "1250");
    assert_eq!(wallet_balances.evm_usdc_balance, "0");

    assert_eq!(
        service
            .engine
            .get_committed_state(&policy_usdc_balance_state_key(address)),
        Some(U256::from(1_250_u64).to_be_bytes::<32>().to_vec())
    );

    let role_response = service
        .set_evm_usdc_minter(address, true)
        .expect("minter role grant should succeed");
    assert!(role_response.enabled);

    assert_eq!(
        service
            .engine
            .get_committed_state(&evm_usdc_minter_role_state_key(address)),
        Some(vec![1_u8])
    );

    let role_response = service
        .set_evm_usdc_minter(address, false)
        .expect("minter role revoke should succeed");
    assert!(!role_response.enabled);

    assert_eq!(
        service
            .engine
            .get_committed_state(&evm_usdc_minter_role_state_key(address)),
        None
    );
}

