#[test]
fn node_rpc_faucet_tops_up_policy_and_evm_usdc() {
    with_env_vars(
        &[(
            FAUCET_OPERATOR_PRIVATE_KEY_ENV,
            Some(encode_hex(&[0x44; 32])),
        )],
        || {
            let mut engine = single_node_engine();
            let address = [0x22; 20];
            let mut service = NodeRpcService::new(&mut engine);

            let response = service
                .faucet_fund_account(address, U256::from(1_000_u64), U256::from(250_u64))
                .expect("faucet funding should succeed");
            assert_eq!(response.policy_usdc_balance, "1000");
            assert_eq!(response.evm_usdc_balance, "250");
            assert_eq!(response.evm_usdc_total_supply, "250");
            let tx_hash = response
                .evm_usdc_deposit_tx_hash
                .expect("evm faucet top-up should return tx hash");
            let (receipt, _) = service
                .eth_get_transaction_receipt(tx_hash)
                .expect("receipt lookup should succeed")
                .expect("receipt should be indexed");
            assert!(receipt.success);
            assert_eq!(receipt.to, Some(evm_usdc_system_address_bytes()));
            assert_eq!(receipt.logs.len(), 2);

            let response = service
                .faucet_fund_account(address, U256::from(500_u64), U256::from(100_u64))
                .expect("smaller repeated faucet request should be idempotent");
            assert_eq!(response.policy_usdc_balance, "1000");
            assert_eq!(response.evm_usdc_balance, "250");
            assert_eq!(response.evm_usdc_total_supply, "250");
            assert_eq!(response.evm_usdc_deposit_tx_hash, None);

            assert_eq!(
                service
                    .engine
                    .get_committed_state(&policy_usdc_balance_state_key(address)),
                Some(U256::from(1_000_u64).to_be_bytes::<32>().to_vec())
            );
            assert_eq!(
                service
                    .engine
                    .get_committed_state(&evm_usdc_balance_state_key(address)),
                Some(U256::from(250_u64).to_be_bytes::<32>().to_vec())
            );
            assert_eq!(
                service
                    .engine
                    .get_committed_state(&evm_usdc_total_supply_state_key()),
                Some(U256::from(250_u64).to_be_bytes::<32>().to_vec())
            );

            let err = service
                .faucet_fund_account(
                    address,
                    U256::from(MAX_FAUCET_POLICY_USDC_MICRO) + U256::from(1_u64),
                    U256::from(0_u64),
                )
                .expect_err("policy faucet cap should be enforced");
            assert_eq!(
                err,
                RpcError::InvalidRequest("policy_usdc exceeds faucet cap")
            );
        },
    );
}

#[test]
fn json_rpc_faucet_enforces_limiter() {
    with_env_vars(&[], || {
        let server = JsonRpcHttpServer::new(Arc::new(Mutex::new(single_node_engine())))
            .with_faucet_limiter(FaucetLimiter::in_memory_for_tests(
                86_400, 3_600, 1, 60, 100,
            ));
        let first = serde_json::to_string(&JsonRpcRequest {
            jsonrpc: "2.0".into(),
            method: "kombat_faucetFundAccount".into(),
            params: json!({
                "address_hex": encode_hex(&[0x33; 20]),
                "policy_usdc": "0",
                "evm_usdc": "0",
            }),
            id: json!(1),
        })
        .expect("request should serialize");
        let second = serde_json::to_string(&JsonRpcRequest {
            jsonrpc: "2.0".into(),
            method: "kombat_faucetFundAccount".into(),
            params: json!({
                "address_hex": encode_hex(&[0x44; 20]),
                "policy_usdc": "0",
                "evm_usdc": "0",
            }),
            id: json!(2),
        })
        .expect("request should serialize");
        let headers = BTreeMap::from([("x-forwarded-for".to_string(), "203.0.113.8".to_string())]);

        let response: Value =
            serde_json::from_str(&server.handle_json_request_with_headers(&first, &headers))
                .expect("first response should decode");
        assert!(response.get("result").is_some());
        assert!(response["result"]["evm_usdc_deposit_tx_hash"].is_null());

        let response: Value =
            serde_json::from_str(&server.handle_json_request_with_headers(&second, &headers))
                .expect("second response should decode");
        assert_eq!(response["error"]["code"], -32011);
        assert_eq!(response["error"]["data"]["reason"], "ip rate limit");
    });
}

#[test]
fn json_rpc_faucet_waits_for_consensus_block_item() {
    let engine = Arc::new(Mutex::new(single_node_engine()));
    let server = JsonRpcHttpServer::new_with_config(
        engine.clone(),
        JsonRpcServerConfig {
            manual_block_production_enabled: false,
            mahi_enabled: false,
            operator_bearer_token: None,
            peer_relay_bearer_token: None,
            network_bootstrap: None,
            peer_transport_enabled: false,
        },
    )
    .with_faucet_limiter(FaucetLimiter::in_memory_for_tests(
        86_400, 3_600, 10, 60, 100,
    ));
    let address = [0x66; 20];
    let body = serde_json::to_string(&JsonRpcRequest {
        jsonrpc: "2.0".into(),
        method: "kombat_faucetFundAccount".into(),
        params: json!({
            "address_hex": encode_hex(&address),
            "policy_usdc": "1000",
            "evm_usdc": "250",
            "wait_timeout_ms": 1_000,
        }),
        id: json!(7_107),
    })
    .expect("request should serialize");
    let producer_engine = engine.clone();
    let producer = std::thread::spawn(move || {
        let deadline = Instant::now() + Duration::from_secs(2);
        loop {
            let mut guard = producer_engine.lock().expect("engine lock should succeed");
            if guard.pending_faucet_grant_count() > 0 {
                guard
                    .produce_block_from_mempool(1_100, 1)
                    .expect("queued faucet grant should commit");
                break;
            }
            drop(guard);
            assert!(
                Instant::now() < deadline,
                "faucet grant did not become pending before test deadline"
            );
            std::thread::sleep(Duration::from_millis(5));
        }
    });

    let response: JsonRpcResponse =
        serde_json::from_str(&server.handle_json_request(&body)).expect("response should parse");
    producer.join().expect("producer should join");
    assert!(response.error.is_none(), "{:?}", response.error);
    let result = response.result.expect("result should exist");
    assert_eq!(result["policy_usdc_balance"], "1000");
    assert_eq!(result["evm_usdc_balance"], "250");
    assert_eq!(result["evm_usdc_total_supply"], "250");
    assert!(result["evm_usdc_deposit_tx_hash"].is_null());
}

#[test]
fn json_rpc_faucet_forwarding_retries_when_timeout_recovery_unavailable() {
    let address = [0x77; 20];
    let leader_response = JsonRpcResponse {
        jsonrpc: "2.0".into(),
        result: Some(faucet_fund_account_response_to_json(
            &FaucetFundAccountResponse {
                address,
                policy_usdc_balance: "1000".into(),
                evm_usdc_balance: "250".into(),
                evm_usdc_total_supply: "250".into(),
                evm_usdc_deposit_tx_hash: None,
                state_root: [9; 32],
            },
        )),
        error: None,
        id: json!(7_108),
    };
    let (leader_endpoint, join) =
        spawn_mock_json_rpc_server_first_post_disconnect_then_response(leader_response);
    let (engine, network_bootstrap) = follower_network_fixture(&leader_endpoint);
    let server = JsonRpcHttpServer::new_with_config(
        Arc::new(Mutex::new(engine)),
        JsonRpcServerConfig {
            manual_block_production_enabled: false,
            mahi_enabled: false,
            operator_bearer_token: None,
            peer_relay_bearer_token: None,
            network_bootstrap: Some(network_bootstrap),
            peer_transport_enabled: false,
        },
    );
    let body = serde_json::to_string(&JsonRpcRequest {
        jsonrpc: "2.0".into(),
        method: "kombat_faucetFundAccount".into(),
        params: json!({
            "address_hex": encode_hex(&address),
            "policy_usdc": "1000",
            "evm_usdc": "250",
            "wait_timeout_ms": 0,
        }),
        id: json!(7_108),
    })
    .expect("request should serialize");

    let forwarded: JsonRpcResponse = with_env_vars(
        &[(super::NETWORK_SUBMIT_FORWARDING_ENV, Some("1".into()))],
        || serde_json::from_str(&server.handle_json_request(&body)).expect("response should parse"),
    );

    assert!(forwarded.error.is_none(), "{:?}", forwarded.error);
    let result = forwarded.result.expect("result should exist");
    assert_eq!(result["policy_usdc_balance"], "1000");
    assert_eq!(result["evm_usdc_balance"], "250");
    let requests = join.join().expect("mock leader should join");
    assert_eq!(
        requests.len(),
        2,
        "forwarder should retry after ambiguous leader response"
    );
    assert!(requests.iter().all(|request| request
        .body
        .contains("\"method\":\"kombat_faucetFundAccount\"")));
}

#[test]
fn faucet_limiter_redis_enforces_limits_when_configured() {
    let Ok(redis_url) = env::var("KOMBAT_FAUCET_REDIS_TEST_URL") else {
        return;
    };
    let limiter = FaucetLimiter {
        mode: FaucetLimiterMode::Redis(
            redis::Client::open(redis_url).expect("redis test url should parse"),
        ),
        address_cooldown_secs: 30,
        ip_window_secs: 30,
        ip_max_claims: 1,
        global_window_secs: 30,
        global_max_claims: 1_000_000,
    };
    let suffix = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .expect("clock should be monotonic")
        .as_nanos();
    let client_id = format!("redis-test-{suffix}");
    let first_address = format!("0x{suffix:040x}");
    let second_address = format!("0x{:040x}", suffix.saturating_add(1));

    limiter
        .check_and_record(&client_id, &first_address)
        .expect("first redis faucet claim should pass");
    assert_eq!(
        limiter
            .check_and_record(&client_id, &first_address)
            .expect_err("same address should be rate limited"),
        "address cooldown"
    );
    assert_eq!(
        limiter
            .check_and_record(&client_id, &second_address)
            .expect_err("same client should be rate limited"),
        "ip rate limit"
    );
}

