#[test]
fn node_rpc_reports_intent_status() {
    let signer = signing_key(8);
    let mut engine = single_node_engine();
    engine
        .policy_store_mut()
        .insert(sample_policy())
        .expect("policy should insert");

    let signed = signed_intent(&signer, 1, 10_000, IntentKind::Cancel { order_id: 7 });
    let expected_intent_id = intent_id(&signed);

    {
        let mut service = NodeRpcService::new(&mut engine);
        service
            .submit_intent(signed, 1_100)
            .expect("submit intent should succeed");
        let queued = service.get_intent_status(expected_intent_id);
        assert_eq!(queued.stage, IntentStatusStage::AcceptedDirect);
        assert_eq!(queued.rejection_reason, None);
        assert_eq!(queued.pending_reason, None);
        assert!(queued.currently_queued);
        assert_eq!(queued.policy_id, Some(42));
        assert_eq!(queued.nonce, Some(1));
    }

    {
        let mut service = NodeRpcService::new(&mut engine);
        service
            .produce_block(1_200, 10)
            .expect("block production should succeed");
        let executed = service.get_intent_status(expected_intent_id);
        assert_eq!(executed.stage, IntentStatusStage::Executed);
        assert_eq!(executed.rejection_reason, None);
        assert_eq!(executed.pending_reason, None);
        assert!(!executed.currently_queued);
        assert_eq!(executed.block_height, Some(1));
    }
}

#[test]
fn json_rpc_status_exposes_rejection_reason() {
    let signer = signing_key(8);
    let mut policy = sample_policy();
    policy.terms.gas_budget_per_day = 10;
    policy.terms.gas_refill_per_day = 10;

    let mut engine = single_node_engine();
    engine
        .policy_store_mut()
        .insert(policy)
        .expect("policy should insert");

    let first = signed_intent(
        &signer,
        1,
        10_000,
        IntentKind::Transfer {
            to: 33,
            token: 1,
            amount: 20,
        },
    );
    let second = signed_intent(
        &signer,
        2,
        10_000,
        IntentKind::Transfer {
            to: 34,
            token: 1,
            amount: 30,
        },
    );
    let second_id = intent_id(&second);

    engine
        .submit_intent(first, 1_100)
        .expect("first intent should admit");
    engine
        .submit_intent(second, 1_100)
        .expect("second intent should admit");
    engine
        .produce_block_from_mempool(1_200, 10)
        .expect("block production should succeed");

    let server = JsonRpcHttpServer::new_with_config(
        Arc::new(Mutex::new(engine)),
        JsonRpcServerConfig {
            manual_block_production_enabled: false,
            mahi_enabled: false,
            operator_bearer_token: Some("test-operator".into()),
            peer_relay_bearer_token: None,
            network_bootstrap: None,
            peer_transport_enabled: false,
        },
    );
    let body = serde_json::to_string(&JsonRpcRequest {
        jsonrpc: "2.0".into(),
        method: "kombat_getIntentStatus".into(),
        params: json!({
            "intent_id_hex": encode_hex(&second_id),
        }),
        id: json!(11),
    })
    .expect("request should serialize");

    let response: JsonRpcResponse =
        serde_json::from_str(&server.handle_json_request(&body)).expect("response should parse");
    let result = response.result.expect("result should exist");
    assert_eq!(result["stage"], "rejected");
    assert_eq!(result["rejection_reason"], "gas_budget_exceeded");
    assert_eq!(result["order_rejection_reason"], Value::Null);
}

#[test]
fn json_rpc_status_exposes_order_rejection_reason() {
    let signer = signing_key(8);
    let mut engine = single_node_engine();
    engine
        .policy_store_mut()
        .insert(sample_policy())
        .expect("policy should insert");
    engine
        .submit_order(
            OrderRequest {
                market_id: 7,
                account_id: 22,
                client_order_id: 1,
                side: OrderSide::Ask,
                quantity_lots: 5,
                kind: OrderKind::Limit { price_ticks: 103 },
                time_in_force: TimeInForce::Gtc,
                post_only: false,
            },
            1_000,
        )
        .expect("ask should rest");

    let first = signed_intent(&signer, 1, 10_000, IntentKind::Cancel { order_id: 7 });
    let rejected = signed_intent(
        &signer,
        2,
        10_000,
        IntentKind::PlaceOrder {
            market_id: 7,
            client_order_id: 99,
            side: IntentOrderSide::Bid,
            quantity_lots: 1,
            kind: IntentOrderKind::Limit { price_ticks: 103 },
            time_in_force: IntentTimeInForce::Gtc,
            post_only: true,
        },
    );
    let rejected_id = intent_id(&rejected);
    engine
        .submit_intent(first, 1_100)
        .expect("first intent should admit");
    engine
        .submit_intent(rejected, 1_100)
        .expect("future order intent should queue");
    engine
        .produce_block_from_mempool(1_200, 10)
        .expect("block production should succeed");

    let server = JsonRpcHttpServer::new(Arc::new(Mutex::new(engine)));
    let body = serde_json::to_string(&JsonRpcRequest {
        jsonrpc: "2.0".into(),
        method: "kombat_getIntentStatus".into(),
        params: json!({
            "intent_id_hex": encode_hex(&rejected_id),
        }),
        id: json!(12),
    })
    .expect("request should serialize");

    let response: JsonRpcResponse =
        serde_json::from_str(&server.handle_json_request(&body)).expect("response should parse");
    let result = response.result.expect("result should exist");
    assert_eq!(result["stage"], "rejected");
    assert_eq!(result["rejection_reason"], "internal_error");
    assert_eq!(result["order_rejection_reason"], "post_only_would_cross");
}

