#[test]
fn json_rpc_submit_intent_returns_structured_error() {
    let signer = signing_key(8);
    let server = JsonRpcHttpServer::new(Arc::new(Mutex::new(single_node_engine())));
    let signed = signed_intent(&signer, 1, 10_000, IntentKind::Cancel { order_id: 7 });

    let body = serde_json::to_string(&JsonRpcRequest {
        jsonrpc: "2.0".into(),
        method: "kombat_submitIntent".into(),
        params: json!({
            "signed_intent": {
                "intent": {
                    "chain_id": signed.intent.chain_id,
                    "account": signed.intent.account,
                    "policy_id": signed.intent.policy_id,
                    "nonce": signed.intent.nonce,
                    "expires_at": signed.intent.expires_at,
                    "predicate": null,
                    "kind": "cancel",
                    "order_id": 7,
                },
                "signature_hex": encode_hex(&signed.signature),
            },
            "timestamp_ms": 1_100,
        }),
        id: json!(13),
    })
    .expect("request should serialize");

    let response: JsonRpcResponse =
        serde_json::from_str(&server.handle_json_request(&body)).expect("response should parse");
    let error = response.error.expect("error should exist");
    assert_eq!(error.code, -32020);
    assert_eq!(error.message, "intent submission rejected");
    let data = error.data.expect("error data should exist");
    assert_eq!(data["kind"], "intent_submission");
    assert_eq!(data["reason"], "unknown_policy");
    assert_eq!(data["policy_id"], 42);
    assert_eq!(data["nonce"], 1);
    assert!(data["intent_id_hex"].as_str().is_some());
}

