#[test]
fn json_rpc_submit_intent_batch_accepts_multiple_items() {
    let signer = signing_key(8);
    let mut engine = single_node_engine();
    engine
        .policy_store_mut()
        .insert(sample_policy())
        .expect("policy should insert");
    let server = JsonRpcHttpServer::new(Arc::new(Mutex::new(engine)));
    let first = signed_intent(&signer, 1, 10_000, IntentKind::Cancel { order_id: 7 });
    let second = signed_intent(&signer, 2, 10_000, IntentKind::Cancel { order_id: 8 });

    let body = serde_json::to_string(&JsonRpcRequest {
        jsonrpc: "2.0".into(),
        method: "kombat_submitIntentBatch".into(),
        params: json!({
            "items": [
                {
                    "signed_intent": {
                        "intent": {
                            "chain_id": first.intent.chain_id,
                            "account": first.intent.account,
                            "policy_id": first.intent.policy_id,
                            "nonce": first.intent.nonce,
                            "expires_at": first.intent.expires_at,
                            "predicate": null,
                            "kind": "cancel",
                            "order_id": 7,
                        },
                        "signature_hex": encode_hex(&first.signature),
                    },
                    "timestamp_ms": 1_100,
                },
                {
                    "signed_intent": {
                        "intent": {
                            "chain_id": second.intent.chain_id,
                            "account": second.intent.account,
                            "policy_id": second.intent.policy_id,
                            "nonce": second.intent.nonce,
                            "expires_at": second.intent.expires_at,
                            "predicate": null,
                            "kind": "cancel",
                            "order_id": 8,
                        },
                        "signature_hex": encode_hex(&second.signature),
                    },
                    "timestamp_ms": 1_101,
                }
            ]
        }),
        id: json!(15),
    })
    .expect("request should serialize");

    let response: JsonRpcResponse =
        serde_json::from_str(&server.handle_json_request(&body)).expect("response should parse");
    assert!(response.error.is_none(), "{:?}", response.error);
    let result = response.result.expect("result should exist");
    let results = result["results"]
        .as_array()
        .expect("batch results should exist");
    assert_eq!(results.len(), 2);
    assert!(results.iter().all(|item| item["accepted"] == json!(true)));
    assert!(results
        .iter()
        .all(|item| item["intent_id_hex"].as_str().is_some()));
}

#[test]
fn json_rpc_submit_intent_batch_reports_actual_admission_failures() {
    let signer = signing_key(8);
    let mut engine = single_node_engine();
    engine
        .policy_store_mut()
        .insert(sample_policy())
        .expect("policy should insert");
    let server = JsonRpcHttpServer::new(Arc::new(Mutex::new(engine)));
    let first = signed_intent(&signer, 1, 10_000, IntentKind::Cancel { order_id: 7 });
    let duplicate_nonce = signed_intent(&signer, 1, 10_000, IntentKind::Cancel { order_id: 8 });

    let body = serde_json::to_string(&JsonRpcRequest {
        jsonrpc: "2.0".into(),
        method: "kombat_submitIntentBatch".into(),
        params: json!({
            "items": [
                {
                    "signed_intent": {
                        "intent": {
                            "chain_id": first.intent.chain_id,
                            "account": first.intent.account,
                            "policy_id": first.intent.policy_id,
                            "nonce": first.intent.nonce,
                            "expires_at": first.intent.expires_at,
                            "predicate": null,
                            "kind": "cancel",
                            "order_id": 7,
                        },
                        "signature_hex": encode_hex(&first.signature),
                    },
                    "timestamp_ms": 1_100,
                },
                {
                    "signed_intent": {
                        "intent": {
                            "chain_id": duplicate_nonce.intent.chain_id,
                            "account": duplicate_nonce.intent.account,
                            "policy_id": duplicate_nonce.intent.policy_id,
                            "nonce": duplicate_nonce.intent.nonce,
                            "expires_at": duplicate_nonce.intent.expires_at,
                            "predicate": null,
                            "kind": "cancel",
                            "order_id": 8,
                        },
                        "signature_hex": encode_hex(&duplicate_nonce.signature),
                    },
                    "timestamp_ms": 1_101,
                }
            ]
        }),
        id: json!(16),
    })
    .expect("request should serialize");

    let response: JsonRpcResponse =
        serde_json::from_str(&server.handle_json_request(&body)).expect("response should parse");
    assert!(response.error.is_none(), "{:?}", response.error);
    let result = response.result.expect("result should exist");
    let results = result["results"]
        .as_array()
        .expect("batch results should exist");
    assert_eq!(results.len(), 2);
    assert_eq!(results[0]["accepted"], true);
    assert_eq!(results[1]["accepted"], false);
    assert_eq!(results[1]["error"]["message"], "intent submission rejected");
    assert_eq!(
        results[1]["error"]["data"]["reason"],
        "duplicate_policy_nonce"
    );
    assert_eq!(results[1]["error"]["data"]["policy_id"], 42);
    assert_eq!(results[1]["error"]["data"]["nonce"], 1);
}

