#[test]
fn json_rpc_submit_evm_owner_call_creates_policy_for_wallet_owned_account() {
    let (wallet_secret, wallet_address) = evm_wallet(42);
    let wrong_secret = evm_wallet(43).0;
    let grantee = signing_key(9);
    let mut engine = single_node_engine();
    engine
        .create_account(11, evm_owner_principal(wallet_address), [9; 32], 1_000)
        .expect("wallet-owned account should create");
    engine
        .apply_committed_state_updates(
            [
                (account_evm_address_state_key(11), wallet_address.to_vec()),
                (
                    evm_address_account_state_key(wallet_address),
                    11_u64.to_be_bytes().to_vec(),
                ),
            ],
            BTreeSet::new(),
        )
        .expect("wallet link should commit");
    let server = JsonRpcHttpServer::new(Arc::new(Mutex::new(engine)));
    let action = OwnerActionJson::CreatePolicy {
        policy_id: 42,
        grantee_hex: encode_hex(grantee.verifying_key().as_bytes()),
        expires_at: 50_000,
        terms: PolicyTermsWireJson {
            gas_budget_per_day: 100,
            gas_refill_per_day: 100,
            max_intents_per_second: 2,
            max_intents_per_day: 10,
            max_volume_per_day: 1_000,
            max_drawdown_pct: 25,
        },
    };

    let bad_params = SubmitEvmOwnerCallParams {
        signed_owner_call: serde_json::from_value(signed_evm_owner_call_json(
            &wrong_secret,
            wallet_address,
            11,
            7,
            0,
            action.clone(),
        ))
        .expect("bad signed owner call should deserialize"),
        timestamp_ms: 1_050,
    };
    let bad_body = serde_json::to_string(&JsonRpcRequest {
        jsonrpc: "2.0".into(),
        method: "kombat_submitEvmOwnerCall".into(),
        params: serde_json::to_value(bad_params).expect("params should serialize"),
        id: json!(17),
    })
    .expect("request should serialize");
    let bad_response: JsonRpcResponse =
        serde_json::from_str(&server.handle_json_request(&bad_body))
            .expect("response should parse");
    let error = bad_response.error.expect("wrong wallet should reject");
    assert_eq!(error.code, -32021);
    assert_eq!(
        error.data.expect("error data should exist")["reason"],
        "invalid_owner_signature"
    );

    let params = SubmitEvmOwnerCallParams {
        signed_owner_call: serde_json::from_value(signed_evm_owner_call_json(
            &wallet_secret,
            wallet_address,
            11,
            7,
            0,
            action,
        ))
        .expect("signed owner call should deserialize"),
        timestamp_ms: 1_050,
    };
    let body = serde_json::to_string(&JsonRpcRequest {
        jsonrpc: "2.0".into(),
        method: "kombat_submitEvmOwnerCall".into(),
        params: serde_json::to_value(params).expect("params should serialize"),
        id: json!(18),
    })
    .expect("request should serialize");

    let response: JsonRpcResponse =
        serde_json::from_str(&server.handle_json_request(&body)).expect("response should parse");
    assert!(response.error.is_none(), "{:?}", response.error);
    let result = response.result.expect("result should exist");
    assert_eq!(result["action"], "create_policy");
    assert_eq!(result["policy_id"], 42);
}

#[test]
fn json_rpc_submit_evm_mandate_action_revokes_wallet_owned_mandate() {
    let (wallet_secret, wallet_address) = evm_wallet(52);
    let owner = evm_owner_principal(wallet_address);
    let mut initial_engine = single_node_engine();
    initial_engine
        .create_account(11, owner, [9; 32], 900)
        .expect("wallet-owned account should create");
    link_account_evm_address_for_test(&mut initial_engine, 11, wallet_address);
    let mandate = {
        let mut service = NodeRpcService::new(&mut initial_engine);
        let mut params = sample_create_mandate_params(22, 1);
        params.owner_hex = encode_hex(&owner);
        service
            .create_mandate(params)
            .expect("mandate should create")
            .mandate
    };
    let server = JsonRpcHttpServer::new(Arc::new(Mutex::new(initial_engine)));
    let action = MandateActionJson::RevokeMandate {
        mandate_id_hex: encode_hex(&mandate.id),
        reason: "wallet_revoked".into(),
    };
    let expired =
        signed_evm_mandate_action_json(&wallet_secret, wallet_address, 7, 0, 0, action.clone());
    let expired_body = serde_json::to_string(&JsonRpcRequest {
        jsonrpc: "2.0".into(),
        method: "kombat_submitEvmMandateAction".into(),
        params: serde_json::to_value(SubmitEvmMandateActionParams {
            signed_mandate_action: expired,
            timestamp_ms: 1_050,
        })
        .expect("params should serialize"),
        id: json!(25),
    })
    .expect("request should serialize");
    let expired_response: JsonRpcResponse =
        serde_json::from_str(&server.handle_json_request(&expired_body))
            .expect("response should parse");
    let expired_error = expired_response
        .error
        .expect("expired signature should reject");
    assert_eq!(
        expired_error.data.expect("error data should exist")["reason"],
        "signature_expired"
    );

    let signed =
        signed_evm_mandate_action_json(&wallet_secret, wallet_address, 7, 0, u64::MAX, action);
    let body = serde_json::to_string(&JsonRpcRequest {
        jsonrpc: "2.0".into(),
        method: "kombat_submitEvmMandateAction".into(),
        params: serde_json::to_value(SubmitEvmMandateActionParams {
            signed_mandate_action: signed,
            timestamp_ms: 1_060,
        })
        .expect("params should serialize"),
        id: json!(26),
    })
    .expect("request should serialize");

    let response: JsonRpcResponse =
        serde_json::from_str(&server.handle_json_request(&body)).expect("response should parse");

    assert!(response.error.is_none(), "{:?}", response.error);
    let result = response.result.expect("result should exist");
    assert_eq!(result["mandate_id_hex"], encode_hex(&mandate.id));
    assert_eq!(result["state"], "revoked");
}

#[test]
fn json_rpc_submit_evm_mandate_action_accepts_minimal_create_payload() {
    let (wallet_secret, wallet_address) = evm_wallet(53);
    let owner = evm_owner_principal(wallet_address);
    let server = JsonRpcHttpServer::new(Arc::new(Mutex::new(single_node_engine())));
    let action_json = json!({
        "kind": "create_mandate",
        "agent": 22,
        "version": 1,
        "constraints": [
            { "kind": "allowed_markets", "set": [7] },
            { "kind": "max_notional_total", "limit_usdc": "1000000" },
            { "kind": "max_leverage", "mult": 5 }
        ],
        "conformance_window_ms": 86_400_000,
        "expires_at": 86_401_000
    });
    let action_typed: MandateActionJson =
        serde_json::from_value(action_json.clone()).expect("minimal create action should parse");
    let action = super::mandate_action_from_json(owner, &action_typed)
        .expect("minimal create action should decode");
    let digest = evm_mandate_action_eip712_digest(7, owner, 0, u64::MAX, &action)
        .expect("EVM mandate action should hash");
    let body = serde_json::to_string(&JsonRpcRequest {
        jsonrpc: "2.0".into(),
        method: "kombat_submitEvmMandateAction".into(),
        params: json!({
            "signed_mandate_action": {
                "chain_id": 7,
                "owner_hex": encode_hex(&owner),
                "nonce": 0,
                "valid_until_ms": u64::MAX,
                "action": action_json,
                "signature_hex": evm_signature_hex(&wallet_secret, digest)
            },
            "timestamp_ms": 1_000
        }),
        id: json!(27),
    })
    .expect("request should serialize");

    let response: JsonRpcResponse =
        serde_json::from_str(&server.handle_json_request(&body)).expect("response should parse");

    assert!(response.error.is_none(), "{:?}", response.error);
    let result = response.result.expect("result should exist");
    assert_eq!(result["agent"], 22);
    assert_eq!(result["version"], 1);
    assert_eq!(result["state"], "active");
}

#[test]
fn node_rpc_submits_orders_and_reads_book_state() {
    let mut engine = single_node_engine();
    let ask = OrderRequest {
        market_id: 7,
        account_id: 22,
        client_order_id: 1,
        side: OrderSide::Ask,
        quantity_lots: 5,
        kind: OrderKind::Limit { price_ticks: 103 },
        time_in_force: TimeInForce::Gtc,
        post_only: false,
    };
    let bid = OrderRequest {
        market_id: 7,
        account_id: 33,
        client_order_id: 2,
        side: OrderSide::Bid,
        quantity_lots: 4,
        kind: OrderKind::Limit { price_ticks: 101 },
        time_in_force: TimeInForce::Gtc,
        post_only: false,
    };

    let mut service = NodeRpcService::new(&mut engine);
    let ask_response = service.submit_order(ask, 1_000).expect("ask should submit");
    let bid_response = service.submit_order(bid, 1_001).expect("bid should submit");

    assert_eq!(ask_response.status, MatchStatus::Resting);
    assert_eq!(bid_response.status, MatchStatus::Resting);

    let book = service.get_order_book(7, 10);
    assert_eq!(book.bids[0].price_ticks, 101);
    assert_eq!(book.asks[0].price_ticks, 103);

    let open_orders = service.get_open_orders(7, 22, 10);
    assert_eq!(open_orders.len(), 1);
    assert_eq!(open_orders[0].client_order_id, 1);
    assert_eq!(open_orders[0].side, OrderSide::Ask);

    let order_status = service.get_order_status(7, 22, 1);
    assert_eq!(order_status.stage, OrderStatusStage::Resting);
    assert_eq!(order_status.filled_lots, 0);
    assert_eq!(order_status.remaining_lots, 5);
    assert_eq!(order_status.replacement_client_order_id, None);
}

#[test]
fn node_rpc_reads_trade_history() {
    let mut engine = single_node_engine();
    let ask = OrderRequest {
        market_id: 7,
        account_id: 22,
        client_order_id: 1,
        side: OrderSide::Ask,
        quantity_lots: 5,
        kind: OrderKind::Limit { price_ticks: 103 },
        time_in_force: TimeInForce::Gtc,
        post_only: false,
    };
    let crossing_bid = OrderRequest {
        market_id: 7,
        account_id: 33,
        client_order_id: 2,
        side: OrderSide::Bid,
        quantity_lots: 3,
        kind: OrderKind::Limit { price_ticks: 104 },
        time_in_force: TimeInForce::Gtc,
        post_only: false,
    };

    let mut service = NodeRpcService::new(&mut engine);
    service.submit_order(ask, 1_000).expect("ask should rest");
    service
        .submit_order(crossing_bid, 1_001)
        .expect("crossing bid should fill");

    let fills = service.get_trade_history(7, Some(22), Some(1), None, 10);
    assert_eq!(fills.len(), 1);
    assert_eq!(fills[0].market_id, 7);
    assert_eq!(fills[0].account_id, 22);
    assert_eq!(fills[0].client_order_id, 1);
    assert_eq!(fills[0].counterparty_account_id, 33);
    assert_eq!(fills[0].counterparty_client_order_id, 2);
    assert_eq!(fills[0].role, OrderFillRole::Maker);
    assert_eq!(fills[0].side, OrderFillSide::Sell);
    assert_eq!(fills[0].price_ticks, 103);
    assert_eq!(fills[0].quantity_lots, 3);
}

#[test]
fn node_rpc_gets_account_pnl_window_from_committed_events() {
    let signer = signing_key(8);
    let mut engine = single_node_engine();
    engine
        .policy_store_mut()
        .insert(sample_policy())
        .expect("policy should insert");
    engine
        .submit_order(
            OrderRequest {
                market_id: 7,
                account_id: 22,
                client_order_id: 1,
                side: OrderSide::Ask,
                quantity_lots: 5,
                kind: OrderKind::Limit { price_ticks: 103 },
                time_in_force: TimeInForce::Gtc,
                post_only: false,
            },
            1_000,
        )
        .expect("direct maker ask should rest");

    let crossing = signed_intent(
        &signer,
        1,
        10_000,
        IntentKind::PlaceOrder {
            market_id: 7,
            client_order_id: 2,
            side: IntentOrderSide::Bid,
            quantity_lots: 3,
            kind: IntentOrderKind::Limit { price_ticks: 104 },
            time_in_force: IntentTimeInForce::Gtc,
            post_only: false,
        },
    );
    engine
        .submit_intent(crossing, 1_100)
        .expect("crossing intent should admit");
    engine
        .produce_block_from_mempool(1_200, 10)
        .expect("block should commit crossing fill");

    let service = NodeRpcService::new(&mut engine);
    let excluded = service
        .get_account_pnl_window(11, Some(7), 1_000, Some(1_200))
        .expect("exclusive upper bound should be valid");
    assert_eq!(excluded.fill_count, 0);
    assert_eq!(excluded.first_seq, None);

    let window = service
        .get_account_pnl_window(11, Some(7), 1_000, Some(1_201))
        .expect("pnl window should aggregate committed fill");
    assert_eq!(window.account_id, 11);
    assert_eq!(window.market_id, Some(7));
    assert_eq!(window.from_ms, 1_000);
    assert_eq!(window.to_ms, 1_201);
    assert_eq!(window.total_realized_pnl, 0);
    assert_eq!(window.funding_paid, 0);
    assert_eq!(window.trading_realized_pnl, 0);
    assert_eq!(window.fees_paid, 0);
    assert_eq!(window.fill_count, 1);
    assert_eq!(window.fee_count, 0);
    assert_eq!(window.funding_count, 0);
    assert!(window.first_seq.is_some());
    assert!(window.last_seq >= window.first_seq);
}

