#[test]
fn node_rpc_gets_account_equity_history_with_deterministic_downsampling() {
    let mut engine = single_node_engine();
    for timestamp in [1_100, 1_200, 1_300, 1_400, 1_500] {
        engine
            .produce_empty_block(timestamp)
            .expect("history block should produce");
    }
    engine.set_equity_history_samples((1..=5_u64).map(|height| {
        (
            11,
            AccountEquitySample {
                block_height: height,
                timestamp_ms: 1_000 + height * 100,
                total_equity: height as i128,
                total_collateral: (height as i128) * 10,
                total_margin_surplus: height as i128,
                position_count: 1,
                ..AccountEquitySample::default()
            },
        )
    }));

    let before_growth = {
        let service = NodeRpcService::new(&mut engine);
        service
            .get_account_equity_history(11, 1_000, 1_501, Some(3))
            .expect("equity history should return")
    };
    assert_eq!(before_growth.account_id, 11);
    assert_eq!(
        before_growth
            .samples
            .iter()
            .map(|sample| sample.block_height)
            .collect::<Vec<_>>(),
        vec![1, 3, 5]
    );

    engine
        .produce_empty_block(1_600)
        .expect("outside-window block should produce");
    let after_growth = {
        let service = NodeRpcService::new(&mut engine);
        service
            .get_account_equity_history(11, 1_000, 1_501, Some(3))
            .expect("same query should remain stable")
    };
    assert_eq!(after_growth.samples, before_growth.samples);
}

