#[test]
fn node_rpc_account_pnl_window_does_not_double_count_funding_with_later_fill() {
    let signer = signing_key(8);
    let mut engine = single_node_engine();
    engine
        .policy_store_mut()
        .insert(high_volume_policy_for(42, 11, &signer))
        .expect("policy should insert");
    seed_pnl_funding_position(&mut engine, 77, 11, 33);
    engine
        .produce_empty_block(1_100)
        .expect("funding block should produce");
    engine
        .submit_order(
            OrderRequest {
                market_id: 77,
                account_id: 44,
                client_order_id: 3,
                side: OrderSide::Bid,
                quantity_lots: 1,
                kind: OrderKind::Limit {
                    price_ticks: 102_000,
                },
                time_in_force: TimeInForce::Gtc,
                post_only: false,
            },
            1_120,
        )
        .expect("closing liquidity should rest");
    engine
        .submit_intent(
            signed_intent(
                &signer,
                1,
                10_000,
                IntentKind::PlaceOrder {
                    market_id: 77,
                    client_order_id: 4,
                    side: IntentOrderSide::Ask,
                    quantity_lots: 1,
                    kind: IntentOrderKind::Limit {
                        price_ticks: 102_000,
                    },
                    time_in_force: IntentTimeInForce::Gtc,
                    post_only: false,
                },
            ),
            1_130,
        )
        .expect("closing intent should admit");
    engine
        .produce_block_from_mempool(1_150, 10)
        .expect("closing block should commit");

    let service = NodeRpcService::new(&mut engine);
    let funding_only = service
        .get_account_pnl_window(11, Some(77), 1_099, Some(1_101))
        .expect("funding window should aggregate");
    let fill_only = service
        .get_account_pnl_window(11, Some(77), 1_101, Some(1_151))
        .expect("fill window should aggregate");
    let combined = service
        .get_account_pnl_window(11, Some(77), 1_099, Some(1_151))
        .expect("combined window should aggregate");

    assert_eq!(funding_only.fill_count, 0);
    assert_eq!(funding_only.funding_count, 1);
    assert_eq!(fill_only.fill_count, 1);
    assert_eq!(fill_only.funding_count, 0);
    assert_eq!(combined.fill_count, 1);
    assert_eq!(combined.funding_count, 1);
    assert_eq!(
        combined.total_realized_pnl,
        funding_only
            .total_realized_pnl
            .saturating_add(fill_only.total_realized_pnl)
    );
    assert_eq!(combined.funding_paid, funding_only.funding_paid);
    assert_eq!(combined.trading_realized_pnl, fill_only.total_realized_pnl);
}

#[test]
fn node_rpc_builds_market_data_candles_and_snapshots() {
    let mut engine = single_node_engine();
    let ask = OrderRequest {
        market_id: 7,
        account_id: 22,
        client_order_id: 1,
        side: OrderSide::Ask,
        quantity_lots: 5,
        kind: OrderKind::Limit { price_ticks: 103 },
        time_in_force: TimeInForce::Gtc,
        post_only: false,
    };
    let crossing_bid = OrderRequest {
        market_id: 7,
        account_id: 33,
        client_order_id: 2,
        side: OrderSide::Bid,
        quantity_lots: 3,
        kind: OrderKind::Limit { price_ticks: 104 },
        time_in_force: TimeInForce::Gtc,
        post_only: false,
    };

    let mut service = NodeRpcService::new(&mut engine);
    service.submit_order(ask, 1_000).expect("ask should rest");
    service
        .submit_order(crossing_bid, 61_000)
        .expect("crossing bid should fill");

    let candles = service
        .get_candles(7, "1m", 0, 120_000, 10)
        .expect("candles should build");
    assert_eq!(candles.len(), 1);
    assert_eq!(candles[0].timestamp_ms, 60_000);
    assert_eq!(candles[0].open, 103);
    assert_eq!(candles[0].close, 103);
    assert_eq!(candles[0].volume_lots, 3);
    assert_eq!(candles[0].trade_count, 1);

    let snapshot = service.get_market_snapshot(7, 10);
    assert_eq!(snapshot.order_book.asks[0].price_ticks, 103);
    assert_eq!(snapshot.order_book.asks[0].total_lots, 2);
    assert_eq!(
        snapshot.latest_trade.as_ref().map(|fill| fill.price_ticks),
        Some(103)
    );
    assert!(snapshot.next_seq > snapshot.latest_trade.as_ref().unwrap().seq);

    let account = service.get_account_trading_state(33, Some(7), 10, 10);
    assert_eq!(account.positions.len(), 1);
    assert_eq!(account.positions[0].side, PositionSide::Long);
    assert_eq!(account.recent_fills.len(), 1);
    assert_eq!(account.recent_fills[0].role, OrderFillRole::Taker);
}

