#[test]
fn node_rpc_toggles_market_trading_state_and_blocks_new_orders() {
    let mut engine = single_node_engine();
    let mut service = NodeRpcService::new(&mut engine);

    let paused = service.set_market_trading_state(7, true, 1_000);
    assert!(paused.trading_paused);

    let error = service
        .submit_order(
            OrderRequest {
                market_id: 7,
                account_id: 22,
                client_order_id: 9,
                side: OrderSide::Bid,
                quantity_lots: 1,
                kind: OrderKind::Limit { price_ticks: 100 },
                time_in_force: TimeInForce::Gtc,
                post_only: false,
            },
            1_001,
        )
        .expect_err("paused market should reject new orders");

    match error {
        RpcError::Submission(error) => {
            assert_eq!(error.message, "order submission rejected");
            assert_eq!(
                error.data.as_ref().and_then(|data| data["reason"].as_str()),
                Some("market_trading_paused")
            );
            assert_eq!(
                error
                    .data
                    .as_ref()
                    .and_then(|data| data["market_id"].as_u64()),
                Some(7)
            );
        }
        other => panic!("unexpected rpc error: {other:?}"),
    }

    let resumed = service.set_market_trading_state(7, false, 1_002);
    assert!(!resumed.trading_paused);
}

#[test]
fn node_rpc_reads_market_trading_history() {
    let mut engine = single_node_engine();
    let mut service = NodeRpcService::new(&mut engine);

    service.set_market_trading_state(7, true, 1_000);
    service.set_market_trading_state(7, false, 1_050);
    service.set_market_trading_state(9, true, 1_100);

    let history = service.get_market_trading_history(Some(7), Some(0), 10);
    assert_eq!(history.len(), 2);
    assert_eq!(history[0].market_id, 7);
    assert!(history[0].paused);
    assert_eq!(history[0].timestamp_ms, 1_000);
    assert_eq!(history[1].market_id, 7);
    assert!(!history[1].paused);
    assert_eq!(history[1].timestamp_ms, 1_050);
}

