#[test]
fn node_rpc_opens_and_reads_performance_share_delegation() {
    let mut engine = single_node_engine();
    seed_account_policy_usdc(&mut engine, 22, 5_000_000_000);
    seed_account_policy_usdc(&mut engine, 11, 300_000_000);
    let mut service = NodeRpcService::new(&mut engine);
    let mandate = service
        .create_mandate(sample_create_mandate_params(22, 1))
        .expect("mandate should create")
        .mandate;

    let open_params = OpenDelegationParams {
        agent: 22,
        mandate_id_hex: encode_hex(&mandate.id),
        performance_share_units: 1_000,
        crystallization_cadence_ms: 7 * 86_400 * 1_000,
        notice_period_ms: 24 * 3_600 * 1_000,
        agent_bond: "5000000000".into(),
        timestamp_ms: 1_000,
        submitter_nonce: Some(1),
    };
    let opened = service
        .open_delegation(open_params.clone())
        .expect("delegation should open");

    assert_eq!(opened.delegation.agent, 22);
    assert_eq!(opened.delegation.performance_share_units, 1_000);
    assert_eq!(opened.delegation.agent_bond, 5_000_000_000);
    assert!(matches!(
        service.engine.head().body.items.as_slice(),
        [BlockItem::Delegation(_)]
    ));
    assert_eq!(
        service
            .get_delegation(&opened.delegation.delegation_id)
            .expect("delegation should be readable")
            .delegation,
        opened.delegation
    );
    let post_open_height = service.engine.head().header.height;
    let post_open_events = service.engine.runtime_events().len();
    let mut duplicate_open_params = open_params.clone();
    duplicate_open_params.timestamp_ms = 1_001;
    let duplicate_open = service
        .open_delegation(duplicate_open_params)
        .expect("duplicate open should be idempotent");
    assert_eq!(duplicate_open.delegation, opened.delegation);
    assert_eq!(service.engine.head().header.height, post_open_height);
    assert_eq!(service.engine.runtime_events().len(), post_open_events);
    let mut mismatched_open_params = open_params;
    mismatched_open_params.timestamp_ms = 1_002;
    mismatched_open_params.performance_share_units = 2_000;
    let err = service
        .open_delegation(mismatched_open_params)
        .expect_err("same nonce with different action body should reject");
    assert_eq!(err, RpcError::Node("delegation_action_id_mismatch".into()));
    assert_eq!(service.engine.head().header.height, post_open_height);
    assert_eq!(service.engine.runtime_events().len(), post_open_events);
    assert_eq!(service.list_delegations(None, None, 10).len(), 1);
    assert_eq!(service.list_delegations(Some(22), None, 10).len(), 1);
    assert_eq!(service.list_delegations(Some(99), None, 10).len(), 0);
    list_delegation_for_real_capital(service.engine, &opened.delegation, true, true);

    let deposit_params = DepositToDelegationParams {
        principal: 11,
        delegation_id_hex: encode_hex(&opened.delegation.delegation_id),
        amount: "150000000".into(),
        timestamp_ms: 1_100,
        submitter_nonce: Some(2),
    };
    let deposited = service
        .deposit_to_delegation(deposit_params.clone())
        .expect("deposit should succeed");
    assert_eq!(deposited.deposit.principal, 11);
    assert_eq!(deposited.deposit.shares_minted, 150_000_000);
    assert_eq!(deposited.deposit.share.shares, 150_000_000);
    assert_eq!(deposited.deposit.principal_balance, 150_000_000);
    assert_eq!(deposited.deposit.delegation_balance, 150_000_000);
    assert!(matches!(
        service.engine.head().body.items.as_slice(),
        [BlockItem::Delegation(_)]
    ));
    assert_eq!(
        service
            .get_delegation_share(&opened.delegation.delegation_id, 11)
            .share,
        deposited.deposit.share
    );
    let post_deposit_height = service.engine.head().header.height;
    let post_deposit_events = service.engine.runtime_events().len();
    let mut duplicate_deposit_params = deposit_params;
    duplicate_deposit_params.timestamp_ms = 1_101;
    let duplicate_deposit = service
        .deposit_to_delegation(duplicate_deposit_params)
        .expect("duplicate deposit should be idempotent");
    assert_eq!(duplicate_deposit.deposit.shares_minted, 150_000_000);
    assert_eq!(duplicate_deposit.deposit.share, deposited.deposit.share);
    assert_eq!(service.engine.head().header.height, post_deposit_height);
    assert_eq!(service.engine.runtime_events().len(), post_deposit_events);
    let request_params = RequestDelegationRedemptionParams {
        principal: 11,
        delegation_id_hex: encode_hex(&opened.delegation.delegation_id),
        shares: "60000000".into(),
        timestamp_ms: 1_200,
        submitter_nonce: Some(3),
    };
    let requested = service
        .request_delegation_redemption(request_params.clone())
        .expect("redemption request should succeed");
    assert_eq!(requested.redemption.request.principal, 11);
    assert_eq!(requested.redemption.request.shares_requested, 60_000_000);
    assert_eq!(requested.redemption.share.locked_for_redemption, 60_000_000);
    let post_request_height = service.engine.head().header.height;
    let post_request_events = service.engine.runtime_events().len();
    let mut duplicate_request_params = request_params;
    duplicate_request_params.timestamp_ms = 1_201;
    let duplicate_request = service
        .request_delegation_redemption(duplicate_request_params)
        .expect("duplicate redemption request should be idempotent");
    assert_eq!(duplicate_request.redemption, requested.redemption);
    assert_eq!(service.engine.head().header.height, post_request_height);
    assert_eq!(service.engine.runtime_events().len(), post_request_events);
    let finalize_params = FinalizeDelegationRedemptionParams {
        request_id_hex: encode_hex(&requested.redemption.request.request_id),
        timestamp_ms: requested.redemption.request.ready_at_ms,
        submitter_nonce: Some(4),
    };
    let finalized = service
        .finalize_delegation_redemption(finalize_params.clone())
        .expect("redemption should finalize");
    assert_eq!(finalized.finalization.usdc_out, 60_000_000);
    assert_eq!(
        finalized.finalization.request.status,
        RedemptionRequestStatus::Finalized
    );
    let post_finalize_height = service.engine.head().header.height;
    let post_finalize_events = service.engine.runtime_events().len();
    let mut duplicate_finalize_params = finalize_params;
    duplicate_finalize_params.timestamp_ms = duplicate_finalize_params.timestamp_ms + 1;
    let duplicate_finalize = service
        .finalize_delegation_redemption(duplicate_finalize_params)
        .expect("duplicate finalization should be idempotent");
    assert_eq!(duplicate_finalize.finalization.usdc_out, 60_000_000);
    assert_eq!(
        duplicate_finalize.finalization.request.status,
        RedemptionRequestStatus::Finalized
    );
    assert_eq!(service.engine.head().header.height, post_finalize_height);
    assert_eq!(service.engine.runtime_events().len(), post_finalize_events);
    let cancellable = service
        .request_delegation_redemption(RequestDelegationRedemptionParams {
            principal: 11,
            delegation_id_hex: encode_hex(&opened.delegation.delegation_id),
            shares: "10000000".into(),
            timestamp_ms: finalized.finalization.request.ready_at_ms + 100,
            submitter_nonce: None,
        })
        .expect("second redemption request should succeed");
    let cancelled = service
        .cancel_delegation_redemption(CancelDelegationRedemptionParams {
            principal: 11,
            request_id_hex: encode_hex(&cancellable.redemption.request.request_id),
            timestamp_ms: finalized.finalization.request.ready_at_ms + 150,
            submitter_nonce: Some(5),
        })
        .expect("redemption should cancel");
    assert_eq!(
        cancelled.cancellation.request.status,
        RedemptionRequestStatus::Cancelled
    );
    assert_eq!(cancelled.cancellation.share.locked_for_redemption, 0);
    let post_cancel_height = service.engine.head().header.height;
    let post_cancel_events = service.engine.runtime_events().len();
    let duplicate_cancel = service
        .cancel_delegation_redemption(CancelDelegationRedemptionParams {
            principal: 11,
            request_id_hex: encode_hex(&cancellable.redemption.request.request_id),
            timestamp_ms: 1_351,
            submitter_nonce: Some(5),
        })
        .expect("duplicate cancel should be idempotent");
    assert_eq!(
        duplicate_cancel.cancellation.request.status,
        RedemptionRequestStatus::Cancelled
    );
    assert_eq!(service.engine.head().header.height, post_cancel_height);
    assert_eq!(service.engine.runtime_events().len(), post_cancel_events);

    // Bad agent_bond string is rejected at the RPC layer.
    let err = service
        .open_delegation(OpenDelegationParams {
            agent: 33,
            mandate_id_hex: encode_hex(&[9_u8; 32]),
            performance_share_units: 1_000,
            crystallization_cadence_ms: 7 * 86_400 * 1_000,
            notice_period_ms: 24 * 3_600 * 1_000,
            agent_bond: "not_a_number".into(),
            timestamp_ms: 1_000,
            submitter_nonce: None,
        })
        .expect_err("invalid agent_bond should reject");
    assert!(matches!(err, RpcError::InvalidRequest(_)));
}

#[test]
fn node_rpc_open_delegation_survives_native_mahi_head_root() {
    with_env_vars(&[("KOMBAT_MAHI_LEGACY_EXEC", Some("0".into()))], || {
        let mut engine = single_node_engine();
        seed_account_policy_usdc(&mut engine, 22, 5_000_000_000);
        let mandate = {
            let mut service = NodeRpcService::new(&mut engine);
            service
                .create_mandate(sample_create_mandate_params(22, 1))
                .expect("mandate should create")
                .mandate
        };
        let native_empty =
            MahiBlock::signed(validator(9), 4, 1, 2_000, Vec::new(), Vec::new(), [9; 32]);
        engine
            .apply_mahi_committed_block(&native_empty)
            .expect("native Mahi empty block should apply");
        let native_head_root = engine.head().header.state_root;
        assert_ne!(native_head_root, engine.committed_state_root());

        let mut service = NodeRpcService::new(&mut engine);
        let opened = service
            .open_delegation(OpenDelegationParams {
                agent: 22,
                mandate_id_hex: encode_hex(&mandate.id),
                performance_share_units: 1_000,
                crystallization_cadence_ms: 7 * 86_400 * 1_000,
                notice_period_ms: 24 * 3_600 * 1_000,
                agent_bond: "5000000000".into(),
                timestamp_ms: 2_001,
                submitter_nonce: Some(77),
            })
            .expect("native-head bridge delegation should open");

        assert_eq!(opened.delegation.agent, 22);
        assert_eq!(service.engine.head().header.height, 2);
        assert_eq!(
            service.engine.head().header.parent_state_root,
            native_head_root
        );
    });
}

#[test]
fn node_rpc_lists_delegation_redemption_requests_for_vault_ui() {
    let mut engine = single_node_engine();
    seed_account_policy_usdc(&mut engine, 22, 5_000_000_000);
    seed_account_policy_usdc(&mut engine, 11, 300_000_000);

    let (vault_id, ready_request_id, cancelled_request_id);
    {
        let mut service = NodeRpcService::new(&mut engine);
        let mandate = service
            .create_mandate(sample_create_mandate_params(22, 1))
            .expect("mandate should create")
            .mandate;
        let opened = service
            .open_delegation(OpenDelegationParams {
                agent: 22,
                mandate_id_hex: encode_hex(&mandate.id),
                performance_share_units: 1_000,
                crystallization_cadence_ms: 7 * 86_400 * 1_000,
                notice_period_ms: 24 * 3_600 * 1_000,
                agent_bond: "5000000000".into(),
                timestamp_ms: 1_000,
                submitter_nonce: Some(1),
            })
            .expect("delegation should open")
            .delegation;
        vault_id = crate::vaults::vault_id_for_delegation(&opened.delegation_id);
        list_delegation_for_real_capital(service.engine, &opened, true, true);

        service
            .deposit_to_delegation(DepositToDelegationParams {
                principal: 11,
                delegation_id_hex: encode_hex(&opened.delegation_id),
                amount: "150000000".into(),
                timestamp_ms: 1_100,
                submitter_nonce: Some(2),
            })
            .expect("deposit should succeed");

        let finalized = service
            .request_delegation_redemption(RequestDelegationRedemptionParams {
                principal: 11,
                delegation_id_hex: encode_hex(&opened.delegation_id),
                shares: "60000000".into(),
                timestamp_ms: 1_200,
                submitter_nonce: Some(3),
            })
            .expect("finalized request should create")
            .redemption
            .request;
        service
            .finalize_delegation_redemption(FinalizeDelegationRedemptionParams {
                request_id_hex: encode_hex(&finalized.request_id),
                timestamp_ms: finalized.ready_at_ms,
                submitter_nonce: Some(4),
            })
            .expect("request should finalize");

        let cancellable = service
            .request_delegation_redemption(RequestDelegationRedemptionParams {
                principal: 11,
                delegation_id_hex: encode_hex(&opened.delegation_id),
                shares: "10000000".into(),
                timestamp_ms: finalized.ready_at_ms + 100,
                submitter_nonce: Some(5),
            })
            .expect("cancelled request should create")
            .redemption
            .request;
        cancelled_request_id = cancellable.request_id;
        service
            .cancel_delegation_redemption(CancelDelegationRedemptionParams {
                principal: 11,
                request_id_hex: encode_hex(&cancellable.request_id),
                timestamp_ms: finalized.ready_at_ms + 200,
                submitter_nonce: Some(6),
            })
            .expect("request should cancel");

        let ready = service
            .request_delegation_redemption(RequestDelegationRedemptionParams {
                principal: 11,
                delegation_id_hex: encode_hex(&opened.delegation_id),
                shares: "20000000".into(),
                timestamp_ms: finalized.ready_at_ms + 300,
                submitter_nonce: Some(7),
            })
            .expect("ready request should create")
            .redemption
            .request;
        ready_request_id = ready.request_id;
        service
            .engine
            .produce_empty_block(ready.ready_at_ms)
            .expect("advance to ready timestamp");

        let listed = service
            .list_redemption_requests(11, None, None, None, 10)
            .expect("list redemption requests");
        assert_eq!(listed.items.len(), 3);
        assert!(listed.next_cursor.is_none());
        assert_eq!(listed.items[0].request.request_id, ready_request_id);
        assert_eq!(
            listed.items[0].request.status,
            RedemptionRequestStatus::Ready
        );
        assert_eq!(listed.items[0].vault_id, vault_id);
        assert_eq!(listed.items[1].request.request_id, cancelled_request_id);
        assert_eq!(
            listed.items[1].request.status,
            RedemptionRequestStatus::Cancelled
        );
        assert_eq!(
            listed.items[2].request.status,
            RedemptionRequestStatus::Finalized
        );

        let ready_only = service
            .list_redemption_requests(
                11,
                Some(vault_id),
                Some(RedemptionRequestStatus::Ready),
                None,
                10,
            )
            .expect("ready filter");
        assert_eq!(ready_only.items.len(), 1);
        assert_eq!(ready_only.items[0].request.request_id, ready_request_id);

        let page_1 = service
            .list_redemption_requests(11, None, None, None, 1)
            .expect("first page");
        assert_eq!(page_1.items.len(), 1);
        let cursor = page_1.next_cursor.as_deref().expect("cursor");
        let page_2 = service
            .list_redemption_requests(11, None, None, Some(cursor), 1)
            .expect("second page");
        assert_eq!(page_2.items.len(), 1);
        assert_eq!(page_2.items[0].request.request_id, cancelled_request_id);
    }

    let server = JsonRpcHttpServer::new(Arc::new(Mutex::new(engine)));
    let body = serde_json::to_string(&JsonRpcRequest {
        jsonrpc: "2.0".into(),
        method: "kombat_listRedemptionRequests".into(),
        params: json!({
            "principal": 11,
            "vault_id_hex": encode_hex(&vault_id),
            "status": "ready",
            "limit": 10
        }),
        id: json!(1),
    })
    .expect("serialize");
    let response: JsonRpcResponse =
        serde_json::from_str(&server.handle_json_request(&body)).expect("parse response");
    let result = response.result.expect("result");
    let items = result["items"].as_array().expect("items array");
    assert_eq!(items.len(), 1);
    assert_eq!(items[0]["request_id_hex"], encode_hex(&ready_request_id));
    assert_eq!(items[0]["vault_id_hex"], encode_hex(&vault_id));
    assert_eq!(items[0]["kind"], "delegation");
    assert_eq!(items[0]["status"], "ready");
    assert!(result["next_cursor"].is_null());
}

#[test]
fn node_rpc_lists_principal_vault_positions_for_vault_ui() {
    use crate::vaults;

    let mut engine = single_node_engine();
    seed_account_policy_usdc(&mut engine, 22, 5_000_000_000);
    seed_account_policy_usdc(&mut engine, 33, 5_000_000_000);
    seed_account_policy_usdc(&mut engine, 11, 250_000_000);

    let (locked_vault_id, locked_delegation_id);
    {
        let mut service = NodeRpcService::new(&mut engine);
        let mandate_a = service
            .create_mandate(sample_create_mandate_params(22, 1))
            .expect("mandate a should create")
            .mandate;
        let mandate_b = service
            .create_mandate(sample_create_mandate_params(33, 1))
            .expect("mandate b should create")
            .mandate;
        let opened_a = service
            .open_delegation(OpenDelegationParams {
                agent: 22,
                mandate_id_hex: encode_hex(&mandate_a.id),
                performance_share_units: 1_000,
                crystallization_cadence_ms: 7 * 86_400 * 1_000,
                notice_period_ms: 24 * 3_600 * 1_000,
                agent_bond: "5000000000".into(),
                timestamp_ms: 1_000,
                submitter_nonce: Some(1),
            })
            .expect("delegation a opens")
            .delegation;
        let opened_b = service
            .open_delegation(OpenDelegationParams {
                agent: 33,
                mandate_id_hex: encode_hex(&mandate_b.id),
                performance_share_units: 2_000,
                crystallization_cadence_ms: 7 * 86_400 * 1_000,
                notice_period_ms: 24 * 3_600 * 1_000,
                agent_bond: "5000000000".into(),
                timestamp_ms: 1_001,
                submitter_nonce: Some(1),
            })
            .expect("delegation b opens")
            .delegation;
        list_delegation_for_real_capital(service.engine, &opened_a, true, true);
        list_delegation_for_real_capital(service.engine, &opened_b, true, true);

        service
            .deposit_to_delegation(DepositToDelegationParams {
                principal: 11,
                delegation_id_hex: encode_hex(&opened_a.delegation_id),
                amount: "150000000".into(),
                timestamp_ms: 1_100,
                submitter_nonce: Some(2),
            })
            .expect("deposit a succeeds");
        service
            .deposit_to_delegation(DepositToDelegationParams {
                principal: 11,
                delegation_id_hex: encode_hex(&opened_b.delegation_id),
                amount: "100000000".into(),
                timestamp_ms: 1_101,
                submitter_nonce: Some(3),
            })
            .expect("deposit b succeeds");
        service
            .request_delegation_redemption(RequestDelegationRedemptionParams {
                principal: 11,
                delegation_id_hex: encode_hex(&opened_a.delegation_id),
                shares: "60000000".into(),
                timestamp_ms: 1_200,
                submitter_nonce: Some(4),
            })
            .expect("redemption request locks shares");
        let trading_a = delegation_trading_account_id(&opened_a.delegation_id);
        service
            .engine
            .set_isolated_collateral(7, trading_a, 300_000_000);
        let trading_address_hash = alloy_primitives::keccak256(
            [
                b"delegation-trading-address".as_slice(),
                opened_a.delegation_id.as_slice(),
            ]
            .concat(),
        );
        let mut trading_address = [0_u8; 20];
        trading_address.copy_from_slice(&trading_address_hash[..20]);
        service
            .engine
            .apply_committed_state_updates(
                Vec::<(Vec<u8>, Vec<u8>)>::new(),
                vec![policy_usdc_balance_state_key(trading_address)],
            )
            .expect("deployed cash can be absent while isolated collateral remains");

        locked_vault_id = vaults::vault_id_for_delegation(&opened_a.delegation_id);
        locked_delegation_id = opened_a.delegation_id;

        let positions = service
            .list_vault_positions(11, None, None, None, 10)
            .expect("list positions");
        assert_eq!(positions.items.len(), 2);
        assert!(positions.next_cursor.is_none());
        assert!(positions.items[0].vault_id < positions.items[1].vault_id);
        let locked = positions
            .items
            .iter()
            .find(|item| item.vault_id == locked_vault_id)
            .expect("locked position");
        assert_eq!(locked.kind, vaults::VaultKind::Delegation);
        assert_eq!(locked.delegation_id, locked_delegation_id);
        assert_eq!(locked.principal, 11);
        assert_eq!(locked.share.shares, 150_000_000);
        assert_eq!(locked.share.locked_for_redemption, 60_000_000);
        assert_eq!(locked.principal_deposited_micro_usdc, 150_000_000);
        assert_eq!(locked.authoritative_nav_per_share, 2 * SHARE_SCALE_FACTOR);
        assert_eq!(locked.indicative_nav_per_share, 2 * SHARE_SCALE_FACTOR);
        assert_eq!(locked.live_nav_per_share, Some(2 * SHARE_SCALE_FACTOR));
        assert_eq!(locked.live_estimated_value_micro_usdc, Some(300_000_000));
        let live = locked.live_trading.expect("live trading info");
        assert_eq!(live.trading_account_id, trading_a);
        assert_eq!(live.total_equity_micro_usdc, 300_000_000);
        assert_eq!(locked.compensation_claim_micro_usdc, 0);
        assert_eq!(locked.estimated_value_micro_usdc, 300_000_000);
        assert_eq!(locked.status, vaults::VaultStatus::Open);

        let page_1 = service
            .list_vault_positions(11, None, None, None, 1)
            .expect("first position page");
        assert_eq!(page_1.items.len(), 1);
        let cursor = page_1.next_cursor.as_deref().expect("cursor");
        let page_2 = service
            .list_vault_positions(11, None, None, Some(cursor), 1)
            .expect("second position page");
        assert_eq!(page_2.items.len(), 1);
        assert!(page_2.next_cursor.is_none());
        assert!(page_2.items[0].vault_id > page_1.items[0].vault_id);

        let open_only = service
            .list_vault_positions(11, None, Some(vaults::VaultStatus::Open), None, 10)
            .expect("open filter");
        assert_eq!(open_only.items.len(), 2);
        let paused = service
            .list_vault_positions(11, None, Some(vaults::VaultStatus::Paused), None, 10)
            .expect("paused filter");
        assert!(paused.items.is_empty());
        let future_kind = service
            .list_vault_positions(
                11,
                Some(vaults::VaultKind::SupplyBorrowPool),
                None,
                None,
                10,
            )
            .expect("unimplemented kind");
        assert!(future_kind.items.is_empty());
        let other_principal = service
            .list_vault_positions(12, None, None, None, 10)
            .expect("principal without shares");
        assert!(other_principal.items.is_empty());
        let err = service
            .list_vault_positions(11, None, None, Some("not hex"), 10)
            .expect_err("bad cursor rejects");
        assert!(matches!(err, RpcError::InvalidRequest(_)));
    }

    let server = JsonRpcHttpServer::new(Arc::new(Mutex::new(engine)));
    let body = serde_json::to_string(&JsonRpcRequest {
        jsonrpc: "2.0".into(),
        method: "kombat_listVaultPositions".into(),
        params: json!({
            "principal": 11,
            "kind": "delegation",
            "status": "open",
            "limit": 10
        }),
        id: json!(1),
    })
    .expect("serialize");
    let response: JsonRpcResponse =
        serde_json::from_str(&server.handle_json_request(&body)).expect("parse response");
    let result = response.result.expect("result");
    let items = result["items"].as_array().expect("items array");
    assert_eq!(items.len(), 2);
    let locked = items
        .iter()
        .find(|item| item["vault_id_hex"] == encode_hex(&locked_vault_id))
        .expect("locked JSON item");
    assert_eq!(locked["kind"], "delegation");
    assert_eq!(
        locked["delegation_id_hex"],
        encode_hex(&locked_delegation_id)
    );
    assert_eq!(locked["principal"], 11);
    assert_eq!(locked["shares"], "150000000");
    assert_eq!(locked["locked_shares_for_redemption"], "60000000");
    assert_eq!(locked["avg_entry_nav_per_share"], "1000000");
    assert_eq!(locked["principal_deposited_micro_usdc"], "150000000");
    assert_eq!(locked["authoritative_nav_per_share"], "2000000");
    assert_eq!(
        locked["authoritative_nav_source"],
        "current_delegation_equity_nav"
    );
    assert_eq!(locked["indicative_nav_per_share"], "2000000");
    assert_eq!(
        locked["indicative_nav_source"],
        "current_delegation_equity_nav"
    );
    assert_eq!(locked["live_nav_per_share"], "2000000");
    assert_eq!(locked["live_estimated_value_micro_usdc"], "300000000");
    assert_eq!(
        locked["live_trading"]["source"],
        "delegation_trading_account_risk_summary"
    );
    assert_eq!(
        locked["live_trading"]["total_equity_micro_usdc"],
        "300000000"
    );
    assert_eq!(locked["compensation_claim_micro_usdc"], "0");
    assert_eq!(locked["estimated_value_micro_usdc"], "300000000");
    assert_eq!(locked["status"], "open");
    assert!(result["next_cursor"].is_null());
}

// RFC 043 — Vaults Discovery Surface integration tests.
#[test]
fn node_rpc_lists_and_reads_delegation_vaults() {
    use crate::vaults;

    let mut engine = single_node_engine();
    // Two agents, each with bond + a principal funding the second one
    // so we get two delegations with distinct TVL.
    seed_account_policy_usdc(&mut engine, 22, 5_000_000_000);
    seed_account_policy_usdc(&mut engine, 33, 5_000_000_000);
    seed_account_policy_usdc(&mut engine, 11, 250_000_000);
    let mut service = NodeRpcService::new(&mut engine);
    let mandate_a = service
        .create_mandate(sample_create_mandate_params(22, 1))
        .expect("mandate a should create")
        .mandate;
    let mandate_b = service
        .create_mandate(sample_create_mandate_params(33, 1))
        .expect("mandate b should create")
        .mandate;

    let opened_a = service
        .open_delegation(OpenDelegationParams {
            agent: 22,
            mandate_id_hex: encode_hex(&mandate_a.id),
            performance_share_units: 1_000,
            crystallization_cadence_ms: 7 * 86_400 * 1_000,
            notice_period_ms: 24 * 3_600 * 1_000,
            agent_bond: "5000000000".into(),
            timestamp_ms: 1_000,
            submitter_nonce: Some(1),
        })
        .expect("delegation a opens")
        .delegation;
    let opened_b = service
        .open_delegation(OpenDelegationParams {
            agent: 33,
            mandate_id_hex: encode_hex(&mandate_b.id),
            performance_share_units: 2_000,
            crystallization_cadence_ms: 7 * 86_400 * 1_000,
            notice_period_ms: 24 * 3_600 * 1_000,
            agent_bond: "5000000000".into(),
            timestamp_ms: 1_001,
            submitter_nonce: Some(1),
        })
        .expect("delegation b opens")
        .delegation;
    list_delegation_for_real_capital(service.engine, &opened_a, true, true);
    list_delegation_for_real_capital(service.engine, &opened_b, true, true);
    // Fund delegation b so it has non-zero TVL while delegation a has 0.
    service
        .deposit_to_delegation(DepositToDelegationParams {
            principal: 11,
            delegation_id_hex: encode_hex(&opened_b.delegation_id),
            amount: "150000000".into(),
            timestamp_ms: 1_100,
            submitter_nonce: Some(2),
        })
        .expect("deposit succeeds");
    let trading_b = delegation_trading_account_id(&opened_b.delegation_id);
    service
        .engine
        .set_isolated_collateral(7, trading_b, 151_000_000);

    // No filters → both delegations surface as USDC vaults; b has TVL,
    // so it sorts first by tvl_micro_usdc desc.
    let listed = service
        .list_vaults(None, None, None, None, false, None, 100)
        .expect("list vaults");
    assert_eq!(listed.items.len(), 2);
    assert!(listed.next_cursor.is_none());
    assert_eq!(listed.items[0].kind, vaults::VaultKind::Delegation);
    assert_eq!(listed.items[0].operator, Some(33));
    assert_eq!(listed.items[0].tvl_micro_usdc, 150_000_000);
    assert_eq!(listed.items[1].operator, Some(22));
    assert_eq!(listed.items[1].tvl_micro_usdc, 0);
    assert_eq!(listed.items[0].status, vaults::VaultStatus::Open);
    assert_eq!(
        listed.items[0].capital_currency,
        vaults::VAULT_USDC_ASSET_ID
    );
    assert_eq!(listed.items[0].fee_summary.perf_share_units, 2_000);
    assert!(listed.items[0].discovery.listed);
    assert!(listed.items[0].real_capital.is_some());
    let live = listed.items[0].live_trading.expect("live trading info");
    assert_eq!(live.trading_account_id, trading_b);
    assert_eq!(live.market_count, 1);
    assert_eq!(live.total_collateral_micro_usdc, 151_000_000);
    assert_eq!(live.total_equity_micro_usdc, 151_000_000);

    // Operator filter narrows to a single record.
    let only_a = service
        .list_vaults(None, None, Some(22), None, false, None, 100)
        .expect("list vaults filtered");
    assert_eq!(only_a.items.len(), 1);
    assert_eq!(only_a.items[0].operator, Some(22));

    // Kind filter on the only-implemented kind returns the same set.
    let kind_filter = service
        .list_vaults(
            Some(vaults::VaultKind::Delegation),
            None,
            None,
            None,
            false,
            None,
            100,
        )
        .expect("kind filter");
    assert_eq!(kind_filter.items.len(), 2);

    // Status filter — none are Paused, so it returns empty.
    let paused = service
        .list_vaults(
            None,
            Some(vaults::VaultStatus::Paused),
            None,
            None,
            false,
            None,
            100,
        )
        .expect("status filter");
    assert!(paused.items.is_empty());

    // Currency filter: default is USDC-only; an explicit non-USDC list
    // returns nothing for delegation kind (which is USDC-only).
    let other_currency = service
        .list_vaults(None, None, None, Some(vec![999]), false, None, 100)
        .expect("currency filter");
    assert!(other_currency.items.is_empty());

    // Empty currency list ⇒ "any" — returns both records.
    let any_currency = service
        .list_vaults(None, None, None, Some(vec![]), false, None, 100)
        .expect("any currency");
    assert_eq!(any_currency.items.len(), 2);

    // get_vault round-trip via the listed vault_id.
    let want_id = listed.items[0].vault_id;
    let fetched = service.get_vault(&want_id).expect("rpc result");
    assert!(fetched.present);
    let record = fetched.record.expect("record");
    assert_eq!(record.vault_id, want_id);
    assert_eq!(record.tvl_micro_usdc, 150_000_000);
    assert_eq!(
        record
            .live_trading
            .as_ref()
            .expect("live trading info")
            .trading_account_id,
        trading_b
    );
    match &record.details {
        vaults::VaultDetails::Delegation(d) => {
            assert_eq!(d.delegation_id, opened_b.delegation_id);
        }
    }

    // Unknown vault_id returns present=false.
    let absent = service.get_vault(&[0u8; 16]).expect("rpc result");
    assert!(!absent.present);
    assert!(absent.record.is_none());

    // Cursor pagination: limit=1 forces page boundary; next_cursor lands.
    let page1 = service
        .list_vaults(None, None, None, None, false, None, 1)
        .expect("page 1");
    assert_eq!(page1.items.len(), 1);
    assert_eq!(page1.items[0].operator, Some(33));
    let cursor = page1.next_cursor.clone().expect("next_cursor present");
    let page2 = service
        .list_vaults(None, None, None, None, false, Some(cursor.as_str()), 1)
        .expect("page 2");
    assert_eq!(page2.items.len(), 1);
    assert_eq!(page2.items[0].operator, Some(22));
    assert!(page2.next_cursor.is_none());

    // Bad cursor → InvalidRequest.
    let err = service
        .list_vaults(None, None, None, None, false, Some("not hex"), 100)
        .expect_err("bad cursor rejects");
    assert!(matches!(err, RpcError::InvalidRequest(_)));
}

#[test]
fn node_rpc_lists_and_reads_real_capital_listings() {
    let mut engine = single_node_engine();
    seed_account_policy_usdc(&mut engine, 22, 5_000_000_000);
    seed_account_policy_usdc(&mut engine, 33, 5_000_000_000);
    let mut service = NodeRpcService::new(&mut engine);
    let mandate_a = service
        .create_mandate(sample_create_mandate_params(22, 1))
        .expect("mandate a")
        .mandate;
    let mandate_b = service
        .create_mandate(sample_create_mandate_params(33, 1))
        .expect("mandate b")
        .mandate;
    let opened_a = service
        .open_delegation(OpenDelegationParams {
            agent: 22,
            mandate_id_hex: encode_hex(&mandate_a.id),
            performance_share_units: 1_000,
            crystallization_cadence_ms: 7 * 86_400 * 1_000,
            notice_period_ms: 24 * 3_600 * 1_000,
            agent_bond: "5000000000".into(),
            timestamp_ms: 1_000,
            submitter_nonce: Some(1),
        })
        .expect("delegation a")
        .delegation;
    let opened_b = service
        .open_delegation(OpenDelegationParams {
            agent: 33,
            mandate_id_hex: encode_hex(&mandate_b.id),
            performance_share_units: 1_000,
            crystallization_cadence_ms: 7 * 86_400 * 1_000,
            notice_period_ms: 24 * 3_600 * 1_000,
            agent_bond: "5000000000".into(),
            timestamp_ms: 1_001,
            submitter_nonce: Some(1),
        })
        .expect("delegation b")
        .delegation;
    let vault_a = list_delegation_for_real_capital(service.engine, &opened_a, true, true);
    let vault_b = list_delegation_for_real_capital(service.engine, &opened_b, false, false);

    let default_page = service
        .list_real_capital_listings(None, None, false, false, None, 10)
        .expect("default listing page");
    assert_eq!(default_page.items.len(), 1);
    assert_eq!(default_page.items[0].vault_id, vault_a);
    assert_eq!(
        default_page.items[0].mode,
        VaultRealCapitalMode::CappedPilot
    );
    assert_eq!(default_page.items[0].pilot_principal_allowlist, None);
    assert!(!default_page.control.global_deposit_kill_switch);
    assert_eq!(
        default_page
            .control
            .total_protocol_delegation_tvl_micro_usdc,
        0
    );

    let all = service
        .list_real_capital_listings(None, None, true, true, None, 10)
        .expect("include disabled and unlisted");
    assert_eq!(all.items.len(), 2);
    assert!(all.items.iter().any(|item| item.vault_id == vault_b));
    let filtered = service
        .list_real_capital_listings(
            Some(33),
            Some(VaultRealCapitalMode::CappedPilot),
            true,
            true,
            None,
            10,
        )
        .expect("agent and mode filter");
    assert_eq!(filtered.items.len(), 1);
    assert_eq!(filtered.items[0].serving_agent, 33);

    let first = service
        .list_real_capital_listings(None, None, true, true, None, 1)
        .expect("first page");
    let cursor = first.next_cursor.as_deref().expect("cursor");
    let second = service
        .list_real_capital_listings(None, None, true, true, Some(cursor), 1)
        .expect("second page");
    assert_eq!(second.items.len(), 1);
    assert!(second.items[0].vault_id > first.items[0].vault_id);

    let fetched = service
        .get_real_capital_listing(&vault_a)
        .expect("get listing");
    assert!(fetched.present);
    assert_eq!(
        fetched.listing.expect("listing").delegation_id,
        opened_a.delegation_id
    );
    let absent = service
        .get_real_capital_listing(&[0_u8; 16])
        .expect("absent listing");
    assert!(!absent.present);
    assert!(absent.listing.is_none());

    let server = JsonRpcHttpServer::new(Arc::new(Mutex::new(engine)));
    let body = serde_json::to_string(&JsonRpcRequest {
        jsonrpc: "2.0".into(),
        method: "kombat_listRealCapitalListings".into(),
        params: json!({
            "include_unlisted": true,
            "include_disabled": true,
            "limit": 10
        }),
        id: json!(1),
    })
    .expect("serialize");
    let response: JsonRpcResponse =
        serde_json::from_str(&server.handle_json_request(&body)).expect("parse response");
    let result = response.result.expect("result");
    assert_eq!(result["items"].as_array().expect("items").len(), 2);
    assert_eq!(result["items"][0]["mode"], "capped_pilot");
    assert_eq!(
        result["items"][0]["caps"]["per_principal_micro_usdc"],
        "1000000000"
    );
    assert_eq!(result["control"]["global_deposit_kill_switch"], false);

    let bad_mode = serde_json::to_string(&JsonRpcRequest {
        jsonrpc: "2.0".into(),
        method: "kombat_listRealCapitalListings".into(),
        params: json!({ "mode": "bad_mode" }),
        id: json!(2),
    })
    .expect("serialize");
    let response: JsonRpcResponse =
        serde_json::from_str(&server.handle_json_request(&bad_mode)).expect("parse bad");
    assert_eq!(response.error.expect("error").code, -32602);

    let get = serde_json::to_string(&JsonRpcRequest {
        jsonrpc: "2.0".into(),
        method: "kombat_getRealCapitalListing".into(),
        params: json!({ "vault_id_hex": encode_hex(&vault_a) }),
        id: json!(3),
    })
    .expect("serialize");
    let response: JsonRpcResponse =
        serde_json::from_str(&server.handle_json_request(&get)).expect("parse get");
    let result = response.result.expect("get result");
    assert_eq!(result["present"], true);
    assert_eq!(result["listing"]["vault_id_hex"], encode_hex(&vault_a));
    assert_eq!(
        result["listing"]["delegation_id_hex"],
        encode_hex(&opened_a.delegation_id)
    );
    assert_eq!(result["listing"]["serving_agent"], 22);
    assert_eq!(result["listing"]["protocol_cap_micro_usdc"], Value::Null);
    assert_eq!(result["listing"]["vault_deposited_micro_usdc"], "0");
}

#[test]
fn json_rpc_submit_real_capital_governance_action_enqueues_and_commits_listing() {
    let mut initial_engine = single_node_engine();
    seed_account_policy_usdc(&mut initial_engine, 22, 5_000_000_000);
    let (delegation_id, vault_id) = {
        let mut service = NodeRpcService::new(&mut initial_engine);
        let mandate = service
            .create_mandate(sample_create_mandate_params(22, 1))
            .expect("mandate should create")
            .mandate;
        let opened = service
            .open_delegation(OpenDelegationParams {
                agent: 22,
                mandate_id_hex: encode_hex(&mandate.id),
                performance_share_units: 1_000,
                crystallization_cadence_ms: 7 * 86_400 * 1_000,
                notice_period_ms: 24 * 3_600 * 1_000,
                agent_bond: "5000000000".into(),
                timestamp_ms: 1_000,
                submitter_nonce: Some(1),
            })
            .expect("delegation should open")
            .delegation;
        (
            opened.delegation_id,
            crate::vaults::vault_id_for_delegation(&opened.delegation_id),
        )
    };
    let engine = Arc::new(Mutex::new(initial_engine));
    let server = JsonRpcHttpServer::new_with_config(
        engine.clone(),
        JsonRpcServerConfig {
            manual_block_production_enabled: false,
            mahi_enabled: false,
            operator_bearer_token: Some("real-capital-operator".into()),
            peer_relay_bearer_token: None,
            network_bootstrap: None,
            peer_transport_enabled: false,
        },
    );
    let operator_headers = BTreeMap::from([(
        "authorization".to_string(),
        "Bearer real-capital-operator".to_string(),
    )]);
    let body = serde_json::to_string(&JsonRpcRequest {
        jsonrpc: "2.0".into(),
        method: "kombat_submitRealCapitalGovernanceAction".into(),
        params: json!({
            "timestamp_ms": 1_050,
            "action": {
                "kind": "upsert_listing",
                "vault_id_hex": encode_hex(&vault_id),
                "delegation_id_hex": encode_hex(&delegation_id),
                "serving_agent": 22,
                "mode": "capped_pilot",
                "tier0_pilot_exception": true,
                "deposit_enabled": true,
                "listed_for_discovery": true,
                "per_principal_micro_usdc": "500000000",
                "total_vault_tvl_micro_usdc": "500000000",
                "pilot_principal_allowlist": [11],
            }
        }),
        id: json!(42),
    })
    .expect("request should serialize");

    let unauthorized: JsonRpcResponse = serde_json::from_str(&server.handle_json_request(&body))
        .expect("unauthorized response should parse");
    assert_eq!(unauthorized.result, None);
    let error = unauthorized.error.expect("error should exist");
    assert_eq!(error.code, -32010);
    assert_eq!(error.message, "operator authorization required");

    let accepted: JsonRpcResponse =
        serde_json::from_str(&server.handle_json_request_with_headers(&body, &operator_headers))
            .expect("authorized response should parse");
    assert!(accepted.error.is_none(), "{:?}", accepted.error);
    let result = accepted.result.as_ref().expect("result should exist");
    assert_eq!(result["status"], "accepted");
    assert_eq!(result["pending_real_capital_governance_actions"], 1);
    let action_id_hex = result["action_id_hex"]
        .as_str()
        .expect("action id should be string")
        .to_owned();

    let duplicate: JsonRpcResponse =
        serde_json::from_str(&server.handle_json_request_with_headers(&body, &operator_headers))
            .expect("duplicate response should parse");
    assert!(duplicate.error.is_none(), "{:?}", duplicate.error);
    assert_eq!(
        duplicate.result.as_ref().unwrap()["status"],
        "duplicate_pending"
    );
    assert_eq!(
        duplicate.result.as_ref().unwrap()["pending_real_capital_governance_actions"],
        1
    );

    let status_body = serde_json::to_string(&JsonRpcRequest {
        jsonrpc: "2.0".into(),
        method: "kombat_getRealCapitalGovernanceActionStatus".into(),
        params: json!({ "action_id_hex": action_id_hex.clone() }),
        id: json!(46),
    })
    .expect("status request should serialize");
    let pending_status: JsonRpcResponse =
        serde_json::from_str(&server.handle_json_request(&status_body))
            .expect("pending status response should parse");
    assert!(pending_status.error.is_none(), "{:?}", pending_status.error);
    let pending_status = pending_status.result.as_ref().expect("status result");
    assert_eq!(pending_status["status"], "pending");
    assert_eq!(pending_status["action_kind"], "upsert_listing");
    assert_eq!(pending_status["submitted_at_ms"], 1_050);
    assert_eq!(pending_status["processed_at_ms"], Value::Null);
    assert_eq!(pending_status["receipt"], Value::Null);

    engine
        .lock()
        .expect("engine lock should succeed")
        .produce_block_from_mempool(1_100, 10)
        .expect("queued governance action should commit");

    let processed_status: JsonRpcResponse =
        serde_json::from_str(&server.handle_json_request(&status_body))
            .expect("processed status response should parse");
    assert!(
        processed_status.error.is_none(),
        "{:?}",
        processed_status.error
    );
    let processed_status = processed_status.result.as_ref().expect("status result");
    assert_eq!(processed_status["status"], "processed");
    assert_eq!(processed_status["action_kind"], "upsert_listing");
    assert_eq!(processed_status["submitted_at_ms"], 1_050);
    assert_eq!(processed_status["processed_at_ms"], 1_100);
    assert_eq!(processed_status["receipt"]["kind"], "upsert_listing");
    assert_eq!(
        processed_status["receipt"]["delegation_id_hex"],
        encode_hex(&delegation_id)
    );

    let rejected_action = BlockRealCapitalGovernanceAction::UpdateProtocolCap {
        total_protocol_tvl_micro_usdc: Some(0),
    };
    let rejected_action_id =
        real_capital_governance_action_id_for_submission(&rejected_action, 1_120);
    engine
        .lock()
        .expect("engine lock should succeed")
        .test_apply_real_capital_governance_block_item(rejected_action_id, 1_120, rejected_action);
    let rejected_status_body = serde_json::to_string(&JsonRpcRequest {
        jsonrpc: "2.0".into(),
        method: "kombat_getRealCapitalGovernanceActionStatus".into(),
        params: json!({ "action_id_hex": encode_hex(&rejected_action_id) }),
        id: json!(48),
    })
    .expect("rejected status request should serialize");
    let rejected_status: JsonRpcResponse =
        serde_json::from_str(&server.handle_json_request(&rejected_status_body))
            .expect("rejected status response should parse");
    assert!(
        rejected_status.error.is_none(),
        "{:?}",
        rejected_status.error
    );
    let rejected_status = rejected_status.result.as_ref().expect("status result");
    assert_eq!(rejected_status["status"], "rejected");
    assert_eq!(rejected_status["action_kind"], "update_protocol_cap");
    assert_eq!(rejected_status["submitted_at_ms"], 1_120);
    assert_eq!(rejected_status["processed_at_ms"], 1_120);
    assert_eq!(rejected_status["receipt"]["kind"], "rejected");
    assert_eq!(
        rejected_status["receipt"]["reason"],
        "vault_protocol_cap_zero"
    );

    let get = serde_json::to_string(&JsonRpcRequest {
        jsonrpc: "2.0".into(),
        method: "kombat_getRealCapitalListing".into(),
        params: json!({ "vault_id_hex": encode_hex(&vault_id) }),
        id: json!(43),
    })
    .expect("get request should serialize");
    let fetched: JsonRpcResponse =
        serde_json::from_str(&server.handle_json_request(&get)).expect("get should parse");
    assert!(fetched.error.is_none(), "{:?}", fetched.error);
    let fetched = fetched.result.expect("get result");
    assert_eq!(fetched["present"], true);
    assert_eq!(fetched["listing"]["vault_id_hex"], encode_hex(&vault_id));
    assert_eq!(
        fetched["listing"]["last_updated_governance_action_hex"],
        action_id_hex
    );
    assert_eq!(fetched["listing"]["pilot_principal_allowlist"], json!([11]));

    let invalid_cap = serde_json::to_string(&JsonRpcRequest {
        jsonrpc: "2.0".into(),
        method: "kombat_submitRealCapitalGovernanceAction".into(),
        params: json!({
            "timestamp_ms": 1_060,
            "action": {
                "kind": "update_protocol_cap",
                "total_protocol_tvl_micro_usdc": "not-a-number",
            }
        }),
        id: json!(44),
    })
    .expect("invalid cap request should serialize");
    let invalid: JsonRpcResponse = serde_json::from_str(
        &server.handle_json_request_with_headers(&invalid_cap, &operator_headers),
    )
    .expect("invalid response should parse");
    let error = invalid.error.expect("error should exist");
    assert_eq!(error.code, -32602);
    assert_eq!(error.message, "invalid total_protocol_tvl_micro_usdc");

    let unknown_status = serde_json::to_string(&JsonRpcRequest {
        jsonrpc: "2.0".into(),
        method: "kombat_getRealCapitalGovernanceActionStatus".into(),
        params: json!({ "action_id_hex": encode_hex(&[0x77_u8; 32]) }),
        id: json!(47),
    })
    .expect("unknown status request should serialize");
    let unknown_status: JsonRpcResponse =
        serde_json::from_str(&server.handle_json_request(&unknown_status))
            .expect("unknown status response should parse");
    assert_eq!(
        unknown_status.result.as_ref().expect("unknown status")["status"],
        "unknown"
    );

    let stale_timestamp = serde_json::to_string(&JsonRpcRequest {
        jsonrpc: "2.0".into(),
        method: "kombat_submitRealCapitalGovernanceAction".into(),
        params: json!({
            "timestamp_ms": 1_000_000_000,
            "action": {
                "kind": "update_global_kill_switch",
                "disabled": true,
            }
        }),
        id: json!(45),
    })
    .expect("stale timestamp request should serialize");
    let stale: JsonRpcResponse = serde_json::from_str(
        &server.handle_json_request_with_headers(&stale_timestamp, &operator_headers),
    )
    .expect("stale timestamp response should parse");
    let error = stale.error.expect("error should exist");
    assert_eq!(error.code, -32030);
    assert_eq!(
        error
            .data
            .as_ref()
            .and_then(|data| data.get("reason"))
            .and_then(Value::as_str),
        Some("real_capital_governance_timestamp_stale")
    );
}

#[test]
fn node_rpc_vault_status_tracks_delegation_lifecycle() {
    use crate::vaults;

    let mut engine = single_node_engine();
    seed_account_policy_usdc(&mut engine, 22, 5_000_000_000);
    let mut service = NodeRpcService::new(&mut engine);
    let mandate = service
        .create_mandate(sample_create_mandate_params(22, 1))
        .expect("mandate")
        .mandate;
    let opened = service
        .open_delegation(OpenDelegationParams {
            agent: 22,
            mandate_id_hex: encode_hex(&mandate.id),
            performance_share_units: 1_000,
            crystallization_cadence_ms: 7 * 86_400 * 1_000,
            notice_period_ms: 24 * 3_600 * 1_000,
            agent_bond: "5000000000".into(),
            timestamp_ms: 1_000,
            submitter_nonce: Some(1),
        })
        .expect("delegation opens")
        .delegation;
    list_delegation_for_real_capital(service.engine, &opened, true, true);

    let listed = service
        .list_vaults(None, None, None, None, false, None, 10)
        .expect("list vaults");
    assert_eq!(listed.items[0].status, vaults::VaultStatus::Open);

    service
        .close_delegation_to_deposits(DelegationLifecycleParams {
            delegation_id_hex: encode_hex(&opened.delegation_id),
            timestamp_ms: 1_500,
            submitter_nonce: Some(2),
        })
        .expect("close to deposits");
    let listed = service
        .list_vaults(None, None, None, None, false, None, 10)
        .expect("list vaults");
    assert_eq!(
        listed.items[0].status,
        vaults::VaultStatus::ClosedToDeposits
    );
}

#[test]
fn json_rpc_kombat_list_vaults_returns_envelope_and_paginates() {
    // Set up an engine with two delegations so pagination is meaningful.
    let mut engine = single_node_engine();
    seed_account_policy_usdc(&mut engine, 22, 5_000_000_000);
    seed_account_policy_usdc(&mut engine, 33, 5_000_000_000);
    seed_account_policy_usdc(&mut engine, 11, 250_000_000);
    {
        let mut service = NodeRpcService::new(&mut engine);
        let mandate_a = service
            .create_mandate(sample_create_mandate_params(22, 1))
            .expect("mandate a")
            .mandate;
        let mandate_b = service
            .create_mandate(sample_create_mandate_params(33, 1))
            .expect("mandate b")
            .mandate;
        let opened_a = service
            .open_delegation(OpenDelegationParams {
                agent: 22,
                mandate_id_hex: encode_hex(&mandate_a.id),
                performance_share_units: 1_000,
                crystallization_cadence_ms: 7 * 86_400 * 1_000,
                notice_period_ms: 24 * 3_600 * 1_000,
                agent_bond: "5000000000".into(),
                timestamp_ms: 1_000,
                submitter_nonce: Some(1),
            })
            .expect("delegation a")
            .delegation;
        let opened_b = service
            .open_delegation(OpenDelegationParams {
                agent: 33,
                mandate_id_hex: encode_hex(&mandate_b.id),
                performance_share_units: 2_000,
                crystallization_cadence_ms: 7 * 86_400 * 1_000,
                notice_period_ms: 24 * 3_600 * 1_000,
                agent_bond: "5000000000".into(),
                timestamp_ms: 1_001,
                submitter_nonce: Some(1),
            })
            .expect("delegation b")
            .delegation;
        list_delegation_for_real_capital(service.engine, &opened_a, true, true);
        list_delegation_for_real_capital(service.engine, &opened_b, true, true);
        service
            .deposit_to_delegation(DepositToDelegationParams {
                principal: 11,
                delegation_id_hex: encode_hex(&opened_b.delegation_id),
                amount: "150000000".into(),
                timestamp_ms: 1_100,
                submitter_nonce: Some(2),
            })
            .expect("deposit b");
    }

    let server = JsonRpcHttpServer::new(Arc::new(Mutex::new(engine)));

    // Page 1: limit=1 should yield one item plus next_cursor.
    let body_p1 = serde_json::to_string(&JsonRpcRequest {
        jsonrpc: "2.0".into(),
        method: "kombat_listVaults".into(),
        params: json!({ "limit": 1 }),
        id: json!(1),
    })
    .expect("serialize p1");
    let response_p1: JsonRpcResponse =
        serde_json::from_str(&server.handle_json_request(&body_p1)).expect("parse p1");
    let result_p1 = response_p1.result.expect("page 1 result");
    let items_p1 = result_p1["items"].as_array().expect("items array");
    assert_eq!(items_p1.len(), 1);
    assert_eq!(items_p1[0]["operator"], 33);
    assert_eq!(items_p1[0]["kind"], "delegation");
    assert_eq!(items_p1[0]["status"], "open");
    assert_eq!(items_p1[0]["capital_currency"], 0);
    let cursor = result_p1["next_cursor"]
        .as_str()
        .expect("next_cursor present")
        .to_owned();

    // Page 2: resume from cursor. Returns the second record, no further cursor.
    let body_p2 = serde_json::to_string(&JsonRpcRequest {
        jsonrpc: "2.0".into(),
        method: "kombat_listVaults".into(),
        params: json!({ "limit": 1, "cursor": cursor }),
        id: json!(2),
    })
    .expect("serialize p2");
    let response_p2: JsonRpcResponse =
        serde_json::from_str(&server.handle_json_request(&body_p2)).expect("parse p2");
    let result_p2 = response_p2.result.expect("page 2 result");
    let items_p2 = result_p2["items"].as_array().expect("items array");
    assert_eq!(items_p2.len(), 1);
    assert_eq!(items_p2[0]["operator"], 22);
    assert!(result_p2["next_cursor"].is_null());
}

#[test]
fn json_rpc_kombat_list_vaults_rejects_invalid_filters() {
    let mut engine = single_node_engine();
    seed_account_policy_usdc(&mut engine, 22, 5_000_000_000);
    let server = JsonRpcHttpServer::new(Arc::new(Mutex::new(engine)));

    for (params, fragment) in [
        (json!({ "kind": "not_a_kind" }), "vault kind"),
        (json!({ "status": "not_a_status" }), "vault status"),
        (json!({ "cursor": "not hex" }), "cursor"),
        (json!({ "limit": 0 }), "limit"),
    ] {
        let body = serde_json::to_string(&JsonRpcRequest {
            jsonrpc: "2.0".into(),
            method: "kombat_listVaults".into(),
            params,
            id: json!(9),
        })
        .expect("serialize");
        let response: JsonRpcResponse =
            serde_json::from_str(&server.handle_json_request(&body)).expect("parse");
        assert!(
            response.result.is_none(),
            "expected error for {fragment}, got result"
        );
        let err = response.error.expect("error object");
        assert!(
            err.message.contains(fragment) || err.message.contains("invalid"),
            "expected {fragment} in {}",
            err.message
        );
    }
}

#[test]
fn json_rpc_kombat_get_vault_envelope_and_invalid_id() {
    let mut engine = single_node_engine();
    seed_account_policy_usdc(&mut engine, 22, 5_000_000_000);
    let opened_id;
    {
        let mut service = NodeRpcService::new(&mut engine);
        let mandate = service
            .create_mandate(sample_create_mandate_params(22, 1))
            .expect("mandate")
            .mandate;
        opened_id = service
            .open_delegation(OpenDelegationParams {
                agent: 22,
                mandate_id_hex: encode_hex(&mandate.id),
                performance_share_units: 1_000,
                crystallization_cadence_ms: 7 * 86_400 * 1_000,
                notice_period_ms: 24 * 3_600 * 1_000,
                agent_bond: "5000000000".into(),
                timestamp_ms: 1_000,
                submitter_nonce: Some(1),
            })
            .expect("delegation")
            .delegation
            .delegation_id;
    }

    let server = JsonRpcHttpServer::new(Arc::new(Mutex::new(engine)));

    // present=true with the live vault.
    let vault_id = crate::vaults::vault_id_for_delegation(&opened_id);
    let vault_id_hex = format!("0x{}", hex::encode(vault_id));
    let body_present = serde_json::to_string(&JsonRpcRequest {
        jsonrpc: "2.0".into(),
        method: "kombat_getVault".into(),
        params: json!({ "vault_id_hex": vault_id_hex }),
        id: json!(1),
    })
    .expect("serialize");
    let response: JsonRpcResponse =
        serde_json::from_str(&server.handle_json_request(&body_present)).expect("parse");
    let result = response.result.expect("result");
    assert_eq!(result["present"], true);
    assert_eq!(result["record"]["kind"], "delegation");
    assert_eq!(result["record"]["operator"], 22);
    assert!(result["record"]["real_capital"].is_null());

    // present=false for an unknown id.
    let body_absent = serde_json::to_string(&JsonRpcRequest {
        jsonrpc: "2.0".into(),
        method: "kombat_getVault".into(),
        params: json!({ "vault_id_hex": "0x00000000000000000000000000000000" }),
        id: json!(2),
    })
    .expect("serialize");
    let response: JsonRpcResponse =
        serde_json::from_str(&server.handle_json_request(&body_absent)).expect("parse");
    let result = response.result.expect("result");
    assert_eq!(result["present"], false);
    assert!(result["record"].is_null());

    // Malformed vault_id_hex → -32602.
    let body_bad = serde_json::to_string(&JsonRpcRequest {
        jsonrpc: "2.0".into(),
        method: "kombat_getVault".into(),
        params: json!({ "vault_id_hex": "not hex" }),
        id: json!(3),
    })
    .expect("serialize");
    let response: JsonRpcResponse =
        serde_json::from_str(&server.handle_json_request(&body_bad)).expect("parse");
    assert!(response.result.is_none());
    let err = response.error.expect("error");
    assert_eq!(err.code, -32602);
    assert!(err.message.contains("vault_id_hex"));
}

#[test]
fn node_rpc_delegation_action_failure_commits_rejection_event() {
    let mut engine = single_node_engine();
    let mut service = NodeRpcService::new(&mut engine);
    let err = service
        .deposit_to_delegation(DepositToDelegationParams {
            principal: 11,
            delegation_id_hex: encode_hex(&[9_u8; 32]),
            amount: "150000000".into(),
            timestamp_ms: 1_100,
            submitter_nonce: None,
        })
        .expect_err("unknown delegation deposit should reject");

    assert_eq!(err, RpcError::Node("unknown_delegation".into()));
    assert!(matches!(
        service.engine.head().body.items.as_slice(),
        [BlockItem::Delegation(_)]
    ));
    assert!(service.engine.runtime_events().iter().any(|event| matches!(
        &event.kind,
        kombat_chain_streams::RuntimeEventKind::DelegationActionRejected {
            action_kind,
            reason,
        } if action_kind == "deposit"
            && reason == "unknown_delegation"
            && event.block_height == Some(service.engine.head().header.height)
    )));
}

#[test]
fn node_rpc_delegation_action_idempotency_survives_snapshot_restore() {
    let mut engine = single_node_engine();
    seed_account_policy_usdc(&mut engine, 22, 5_000_000_000);
    let mut service = NodeRpcService::new(&mut engine);
    let mandate = service
        .create_mandate(sample_create_mandate_params(22, 1))
        .expect("mandate should create")
        .mandate;
    let open_params = OpenDelegationParams {
        agent: 22,
        mandate_id_hex: encode_hex(&mandate.id),
        performance_share_units: 1_000,
        crystallization_cadence_ms: 7 * 86_400 * 1_000,
        notice_period_ms: 24 * 3_600 * 1_000,
        agent_bond: "5000000000".into(),
        timestamp_ms: 1_000,
        submitter_nonce: Some(99),
    };
    let opened = service
        .open_delegation(open_params.clone())
        .expect("delegation should open");
    let snapshot = service.engine.snapshot_bytes();
    let mut restored_engine =
        SingleNodeEngine::from_snapshot_bytes(&snapshot).expect("snapshot should restore");
    let restored_height = restored_engine.head().header.height;
    let restored_events = restored_engine.runtime_events().len();
    let mut restored_service = NodeRpcService::new(&mut restored_engine);

    let mut retry_params = open_params;
    retry_params.timestamp_ms = 1_999;
    let duplicate = restored_service
        .open_delegation(retry_params)
        .expect("restored duplicate open should be idempotent");

    assert_eq!(duplicate.delegation, opened.delegation);
    assert_eq!(
        restored_service.engine.head().header.height,
        restored_height
    );
    assert_eq!(
        restored_service.engine.runtime_events().len(),
        restored_events
    );
}

#[test]
fn node_rpc_updates_delegation_lifecycle() {
    let mut engine = single_node_engine();
    seed_account_policy_usdc(&mut engine, 22, 5_000_000_000);
    let mut service = NodeRpcService::new(&mut engine);
    let mandate = service
        .create_mandate(sample_create_mandate_params(22, 1))
        .expect("mandate should create")
        .mandate;
    let opened = service
        .open_delegation(OpenDelegationParams {
            agent: 22,
            mandate_id_hex: encode_hex(&mandate.id),
            performance_share_units: 1_000,
            crystallization_cadence_ms: 7 * 86_400 * 1_000,
            notice_period_ms: 24 * 3_600 * 1_000,
            agent_bond: "5000000000".into(),
            timestamp_ms: 1_000,
            submitter_nonce: None,
        })
        .expect("delegation should open");
    let params = DelegationLifecycleParams {
        delegation_id_hex: encode_hex(&opened.delegation.delegation_id),
        timestamp_ms: 1_100,
        submitter_nonce: None,
    };

    let closed_to_deposits = service
        .close_delegation_to_deposits(params.clone())
        .expect("delegation should close to deposits");
    assert_eq!(
        closed_to_deposits.delegation.status,
        DelegationStatus::ClosedToDeposits
    );
    let post_close_to_deposits_height = service.engine.head().header.height;
    let post_close_to_deposits_events = service.engine.runtime_events().len();
    let duplicate_closed_to_deposits = service
        .close_delegation_to_deposits(DelegationLifecycleParams {
            timestamp_ms: 1_111,
            ..params.clone()
        })
        .expect("duplicate close-to-deposits should be idempotent by status");
    assert_eq!(
        duplicate_closed_to_deposits.delegation.status,
        DelegationStatus::ClosedToDeposits
    );
    assert_eq!(
        service.engine.head().header.height,
        post_close_to_deposits_height
    );
    assert_eq!(
        service.engine.runtime_events().len(),
        post_close_to_deposits_events
    );
    let winding = service
        .begin_delegation_winding(DelegationLifecycleParams {
            timestamp_ms: 1_200,
            ..params.clone()
        })
        .expect("delegation should begin winding");
    assert_eq!(winding.delegation.status, DelegationStatus::Winding);
    let post_winding_height = service.engine.head().header.height;
    let post_winding_events = service.engine.runtime_events().len();
    let duplicate_winding = service
        .begin_delegation_winding(DelegationLifecycleParams {
            timestamp_ms: 1_211,
            ..params.clone()
        })
        .expect("duplicate winding should be idempotent by status");
    assert_eq!(
        duplicate_winding.delegation.status,
        DelegationStatus::Winding
    );
    assert_eq!(service.engine.head().header.height, post_winding_height);
    assert_eq!(service.engine.runtime_events().len(), post_winding_events);
    let closed = service
        .close_delegation(DelegationLifecycleParams {
            timestamp_ms: 1_300,
            ..params.clone()
        })
        .expect("empty delegation should close");
    assert_eq!(closed.delegation.status, DelegationStatus::Closed);
    let post_closed_height = service.engine.head().header.height;
    let post_closed_events = service.engine.runtime_events().len();
    let duplicate_closed = service
        .close_delegation(DelegationLifecycleParams {
            timestamp_ms: 1_311,
            ..params
        })
        .expect("duplicate close should be idempotent by status");
    assert_eq!(duplicate_closed.delegation.status, DelegationStatus::Closed);
    assert_eq!(service.engine.head().header.height, post_closed_height);
    assert_eq!(service.engine.runtime_events().len(), post_closed_events);
}

fn sample_create_mandate_params(agent: u64, version: u32) -> CreateMandateParams {
    CreateMandateParams {
        owner_hex: encode_hex(&[7_u8; 32]),
        agent,
        version,
        constraints: vec![
            MandateConstraintParam::AllowedMarkets { set: vec![7] },
            MandateConstraintParam::MaxNotionalPerMarket {
                market: 7,
                limit_usdc: "1000000".into(),
            },
        ],
        objectives: vec![MandateObjectiveParam::MaxSlippageBps { limit: 50 }],
        objective_weights: vec![100],
        conformance_window_ms: 86_400_000,
        session_keys_hex: vec![encode_hex(signing_key(8).verifying_key().as_bytes())],
        expires_at: 86_401_000,
        description_uri: Some("ipfs://mandate".into()),
        description_hash_hex: Some(encode_hex(&[9_u8; 32])),
        activation_tier: Some(0),
        timestamp_ms: 1_000,
    }
}

fn mandate_id_for_params(params: &CreateMandateParams) -> MandateId {
    let owner = decode_hex_array::<32>(&params.owner_hex).expect("owner should decode");
    let session_keys = params
        .session_keys_hex
        .iter()
        .map(|value| decode_hex_array::<32>(value).expect("session key should decode"))
        .collect::<Vec<_>>();
    let description_hash = params
        .description_hash_hex
        .as_deref()
        .map(decode_hex_array::<32>)
        .transpose()
        .expect("description hash should decode");
    let constraints = params
        .constraints
        .iter()
        .cloned()
        .map(mandate_constraint_from_param)
        .collect::<Result<Vec<_>, _>>()
        .expect("constraints should decode");
    let objectives = params
        .objectives
        .iter()
        .cloned()
        .map(mandate_objective_from_param)
        .collect::<Vec<_>>();
    derive_mandate_id(
        owner,
        params.agent,
        params.version,
        constraints,
        objectives,
        params.objective_weights.clone(),
        params.conformance_window_ms,
        session_keys,
        params.expires_at,
        description_hash,
    )
}

fn seed_identity_with_operator(
    engine: &mut SingleNodeEngine,
    agent: u64,
    agent_signer: &SigningKey,
    operator: u64,
    operator_signer: &SigningKey,
) {
    engine
        .create_account(
            agent,
            agent_signer.verifying_key().to_bytes(),
            [0; 32],
            1_000,
        )
        .expect("agent account should create");
    engine
        .create_account(
            operator,
            operator_signer.verifying_key().to_bytes(),
            [0; 32],
            1_000,
        )
        .expect("operator account should create");
    engine
        .register_agent_identity(
            RegisterAgentIdentityInput {
                account: agent,
                display_name: format!("Scout {agent:03}"),
                description: "Tier 1 scout".into(),
                kind: AgentKind::Unknown,
                operator: Some(operator),
                contact_uri: None,
            },
            1_100,
        )
        .expect("identity should register");
}

fn seed_tier2_tee_attestation(
    engine: &mut SingleNodeEngine,
    account: u64,
    attestor: u64,
    claim: AttestationClaim,
    record_id: [u8; 32],
) {
    seed_tier2_tee_attestation_with_vendor(
        engine,
        account,
        attestor,
        claim,
        record_id,
        TeeVendor::IntelSgxDcap,
    );
}

fn seed_tier2_tee_attestation_with_vendor(
    engine: &mut SingleNodeEngine,
    account: u64,
    attestor: u64,
    claim: AttestationClaim,
    record_id: [u8; 32],
    vendor: TeeVendor,
) {
    let root_id = [5_u8; 32];
    let root = VendorRoot {
        vendor,
        root_id,
        payload: match vendor {
            TeeVendor::IntelSgxDcap => VendorRootPayload::IntelSgxRoot {
                root_cert_der: vec![1, 2, 3],
                tcb_info_signing_cert_der: vec![4, 5, 6],
                tcb_info_url: "https://example.invalid/tcb.json".into(),
                crl_der: vec![7, 8, 9],
            },
            TeeVendor::AmdSevSnp => VendorRootPayload::AmdSevRoot {
                ark_cert_der: vec![1, 2, 3],
                ask_cert_der: vec![4, 5, 6],
                crl_der: vec![7, 8, 9],
            },
            TeeVendor::AwsNitro => VendorRootPayload::AwsNitroRoot {
                root_cert_der: vec![1, 2, 3],
            },
            TeeVendor::AppleSecureEnclave => VendorRootPayload::AppleSecureEnclaveRoot {
                root_cert_der: vec![1, 2, 3],
            },
        },
        valid_from_block: 0,
        valid_until_block: None,
        introduced_by_governance_action: [1; 32],
        revoked_by_governance_action: None,
    };
    let record = AttestationRecord {
        record_id,
        account,
        kind: AttestationKind::TeeEnclave,
        attestor,
        claim,
        evidence: AttestationEvidence::TeeQuoteVerified {
            vendor,
            vendor_root_id: root_id,
            enclave_id: [6; 32],
            signer: [7; 32],
            verified_at_block: engine.head().header.height,
        },
        issued_at_block: engine.head().header.height,
        issued_at_timestamp_ms: 1_200,
        expires_at_timestamp_ms: 1_200 + TEE_ATTESTATION_MIN_EXPIRY_MS,
        signature: [8; 64],
        revoked_at_block: None,
        verified: true,
    };
    engine.test_seed_tee_attestation_with_root(root, record, 1_200);
}

fn assert_mandate_activation_error(err: RpcError, current_tier: &str, required_tier: &str) {
    match err {
        RpcError::Submission(error) => {
            assert_eq!(error.code, -32027);
            let data = error.data.expect("error should include data");
            assert_eq!(data["reason"], "mandate_activation_below_required_tier");
            assert_eq!(data["current_tier"], current_tier);
            assert_eq!(data["required_tier"], required_tier);
        }
        other => panic!("unexpected tier error: {other:?}"),
    }
}

