fn sample_signed_operator_attestation_action_json_with_claim(
    attestor: u64,
    subject: u64,
    nonce: u64,
    claim: AttestationClaim,
    expires_at_timestamp_ms: u64,
    signature_signer: &SigningKey,
) -> SignedIdentityActionJson {
    let claim_json = match &claim {
        AttestationClaim::RunsCodeHash {
            code_hash,
            model_hash,
        } => AttestationClaimJson::RunsCodeHash {
            code_hash_hex: encode_hex(code_hash),
            model_hash_hex: model_hash.as_ref().map(|hash| encode_hex(hash)),
        },
        AttestationClaim::BoundToMandate { mandate_id } => AttestationClaimJson::BoundToMandate {
            mandate_id_hex: encode_hex(mandate_id),
        },
        AttestationClaim::RunsCodeAndBoundToMandate {
            code_hash,
            model_hash,
            mandate_id,
        } => AttestationClaimJson::RunsCodeAndBoundToMandate {
            code_hash_hex: encode_hex(code_hash),
            model_hash_hex: model_hash.as_ref().map(|hash| encode_hex(hash)),
            mandate_id_hex: encode_hex(mandate_id),
        },
    };
    let action = IdentityAction::RegisterOperatorAttestation(RegisterOperatorAttestationInput {
        attestor,
        subject,
        claim,
        expires_at_timestamp_ms,
    });
    SignedIdentityActionJson {
        chain_id: 7,
        account: attestor,
        nonce,
        action: IdentityActionJson::RegisterOperatorAttestation {
            attestor,
            subject,
            claim: claim_json,
            expires_at_timestamp_ms,
        },
        signature_hex: encode_hex(
            &signature_signer
                .sign(&identity_action_signing_bytes(7, attestor, nonce, &action))
                .to_bytes(),
        ),
    }
}

