#[test]
fn json_rpc_submit_market_maker_program_action_defines_program_and_reads_enrollment() {
    let signer = signing_key(31);
    let mut initial_engine = single_node_engine();
    {
        let mut service = NodeRpcService::new(&mut initial_engine);
        service
            .list_perpetual_market(ListPerpetualMarketParams {
                market_id: 7,
                base_symbol: "BTC".into(),
                quote_asset: Some(1),
                oracle_feed_id: 77,
                initial_margin_bps: 1_000,
                maintenance_margin_bps: 500,
                max_leverage: 20,
                lot_size_microunits: 1,
                tick_size_bps: 1,
                funding_interval_ms: 3_600_000,
                oracle_max_staleness_ms: Some(2_500),
                breaker_price_band_bps: Some(500),
                oracle_min_sources: Some(2),
                oracle_min_confidence: Some(50),
                oracle_min_samples: Some(3),
                oracle_feeder_ids_hex: None,
                timestamp_ms: 1_000,
            })
            .expect("market should list");
    }
    initial_engine
        .create_account(31, signer.verifying_key().to_bytes(), [9; 32], 1_050)
        .expect("market maker account should create");
    seed_account_policy_usdc(
        &mut initial_engine,
        31,
        (PROGRAM_BOND_MIN_MICRO_USDC * 2) as u64,
    );

    let input = market_maker_program_input();
    let program_id = derive_market_maker_program_id(&input);
    let engine = Arc::new(Mutex::new(initial_engine));
    let server = JsonRpcHttpServer::new_with_config(
        engine.clone(),
        JsonRpcServerConfig {
            manual_block_production_enabled: false,
            mahi_enabled: false,
            operator_bearer_token: Some("operator-token".into()),
            peer_relay_bearer_token: None,
            network_bootstrap: None,
            peer_transport_enabled: false,
        },
    );
    let headers = BTreeMap::from([("authorization".into(), "Bearer operator-token".into())]);
    let define_body = serde_json::to_string(&JsonRpcRequest {
        jsonrpc: "2.0".into(),
        method: "kombat_defineMarketMakerProgram".into(),
        params: serde_json::to_value(DefineMarketMakerProgramParams {
            name: input.name,
            markets: input.markets.iter().copied().collect(),
            min_uptime_bps: input.min_uptime_bps,
            max_spread_bps: input.max_spread_bps,
            min_quote_size_micro_usdc: "1000000".into(),
            min_two_sided_windows_per_hour: input.min_two_sided_windows_per_hour,
            rebate_multiplier_units: input.rebate_multiplier_units,
            enrollment_bond_micro_usdc: PROGRAM_BOND_MIN_MICRO_USDC.to_string(),
            compliance_window_ms: input.compliance_window_ms,
            observation_cadence_ms: input.observation_cadence_ms,
            timestamp_ms: 1_100,
            submitter_nonce: Some(81),
            wait_timeout_ms: Some(0),
        })
        .expect("params should serialize"),
        id: json!(171),
    })
    .expect("request should serialize");

    let define_response: JsonRpcResponse =
        serde_json::from_str(&server.handle_json_request_with_headers(&define_body, &headers))
            .expect("define response should parse");
    assert!(
        define_response.error.is_none(),
        "{:?}",
        define_response.error
    );
    let define_result = define_response
        .result
        .as_ref()
        .expect("result should exist");
    assert_eq!(define_result["status"], "accepted");
    assert_eq!(define_result["program_id_hex"], encode_hex(&program_id));
    assert_eq!(define_result["action_status"]["status"], "pending");
    assert_eq!(define_result["action_status"]["action_kind"], "define");

    let get_program_body = serde_json::to_string(&JsonRpcRequest {
        jsonrpc: "2.0".into(),
        method: "kombat_getMarketMakerProgram".into(),
        params: json!({ "program_id_hex": encode_hex(&program_id) }),
        id: json!(172),
    })
    .expect("request should serialize");
    let missing_program: JsonRpcResponse =
        serde_json::from_str(&server.handle_json_request(&get_program_body))
            .expect("program response should parse");
    assert!(
        missing_program.error.is_none(),
        "{:?}",
        missing_program.error
    );
    assert!(missing_program.result.is_none());

    engine
        .lock()
        .expect("engine lock should succeed")
        .produce_block_from_mempool(1_200, 10)
        .expect("define action should commit");

    let program_response: JsonRpcResponse =
        serde_json::from_str(&server.handle_json_request(&get_program_body))
            .expect("program response should parse");
    assert!(
        program_response.error.is_none(),
        "{:?}",
        program_response.error
    );
    let program = program_response
        .result
        .as_ref()
        .expect("program should exist");
    assert_eq!(program["program_id_hex"], encode_hex(&program_id));
    assert_eq!(program["status"], "active");
    assert_eq!(program["markets"], json!([7]));
    assert_eq!(
        program["enrollment_bond_micro_usdc"],
        PROGRAM_BOND_MIN_MICRO_USDC.to_string()
    );

    let enroll_body = serde_json::to_string(&JsonRpcRequest {
        jsonrpc: "2.0".into(),
        method: "kombat_enrollMarketMakerProgram".into(),
        params: serde_json::to_value(EnrollMarketMakerProgramParams {
            market_maker: Some(31),
            market_maker_identity: None,
            market_id: 7,
            program_id_hex: encode_hex(&program_id),
            bond_micro_usdc: PROGRAM_BOND_MIN_MICRO_USDC.to_string(),
            timestamp_ms: 1_250,
            submitter_nonce: Some(82),
            wait_timeout_ms: Some(0),
        })
        .expect("params should serialize"),
        id: json!(173),
    })
    .expect("request should serialize");
    let enroll_response: JsonRpcResponse =
        serde_json::from_str(&server.handle_json_request_with_headers(&enroll_body, &headers))
            .expect("enroll response should parse");
    assert!(
        enroll_response.error.is_none(),
        "{:?}",
        enroll_response.error
    );
    engine
        .lock()
        .expect("engine lock should succeed")
        .produce_block_from_mempool(1_300, 10)
        .expect("enroll action should commit");

    let get_enrollment_body = serde_json::to_string(&JsonRpcRequest {
        jsonrpc: "2.0".into(),
        method: "kombat_getMarketMakerEnrollment".into(),
        params: json!({
            "market_maker": 31,
            "market_id": 7,
            "program_id_hex": encode_hex(&program_id),
        }),
        id: json!(174),
    })
    .expect("request should serialize");
    let enrollment_response: JsonRpcResponse =
        serde_json::from_str(&server.handle_json_request(&get_enrollment_body))
            .expect("enrollment response should parse");
    assert!(
        enrollment_response.error.is_none(),
        "{:?}",
        enrollment_response.error
    );
    let enrollment = enrollment_response
        .result
        .as_ref()
        .expect("enrollment should exist");
    assert_eq!(
        enrollment["market_maker_identity"],
        json!({
            "kind": "account",
            "account_id": 31,
        })
    );
    assert_eq!(enrollment["market_id"], 7);
    assert_eq!(enrollment["program_id_hex"], encode_hex(&program_id));
    assert_eq!(enrollment["status"], "active");
    assert_eq!(
        enrollment["bond_micro_usdc"],
        PROGRAM_BOND_MIN_MICRO_USDC.to_string()
    );
}

fn signed_delegation_gossip_fixture(
    signer: &SigningKey,
) -> (
    JsonRpcHttpServer,
    Arc<Mutex<SingleNodeEngine>>,
    Arc<Mutex<SingleNodeEngine>>,
    [u8; 32],
) {
    signed_delegation_gossip_fixture_with_tokens(signer, None, None, None, None)
}

fn signed_delegation_gossip_fixture_with_tokens(
    signer: &SigningKey,
    local_operator_bearer_token: Option<&str>,
    peer_operator_bearer_token: Option<&str>,
    local_peer_relay_bearer_token: Option<&str>,
    peer_peer_relay_bearer_token: Option<&str>,
) -> (
    JsonRpcHttpServer,
    Arc<Mutex<SingleNodeEngine>>,
    Arc<Mutex<SingleNodeEngine>>,
    [u8; 32],
) {
    let peer_endpoint = reserve_local_endpoint();
    let endpoints = vec![
        (9_u8, "http://127.0.0.1:1".to_string()),
        (8_u8, peer_endpoint.clone()),
    ];
    let configs = mahi_network_bootstrap_configs(&endpoints);
    let local_bootstrap = configs
        .get(&9)
        .expect("local bootstrap config should exist")
        .clone();
    let peer_bootstrap = configs
        .get(&8)
        .expect("peer bootstrap config should exist")
        .clone();
    let mut local_engine = SingleNodeEngine::new_with_validator_set(
        SingleNodeConfig {
            chain_id: 7,
            validator_id: validator(9),
            consensus_signing_key: [9; 32],
            genesis_timestamp_ms: 1_000,
            genesis_state_root: [3; 32],
            pacemaker: kombat_chain_consensus::PacemakerConfig {
                base_timeout_ms: 300,
                max_timeout_ms: 20_000,
                max_exponent: 6,
                max_clock_skew_ms: 1_000,
            },
        },
        Some(&local_bootstrap.validator_set),
    );
    let mut peer_engine = SingleNodeEngine::new_with_validator_set(
        SingleNodeConfig {
            chain_id: 7,
            validator_id: validator(8),
            consensus_signing_key: [8; 32],
            genesis_timestamp_ms: 1_000,
            genesis_state_root: [3; 32],
            pacemaker: kombat_chain_consensus::PacemakerConfig {
                base_timeout_ms: 300,
                max_timeout_ms: 20_000,
                max_exponent: 6,
                max_clock_skew_ms: 1_000,
            },
        },
        Some(&peer_bootstrap.validator_set),
    );
    let mandate_id = seed_signed_delegation_open_prereqs(&mut local_engine, signer);
    assert_eq!(
        seed_signed_delegation_open_prereqs(&mut peer_engine, signer),
        mandate_id
    );
    let local_engine = Arc::new(Mutex::new(local_engine));
    let peer_engine = Arc::new(Mutex::new(peer_engine));
    let peer_server = JsonRpcHttpServer::new_with_config(
        peer_engine.clone(),
        JsonRpcServerConfig {
            manual_block_production_enabled: false,
            mahi_enabled: false,
            operator_bearer_token: peer_operator_bearer_token.map(ToOwned::to_owned),
            peer_relay_bearer_token: peer_peer_relay_bearer_token.map(ToOwned::to_owned),
            network_bootstrap: Some(peer_bootstrap),
            peer_transport_enabled: false,
        },
    );
    let listen_address = peer_endpoint
        .strip_prefix("http://")
        .expect("peer endpoint should have http scheme")
        .to_string();
    let serve_peer = peer_server.clone();
    std::thread::spawn(move || {
        serve_peer
            .serve(&listen_address)
            .expect("peer server should serve");
    });
    wait_for_http_server(&peer_endpoint);
    let local_server = JsonRpcHttpServer::new_with_config(
        local_engine.clone(),
        JsonRpcServerConfig {
            manual_block_production_enabled: false,
            mahi_enabled: false,
            operator_bearer_token: local_operator_bearer_token.map(ToOwned::to_owned),
            peer_relay_bearer_token: local_peer_relay_bearer_token.map(ToOwned::to_owned),
            network_bootstrap: Some(local_bootstrap),
            peer_transport_enabled: false,
        },
    );
    (local_server, local_engine, peer_engine, mandate_id)
}

fn signed_market_maker_program_gossip_fixture(
    signer: &SigningKey,
) -> (
    JsonRpcHttpServer,
    Arc<Mutex<SingleNodeEngine>>,
    Arc<Mutex<SingleNodeEngine>>,
    [u8; 32],
) {
    signed_market_maker_program_gossip_fixture_with_tokens(signer, None, None, None, None)
}

fn signed_market_maker_program_gossip_fixture_with_tokens(
    signer: &SigningKey,
    local_operator_bearer_token: Option<&str>,
    peer_operator_bearer_token: Option<&str>,
    local_peer_relay_bearer_token: Option<&str>,
    peer_peer_relay_bearer_token: Option<&str>,
) -> (
    JsonRpcHttpServer,
    Arc<Mutex<SingleNodeEngine>>,
    Arc<Mutex<SingleNodeEngine>>,
    [u8; 32],
) {
    let peer_endpoint = reserve_local_endpoint();
    let endpoints = vec![
        (9_u8, "http://127.0.0.1:1".to_string()),
        (8_u8, peer_endpoint.clone()),
    ];
    let configs = mahi_network_bootstrap_configs(&endpoints);
    let local_bootstrap = configs
        .get(&9)
        .expect("local bootstrap config should exist")
        .clone();
    let peer_bootstrap = configs
        .get(&8)
        .expect("peer bootstrap config should exist")
        .clone();
    let mut local_engine = SingleNodeEngine::new_with_validator_set(
        SingleNodeConfig {
            chain_id: 7,
            validator_id: validator(9),
            consensus_signing_key: [9; 32],
            genesis_timestamp_ms: 1_000,
            genesis_state_root: [3; 32],
            pacemaker: kombat_chain_consensus::PacemakerConfig {
                base_timeout_ms: 300,
                max_timeout_ms: 20_000,
                max_exponent: 6,
                max_clock_skew_ms: 1_000,
            },
        },
        Some(&local_bootstrap.validator_set),
    );
    let mut peer_engine = SingleNodeEngine::new_with_validator_set(
        SingleNodeConfig {
            chain_id: 7,
            validator_id: validator(8),
            consensus_signing_key: [8; 32],
            genesis_timestamp_ms: 1_000,
            genesis_state_root: [3; 32],
            pacemaker: kombat_chain_consensus::PacemakerConfig {
                base_timeout_ms: 300,
                max_timeout_ms: 20_000,
                max_exponent: 6,
                max_clock_skew_ms: 1_000,
            },
        },
        Some(&peer_bootstrap.validator_set),
    );
    // This fixture seeds the same program on both validators so the relay tests isolate
    // gossip admission. Production program definition propagates through consensus replay.
    let program_id = seed_signed_market_maker_program_prereqs(&mut local_engine, signer);
    assert_eq!(
        seed_signed_market_maker_program_prereqs(&mut peer_engine, signer),
        program_id
    );
    let local_engine = Arc::new(Mutex::new(local_engine));
    let peer_engine = Arc::new(Mutex::new(peer_engine));
    let peer_server = JsonRpcHttpServer::new_with_config(
        peer_engine.clone(),
        JsonRpcServerConfig {
            manual_block_production_enabled: false,
            mahi_enabled: false,
            operator_bearer_token: peer_operator_bearer_token.map(ToOwned::to_owned),
            peer_relay_bearer_token: peer_peer_relay_bearer_token.map(ToOwned::to_owned),
            network_bootstrap: Some(peer_bootstrap),
            peer_transport_enabled: false,
        },
    );
    let listen_address = peer_endpoint
        .strip_prefix("http://")
        .expect("peer endpoint should have http scheme")
        .to_string();
    let serve_peer = peer_server.clone();
    std::thread::spawn(move || {
        serve_peer
            .serve(&listen_address)
            .expect("peer server should serve");
    });
    wait_for_http_server(&peer_endpoint);
    let local_server = JsonRpcHttpServer::new_with_config(
        local_engine.clone(),
        JsonRpcServerConfig {
            manual_block_production_enabled: false,
            mahi_enabled: false,
            operator_bearer_token: local_operator_bearer_token.map(ToOwned::to_owned),
            peer_relay_bearer_token: local_peer_relay_bearer_token.map(ToOwned::to_owned),
            network_bootstrap: Some(local_bootstrap),
            peer_transport_enabled: false,
        },
    );
    (local_server, local_engine, peer_engine, program_id)
}

#[test]
fn node_rpc_creates_and_reads_tier0_mandate() {
    let mut engine = single_node_engine();
    let mut service = NodeRpcService::new(&mut engine);

    let created = service
        .create_mandate(sample_create_mandate_params(22, 1))
        .expect("mandate should create");

    assert_eq!(created.mandate.agent, 22);
    assert_eq!(created.mandate.version, 1);
    assert_eq!(created.mandate.activated_at, Some(1_000));
    assert_eq!(
        service
            .get_mandate(&created.mandate.id)
            .expect("mandate should be readable")
            .mandate,
        created.mandate
    );
    assert_eq!(service.list_mandates(None, Some(22), None, 10).len(), 1);
    assert_eq!(
        service
            .list_mandates(Some(created.mandate.owner), Some(22), None, 10)
            .len(),
        1
    );
    assert_eq!(
        service
            .list_mandates(Some([8_u8; 32]), Some(22), None, 10)
            .len(),
        0
    );
    assert_eq!(service.list_mandates(None, Some(99), None, 10).len(), 0);

    let err = service
        .create_mandate(sample_create_mandate_params(22, 1))
        .expect_err("same version should reject");
    assert!(matches!(err, RpcError::Submission(_)));

    let mut tier1 = sample_create_mandate_params(33, 1);
    tier1.activation_tier = Some(1);
    let err = service
        .create_mandate(tier1)
        .expect_err("tier1 should reject below required identity tier");
    match err {
        RpcError::Submission(error) => {
            assert_eq!(error.code, -32027);
            let data = error.data.expect("error should include data");
            assert_eq!(data["reason"], "mandate_activation_below_required_tier");
            assert_eq!(data["current_tier"], "tier0_unattested");
            assert_eq!(data["required_tier"], "tier1_operator_attested");
        }
        other => panic!("unexpected tier error: {other:?}"),
    }

    let mut tier2 = sample_create_mandate_params(33, 1);
    tier2.activation_tier = Some(2);
    let err = service
        .create_mandate(tier2)
        .expect_err("tier2 should reject below required identity tier");
    match err {
        RpcError::Submission(error) => {
            assert_eq!(error.code, -32027);
            let data = error.data.expect("error should include data");
            assert_eq!(data["reason"], "mandate_activation_below_required_tier");
            assert_eq!(data["current_tier"], "tier0_unattested");
            assert_eq!(data["required_tier"], "tier2_tee_attested");
        }
        other => panic!("unexpected tier error: {other:?}"),
    }

    let mut invalid_tier = sample_create_mandate_params(33, 1);
    invalid_tier.activation_tier = Some(3);
    let err = service
        .create_mandate(invalid_tier)
        .expect_err("unsupported activation tier should reject");
    assert!(matches!(
        err,
        RpcError::InvalidRequest(message) if message == "invalid activation_tier"
    ));
}

#[test]
fn node_rpc_submits_signed_mandate_action_and_tracks_nonce() {
    let owner_signer = signing_key(7);
    let owner = owner_signer.verifying_key().to_bytes();
    let mut engine = single_node_engine();
    let mut service = NodeRpcService::new(&mut engine);

    assert_eq!(service.get_mandate_action_nonce(&owner), 0);
    let params = SubmitMandateActionParams {
        signed_mandate_action: sample_signed_mandate_create_action_json(
            &owner_signer,
            0,
            &owner_signer,
        ),
        timestamp_ms: 1_000,
    };
    let created = service
        .submit_mandate_action(params.clone())
        .expect("signed mandate action should create");
    assert_eq!(created.mandate.owner, owner);
    assert_eq!(created.mandate.state, MandateState::Active);
    assert_eq!(service.get_mandate_action_nonce(&owner), 1);

    let replay = service
        .submit_mandate_action(params)
        .expect_err("replayed signed action should reject");
    match replay {
        RpcError::Submission(error) => {
            assert_eq!(error.code, -32027);
            assert_eq!(
                error.data.as_ref().and_then(|data| data["reason"].as_str()),
                Some("invalid_nonce")
            );
            assert_eq!(
                error
                    .data
                    .as_ref()
                    .and_then(|data| data["expected_nonce"].as_u64()),
                Some(1)
            );
        }
        other => panic!("unexpected replay error: {other:?}"),
    }

    let bad_sig_params = SubmitMandateActionParams {
        signed_mandate_action: sample_signed_mandate_create_action_json(
            &owner_signer,
            1,
            &signing_key(9),
        ),
        timestamp_ms: 1_100,
    };
    let bad_sig = service
        .submit_mandate_action(bad_sig_params)
        .expect_err("wrong signer should reject");
    assert!(matches!(
        bad_sig,
        RpcError::Submission(super::JsonRpcErrorObject { code: -32027, .. })
    ));
}

