#[test]
fn identity_attestation_events_round_trip_topics_and_json() {
    let record_id = [3_u8; 32];
    let mandate_id = [4_u8; 32];
    let evidence = attestation_evidence_to_json(AttestationEvidence::TeeQuoteVerified {
        vendor: TeeVendor::IntelSgxDcap,
        vendor_root_id: [7_u8; 32],
        enclave_id: [6_u8; 32],
        signer: [5_u8; 32],
        verified_at_block: 42,
    });
    assert_eq!(evidence["kind"], "tee_quote_verified");
    assert_eq!(evidence["vendor"], "intel_sgx_dcap");
    assert_eq!(evidence["vendor_root_id_hex"], encode_hex(&[7_u8; 32]));
    assert_eq!(evidence["enclave_id_hex"], encode_hex(&[6_u8; 32]));
    assert_eq!(evidence["signer_hex"], encode_hex(&[5_u8; 32]));
    assert_eq!(evidence["verified_at_block"], 42);

    let registered = RuntimeEventKind::AttestationRegistered {
        account: 11,
        record_id,
        kind: kombat_chain_streams::IdentityAttestationKind::OperatorSelf,
        attestor: 22,
        claim: kombat_chain_streams::IdentityAttestationClaim::BoundToMandate { mandate_id },
        expires_at_timestamp_ms: 3_700_000,
        tier_before: IdentityTierStatus::Tier0Unattested,
        tier_after: IdentityTierStatus::Tier1OperatorAttested,
    };
    assert_eq!(registered.account_id(), Some(11));
    assert_eq!(
        event_topic_name(registered.topic()),
        "attestation_registered"
    );
    assert_eq!(
        parse_runtime_event_topic("attestation_registered"),
        Ok(RuntimeEventTopic::AttestationRegistered)
    );
    let value = runtime_event_kind_to_json(&registered);
    assert_eq!(value["topic"], "attestation_registered");
    assert_eq!(value["record_id_hex"], encode_hex(&record_id));
    assert_eq!(value["kind"], "operator_self");
    assert_eq!(value["claim"]["mandate_id_hex"], encode_hex(&mandate_id));
    assert_eq!(value["tier_after"], "tier1_operator_attested");

    let verified = RuntimeEventKind::AttestationVerified {
        account: 11,
        record_id,
        vendor: kombat_chain_streams::IdentityAttestationVendor::OperatorSelf,
        code_hash: [0_u8; 32],
        enclave_id: [0_u8; 32],
    };
    assert_eq!(event_topic_name(verified.topic()), "attestation_verified");
    assert_eq!(
        parse_runtime_event_topic("attestation_verified"),
        Ok(RuntimeEventTopic::AttestationVerified)
    );
    let value = runtime_event_kind_to_json(&verified);
    assert_eq!(value["topic"], "attestation_verified");
    assert_eq!(value["vendor"], "operator_self");

    let verified_tee = RuntimeEventKind::AttestationVerified {
        account: 11,
        record_id,
        vendor: kombat_chain_streams::IdentityAttestationVendor::IntelSgxDcap,
        code_hash: [3_u8; 32],
        enclave_id: [4_u8; 32],
    };
    let value = runtime_event_kind_to_json(&verified_tee);
    assert_eq!(value["topic"], "attestation_verified");
    assert_eq!(value["vendor"], "intel_sgx_dcap");
    assert_eq!(value["code_hash_hex"], encode_hex(&[3_u8; 32]));
    assert_eq!(value["enclave_id_hex"], encode_hex(&[4_u8; 32]));

    let refreshed = RuntimeEventKind::AttestationRefreshed {
        account: 11,
        record_id,
        new_expires_at_timestamp_ms: 7_200_000,
    };
    assert_eq!(event_topic_name(refreshed.topic()), "attestation_refreshed");
    assert_eq!(
        parse_runtime_event_topic("attestation_refreshed"),
        Ok(RuntimeEventTopic::AttestationRefreshed)
    );
    let value = runtime_event_kind_to_json(&refreshed);
    assert_eq!(value["topic"], "attestation_refreshed");
    assert_eq!(value["new_expires_at_timestamp_ms"], 7_200_000);

    let revoked = RuntimeEventKind::AttestationRevoked {
        account: 11,
        record_id,
        reason: kombat_chain_streams::IdentityAttestationRevocationReason::SubjectRequested,
        tier_before: IdentityTierStatus::Tier1OperatorAttested,
        tier_after: IdentityTierStatus::Tier0Unattested,
    };
    assert_eq!(event_topic_name(revoked.topic()), "attestation_revoked");
    assert_eq!(
        parse_runtime_event_topic("attestation_revoked"),
        Ok(RuntimeEventTopic::AttestationRevoked)
    );
    let value = runtime_event_kind_to_json(&revoked);
    assert_eq!(value["topic"], "attestation_revoked");
    assert_eq!(value["reason"], "subject_requested");
    assert_eq!(value["tier_before"], "tier1_operator_attested");
    assert_eq!(value["tier_after"], "tier0_unattested");

    let vendor_revoked = RuntimeEventKind::AttestationRevoked {
        account: 11,
        record_id,
        reason: kombat_chain_streams::IdentityAttestationRevocationReason::VendorRootRevoked,
        tier_before: IdentityTierStatus::Tier1OperatorAttested,
        tier_after: IdentityTierStatus::Tier0Unattested,
    };
    let value = runtime_event_kind_to_json(&vendor_revoked);
    assert_eq!(value["reason"], "vendor_root_revoked");

    let expired = RuntimeEventKind::AttestationExpired {
        account: 11,
        record_id,
        tier_before: IdentityTierStatus::Tier1OperatorAttested,
        tier_after: IdentityTierStatus::Tier0Unattested,
    };
    assert_eq!(event_topic_name(expired.topic()), "attestation_expired");
    assert_eq!(
        parse_runtime_event_topic("attestation_expired"),
        Ok(RuntimeEventTopic::AttestationExpired)
    );
    let value = runtime_event_kind_to_json(&expired);
    assert_eq!(value["topic"], "attestation_expired");
    assert_eq!(value["tier_before"], "tier1_operator_attested");
    assert_eq!(value["tier_after"], "tier0_unattested");

    let tier_changed = RuntimeEventKind::TierChanged {
        account: 11,
        from: IdentityTierStatus::Tier0Unattested,
        to: IdentityTierStatus::Tier1OperatorAttested,
        reason: kombat_chain_streams::IdentityTierTransitionReason::AttestationRevoked,
    };
    assert_eq!(event_topic_name(tier_changed.topic()), "tier_changed");
    assert_eq!(
        parse_runtime_event_topic("tier_changed"),
        Ok(RuntimeEventTopic::TierChanged)
    );
    let value = runtime_event_kind_to_json(&tier_changed);
    assert_eq!(value["topic"], "tier_changed");
    assert_eq!(value["reason"], "attestation_revoked");

    let vendor_tier_changed = RuntimeEventKind::TierChanged {
        account: 11,
        from: IdentityTierStatus::Tier0Unattested,
        to: IdentityTierStatus::Tier1OperatorAttested,
        reason: kombat_chain_streams::IdentityTierTransitionReason::VendorRootChanged,
    };
    let value = runtime_event_kind_to_json(&vendor_tier_changed);
    assert_eq!(value["reason"], "vendor_root_changed");
}

