#[test]
fn node_rpc_previews_intent_initial_margin() {
    let mut engine = single_node_engine();
    let mut service = NodeRpcService::new(&mut engine);
    service
        .list_perpetual_market(ListPerpetualMarketParams {
            market_id: 7,
            base_symbol: "BTC".into(),
            quote_asset: Some(1),
            oracle_feed_id: 77,
            initial_margin_bps: 1_000,
            maintenance_margin_bps: 500,
            max_leverage: 20,
            lot_size_microunits: 1_000_000,
            tick_size_bps: 10_000,
            funding_interval_ms: 3_600_000,
            oracle_max_staleness_ms: Some(5_000),
            breaker_price_band_bps: Some(500),
            oracle_min_sources: None,
            oracle_min_confidence: None,
            oracle_min_samples: None,
            oracle_feeder_ids_hex: None,
            timestamp_ms: 1_000,
        })
        .expect("market should list");
    service.set_index_price(7, 100, 1_050);
    service.set_mark_price(7, 100, 1_050);

    let order = OrderRequest {
        market_id: 7,
        account_id: 22,
        client_order_id: 1,
        side: OrderSide::Bid,
        quantity_lots: 1,
        kind: OrderKind::Limit { price_ticks: 100 },
        time_in_force: TimeInForce::Gtc,
        post_only: false,
    };
    let preview = service
        .preview_intent(order, None, Some(1_100))
        .expect("preview should run");
    assert!(!preview.would_succeed);
    assert_eq!(preview.reason, Some("insufficient_initial_margin"));
    assert_eq!(preview.current_raw_notional, 0);
    assert_eq!(preview.candidate_raw_notional, 100);
    assert_eq!(preview.current_notional, 0);
    assert_eq!(preview.candidate_notional, 100);
    assert_eq!(preview.required_initial, 10);
    assert_eq!(preview.equity_for_market, 0);
    assert_eq!(preview.margin_surplus, -10);

    service.set_isolated_collateral(7, 22, 10, 1_101);
    let funded_preview = service
        .preview_intent(order, None, Some(1_102))
        .expect("funded preview should run");
    assert!(funded_preview.would_succeed);
    assert_eq!(funded_preview.reason, None);
    assert_eq!(funded_preview.margin_surplus, 0);
}

