#[test]
fn json_rpc_rejects_invalid_market_fee_rebate_params() {
    for (maker_fee_bps, maker_rebate_bps, taker_fee_bps, expected_message) in [
        (
            25_u32,
            10_001_u32,
            50_u32,
            "maker_fee_bps, maker_rebate_bps, and taker_fee_bps must be <= 10000",
        ),
        (
            25_u32,
            76_u32,
            50_u32,
            "maker_rebate_bps must be <= maker_fee_bps + taker_fee_bps",
        ),
    ] {
        let server = JsonRpcHttpServer::new_with_config(
            Arc::new(Mutex::new(single_node_engine())),
            JsonRpcServerConfig {
                manual_block_production_enabled: false,
                mahi_enabled: false,
                operator_bearer_token: Some("secret-token".into()),
                peer_relay_bearer_token: None,
                network_bootstrap: None,
                peer_transport_enabled: false,
            },
        );
        let request = JsonRpcRequest {
            jsonrpc: "2.0".into(),
            method: "kombat_setMarketFees".into(),
            params: serde_json::to_value(SetMarketFeesParams {
                market_id: 7,
                maker_fee_bps,
                maker_rebate_bps,
                taker_fee_bps,
            })
            .expect("params should serialize"),
            id: json!(44),
        };
        let response = authorized_json_rpc_response(server, &request, "secret-token");
        assert_eq!(
            response.error,
            Some(super::JsonRpcErrorObject {
                code: -32602,
                message: expected_message.into(),
                data: None,
            })
        );
    }
}

#[test]
fn node_rpc_reads_funding_history() {
    let mut engine = single_node_engine();
    let orders = [
        OrderRequest {
            market_id: 7,
            account_id: 22,
            client_order_id: 1,
            side: OrderSide::Bid,
            quantity_lots: 3,
            kind: OrderKind::Limit { price_ticks: 100 },
            time_in_force: TimeInForce::Gtc,
            post_only: false,
        },
        OrderRequest {
            market_id: 7,
            account_id: 33,
            client_order_id: 2,
            side: OrderSide::Ask,
            quantity_lots: 3,
            kind: OrderKind::Limit { price_ticks: 100 },
            time_in_force: TimeInForce::Gtc,
            post_only: false,
        },
    ];

    let mut service = NodeRpcService::new(&mut engine);
    for (idx, order) in orders.into_iter().enumerate() {
        service
            .submit_order(order, 1_000 + idx as u64)
            .expect("order should succeed");
    }
    service.set_funding_index(7, 2, 1_010);

    let history = service.get_funding_history(Some(7), None, Some(0), 10);
    assert_eq!(history.len(), 3);
    assert_eq!(history[0].kind, FundingRecordKind::IndexUpdated);
    assert_eq!(history[0].funding_index, 2);
    assert_eq!(history[1].kind, FundingRecordKind::Applied);
    assert_eq!(history[1].account_id, Some(22));
    assert_eq!(history[1].funding_delta, Some(-6));
    assert_eq!(history[2].kind, FundingRecordKind::Applied);
    assert_eq!(history[2].account_id, Some(33));
    assert_eq!(history[2].funding_delta, Some(6));
}

