#[test]
fn node_rpc_reads_revenue_split_history() {
    let mut engine = single_node_engine();
    engine.update_market_fee_parameters(
        7,
        MarketFeeParameters {
            maker_fee_bps: 100,
            maker_rebate_bps: 0,
            taker_fee_bps: 200,
        },
    );
    let orders = [
        OrderRequest {
            market_id: 7,
            account_id: 22,
            client_order_id: 1,
            side: OrderSide::Ask,
            quantity_lots: 3,
            kind: OrderKind::Limit { price_ticks: 100 },
            time_in_force: TimeInForce::Gtc,
            post_only: false,
        },
        OrderRequest {
            market_id: 7,
            account_id: 33,
            client_order_id: 2,
            side: OrderSide::Bid,
            quantity_lots: 3,
            kind: OrderKind::Limit { price_ticks: 100 },
            time_in_force: TimeInForce::Gtc,
            post_only: false,
        },
    ];

    let mut service = NodeRpcService::new(&mut engine);
    for (idx, order) in orders.into_iter().enumerate() {
        service
            .submit_order(order, 1_000 + idx as u64)
            .expect("order should succeed");
    }

    let history = service.get_revenue_split_history(Some(7), Some(0), 10);
    assert_eq!(history.len(), 1);
    assert_eq!(history[0].source_fee_amount, 9);
    assert_eq!(history[0].validator_rewards_delta, 3);
    assert_eq!(history[0].validator_reward_balance, 3);
    assert_eq!(history[0].market_maker_rebate_delta, 2);
    assert_eq!(history[0].market_maker_rebate_balance, 2);
    assert_eq!(history[0].insurance_fund_delta, 0);
    assert_eq!(history[0].insurance_fund_balance, 0);
    assert_eq!(history[0].treasury_delta, 4);
    assert_eq!(history[0].treasury_balance, 4);

    let market = service.get_market_state(7);
    assert_eq!(market.fee_vault_balance, 0);
    assert_eq!(market.validator_reward_pool_balance, 3);
    assert_eq!(market.market_maker_rebate_pool_balance, 2);
    assert_eq!(market.treasury_balance, 4);
}

