#[test]
fn node_rpc_reads_account_risk_summary() {
    let mut engine = single_node_engine();
    let orders = [
        OrderRequest {
            market_id: 7,
            account_id: 22,
            client_order_id: 1,
            side: OrderSide::Bid,
            quantity_lots: 3,
            kind: OrderKind::Limit { price_ticks: 100 },
            time_in_force: TimeInForce::Gtc,
            post_only: false,
        },
        OrderRequest {
            market_id: 7,
            account_id: 33,
            client_order_id: 2,
            side: OrderSide::Ask,
            quantity_lots: 3,
            kind: OrderKind::Limit { price_ticks: 100 },
            time_in_force: TimeInForce::Gtc,
            post_only: false,
        },
        OrderRequest {
            market_id: 9,
            account_id: 22,
            client_order_id: 3,
            side: OrderSide::Ask,
            quantity_lots: 2,
            kind: OrderKind::Limit { price_ticks: 90 },
            time_in_force: TimeInForce::Gtc,
            post_only: false,
        },
        OrderRequest {
            market_id: 9,
            account_id: 44,
            client_order_id: 4,
            side: OrderSide::Bid,
            quantity_lots: 2,
            kind: OrderKind::Limit { price_ticks: 90 },
            time_in_force: TimeInForce::Gtc,
            post_only: false,
        },
    ];

    let mut service = NodeRpcService::new(&mut engine);
    for (idx, order) in orders.into_iter().enumerate() {
        service
            .submit_order(order, 1_000 + idx as u64)
            .expect("order should succeed");
    }

    let summary = service.get_account_risk_summary(22, None, None, false, 10);
    assert_eq!(summary.account_id, 22);
    assert_eq!(summary.market_count, 2);
    assert!(!summary.frozen);
    assert_eq!(summary.worst_market_id, Some(7));
    assert_eq!(summary.worst_liquidation_gap, 30);
    assert_eq!(summary.markets_cleared_by_suggested_liquidation, 0);
    assert_eq!(summary.markets_still_under_after_suggested_liquidation, 2);
    assert_eq!(summary.markets_freezing_after_suggested_liquidation, 0);
    assert_eq!(
        summary.markets_creating_bad_debt_after_suggested_liquidation,
        0
    );
    assert_eq!(summary.total_suggested_bad_debt, 0);
    assert_eq!(summary.total_bad_debt, 0);
    assert_eq!(summary.total_collateral, 0);
    assert_eq!(summary.total_realized_pnl, 0);
    assert_eq!(summary.total_unrealized_pnl, 0);
    assert_eq!(summary.total_equity, 0);
    assert_eq!(summary.total_open_notional, 480);
    assert_eq!(summary.total_initial_margin_required, 48);
    assert_eq!(summary.total_maintenance_requirement, 48);
    assert_eq!(summary.total_liquidation_gap, 48);
    assert_eq!(summary.total_margin_surplus, -48);
    assert_eq!(summary.under_maintenance_market_count, 2);

    let filtered = service.get_account_risk_summary(
        22,
        Some(7),
        Some(SuggestedLiquidationOutcome::StillUnderMaintenance),
        false,
        10,
    );
    assert_eq!(filtered.account_id, 22);
    assert_eq!(filtered.market_count, 1);
    assert_eq!(filtered.worst_market_id, Some(7));
    assert_eq!(filtered.total_open_notional, 300);
    assert_eq!(filtered.total_initial_margin_required, 30);
    assert_eq!(filtered.total_liquidation_gap, 30);
}

