#[test]
fn node_rpc_reads_liquidation_pressure_summary() {
    let mut engine = single_node_engine();
    let orders = [
        OrderRequest {
            market_id: 7,
            account_id: 22,
            client_order_id: 1,
            side: OrderSide::Bid,
            quantity_lots: 3,
            kind: OrderKind::Limit { price_ticks: 100 },
            time_in_force: TimeInForce::Gtc,
            post_only: false,
        },
        OrderRequest {
            market_id: 7,
            account_id: 33,
            client_order_id: 2,
            side: OrderSide::Ask,
            quantity_lots: 3,
            kind: OrderKind::Limit { price_ticks: 100 },
            time_in_force: TimeInForce::Gtc,
            post_only: false,
        },
        OrderRequest {
            market_id: 9,
            account_id: 22,
            client_order_id: 3,
            side: OrderSide::Ask,
            quantity_lots: 2,
            kind: OrderKind::Limit { price_ticks: 90 },
            time_in_force: TimeInForce::Gtc,
            post_only: false,
        },
        OrderRequest {
            market_id: 9,
            account_id: 44,
            client_order_id: 4,
            side: OrderSide::Bid,
            quantity_lots: 2,
            kind: OrderKind::Limit { price_ticks: 90 },
            time_in_force: TimeInForce::Gtc,
            post_only: false,
        },
        OrderRequest {
            market_id: 11,
            account_id: 66,
            client_order_id: 5,
            side: OrderSide::Bid,
            quantity_lots: 2,
            kind: OrderKind::Limit { price_ticks: 70 },
            time_in_force: TimeInForce::Gtc,
            post_only: false,
        },
        OrderRequest {
            market_id: 11,
            account_id: 77,
            client_order_id: 6,
            side: OrderSide::Ask,
            quantity_lots: 2,
            kind: OrderKind::Limit { price_ticks: 70 },
            time_in_force: TimeInForce::Gtc,
            post_only: false,
        },
    ];

    let mut service = NodeRpcService::new(&mut engine);
    for (idx, order) in orders.into_iter().enumerate() {
        service
            .submit_order(order, 1_000 + idx as u64)
            .expect("order should succeed");
    }

    let market_states = service.list_market_states(false, false, None, usize::MAX);
    let account_summaries =
        service.list_account_risk_summaries(None, false, None, false, usize::MAX);
    let summary = service.get_liquidation_pressure_summary(None, None);

    assert_eq!(summary.market_count, market_states.len());
    assert_eq!(summary.stressed_market_count, market_states.len());
    assert_eq!(summary.stressed_account_count, account_summaries.len());
    assert_eq!(summary.total_liquidation_candidate_count, 6);
    assert_eq!(
        summary.total_liquidation_gap,
        market_states
            .iter()
            .map(|state| state.total_liquidation_gap)
            .sum()
    );
    assert_eq!(summary.worst_market_id, Some(7));
    assert_eq!(summary.worst_account_id, Some(22));
    assert_eq!(summary.top_markets.len(), 3);
    assert_eq!(summary.top_markets[0].market_id, 7);
    assert_eq!(summary.top_accounts.len(), 5);
    assert_eq!(summary.top_accounts[0].account_id, 22);
    assert!(summary.latest_market_risk_transition.is_none());
    assert!(summary.recent_market_risk_transitions.is_empty());
    assert_eq!(summary.suggested_clear_count, 0);
    assert_eq!(
        summary.suggested_still_under_count,
        summary.total_liquidation_candidate_count
    );
    assert_eq!(summary.suggested_freeze_count, 0);
    assert_eq!(summary.suggested_bad_debt_count, 0);
    assert_eq!(summary.total_suggested_bad_debt, 0);

    let filtered = service.get_liquidation_pressure_summary(
        Some(7),
        Some(SuggestedLiquidationOutcome::StillUnderMaintenance),
    );
    assert_eq!(filtered.market_count, 1);
    assert_eq!(filtered.stressed_market_count, 1);
    assert_eq!(filtered.stressed_account_count, 2);
    assert_eq!(filtered.total_liquidation_candidate_count, 2);
    assert_eq!(filtered.worst_market_id, Some(7));
    assert_eq!(filtered.top_markets.len(), 1);
    assert_eq!(filtered.top_markets[0].market_id, 7);
    assert_eq!(filtered.top_accounts.len(), 2);
    assert_eq!(filtered.top_accounts[0].account_id, 22);
}

#[test]
fn node_rpc_exposes_liquidation_escalation_pressure() {
    let mut engine = single_node_engine();
    engine.set_market_risk_parameters(
        7,
        MarketRiskParameters {
            maintenance_margin_bps: 500,
            liquidation_penalty_bps: 0,
            liquidator_fee_bps: 0,
        },
    );
    engine.set_isolated_collateral(7, 22, 40);
    engine.set_isolated_collateral(7, 33, 100);

    let mut service = NodeRpcService::new(&mut engine);
    service
        .submit_order(
            OrderRequest {
                market_id: 7,
                account_id: 22,
                client_order_id: 1,
                side: OrderSide::Bid,
                quantity_lots: 3,
                kind: OrderKind::Limit { price_ticks: 100 },
                time_in_force: TimeInForce::Gtc,
                post_only: false,
            },
            1_000,
        )
        .expect("bid should fill");
    service
        .submit_order(
            OrderRequest {
                market_id: 7,
                account_id: 33,
                client_order_id: 2,
                side: OrderSide::Ask,
                quantity_lots: 3,
                kind: OrderKind::Limit { price_ticks: 100 },
                time_in_force: TimeInForce::Gtc,
                post_only: false,
            },
            1_001,
        )
        .expect("ask should fill");
    service.set_mark_price(7, 90, 1_002);

    service
        .liquidate_position(7, 22, 99, 5, Some(1), 1_003)
        .expect("stalled liquidation should succeed");

    let snapshot = service.get_risk_snapshot(7, 22);
    assert_eq!(snapshot.liquidation_stall_count, 1);
    assert_eq!(snapshot.liquidation_freeze_threshold, 2);
    assert!(snapshot.liquidation_freeze_imminent);

    let summary = service.get_account_risk_summary(22, Some(7), None, false, 10);
    assert_eq!(summary.max_liquidation_stall_count, 1);
    assert_eq!(summary.imminent_freeze_market_count, 1);

    let market = service.get_market_state(7);
    assert_eq!(market.imminent_freeze_count, 1);
    assert_eq!(market.max_liquidation_stall_count, 1);

    let pressure = service.get_liquidation_pressure_summary(Some(7), None);
    assert_eq!(pressure.imminent_freeze_market_count, 1);
    assert_eq!(pressure.imminent_freeze_account_count, 1);
}

#[test]
fn node_rpc_reads_liquidation_escalation_history() {
    let mut engine = single_node_engine();
    engine.set_market_risk_parameters(
        7,
        MarketRiskParameters {
            maintenance_margin_bps: 500,
            liquidation_penalty_bps: 0,
            liquidator_fee_bps: 0,
        },
    );
    engine.set_isolated_collateral(7, 22, 40);
    engine.set_isolated_collateral(7, 33, 100);

    let mut service = NodeRpcService::new(&mut engine);
    service
        .submit_order(
            OrderRequest {
                market_id: 7,
                account_id: 22,
                client_order_id: 1,
                side: OrderSide::Bid,
                quantity_lots: 3,
                kind: OrderKind::Limit { price_ticks: 100 },
                time_in_force: TimeInForce::Gtc,
                post_only: false,
            },
            1_000,
        )
        .expect("bid should fill");
    service
        .submit_order(
            OrderRequest {
                market_id: 7,
                account_id: 33,
                client_order_id: 2,
                side: OrderSide::Ask,
                quantity_lots: 3,
                kind: OrderKind::Limit { price_ticks: 100 },
                time_in_force: TimeInForce::Gtc,
                post_only: false,
            },
            1_001,
        )
        .expect("ask should fill");
    service.set_mark_price(7, 90, 1_002);
    service
        .liquidate_position(7, 22, 99, 5, Some(1), 1_003)
        .expect("stalled liquidation should succeed");

    let history = service.get_liquidation_escalation_history(Some(7), Some(22), Some(0), 10);
    assert_eq!(history.len(), 1);
    assert_eq!(history[0].market_id, 7);
    assert_eq!(history[0].account_id, 22);
    assert_eq!(history[0].action, LiquidationEscalationAction::Advanced);
    assert_eq!(history[0].stall_count, 1);
    assert_eq!(history[0].freeze_threshold, 2);
    assert!(history[0].freeze_imminent);
    assert_eq!(history[0].post_margin_surplus, -4);
    assert!(history[0].post_under_maintenance);
    assert!(!history[0].post_account_frozen);
}

#[test]
fn node_rpc_lists_under_margin_liquidation_candidates() {
    let mut engine = single_node_engine();
    engine.set_market_risk_parameters(
        7,
        MarketRiskParameters {
            maintenance_margin_bps: 500,
            liquidation_penalty_bps: 0,
            liquidator_fee_bps: 0,
        },
    );
    engine.set_market_risk_parameters(
        9,
        MarketRiskParameters {
            maintenance_margin_bps: 500,
            liquidation_penalty_bps: 0,
            liquidator_fee_bps: 0,
        },
    );
    engine.set_isolated_collateral(7, 22, 10);
    engine.set_isolated_collateral(7, 33, 100);
    engine.set_isolated_collateral(7, 44, 100);
    engine.set_isolated_collateral(7, 55, 100);
    engine.set_isolated_collateral(9, 22, 0);
    engine.set_isolated_collateral(9, 66, 100);
    let orders = [
        OrderRequest {
            market_id: 7,
            account_id: 22,
            client_order_id: 1,
            side: OrderSide::Bid,
            quantity_lots: 3,
            kind: OrderKind::Limit { price_ticks: 100 },
            time_in_force: TimeInForce::Gtc,
            post_only: false,
        },
        OrderRequest {
            market_id: 7,
            account_id: 33,
            client_order_id: 2,
            side: OrderSide::Ask,
            quantity_lots: 3,
            kind: OrderKind::Limit { price_ticks: 100 },
            time_in_force: TimeInForce::Gtc,
            post_only: false,
        },
        OrderRequest {
            market_id: 7,
            account_id: 44,
            client_order_id: 3,
            side: OrderSide::Bid,
            quantity_lots: 1,
            kind: OrderKind::Limit { price_ticks: 90 },
            time_in_force: TimeInForce::Gtc,
            post_only: false,
        },
        OrderRequest {
            market_id: 7,
            account_id: 55,
            client_order_id: 4,
            side: OrderSide::Ask,
            quantity_lots: 1,
            kind: OrderKind::Limit { price_ticks: 90 },
            time_in_force: TimeInForce::Gtc,
            post_only: false,
        },
        OrderRequest {
            market_id: 9,
            account_id: 22,
            client_order_id: 5,
            side: OrderSide::Bid,
            quantity_lots: 2,
            kind: OrderKind::Limit { price_ticks: 50 },
            time_in_force: TimeInForce::Gtc,
            post_only: false,
        },
        OrderRequest {
            market_id: 9,
            account_id: 66,
            client_order_id: 6,
            side: OrderSide::Ask,
            quantity_lots: 2,
            kind: OrderKind::Limit { price_ticks: 50 },
            time_in_force: TimeInForce::Gtc,
            post_only: false,
        },
    ];

    let mut service = NodeRpcService::new(&mut engine);
    for (idx, order) in orders.into_iter().enumerate() {
        service
            .submit_order(order, 1_000 + idx as u64)
            .expect("order should succeed");
    }

    let candidates = service.list_liquidation_candidates(None, None, false, None, 10);
    assert_eq!(candidates.len(), 2);
    assert_eq!(candidates[0].max_liquidatable_lots, 3);
    assert_eq!(candidates[0].suggested_liquidation_lots, Some(3));
    assert_eq!(
        candidates[0].suggested_liquidation_outcome,
        Some(SuggestedLiquidationOutcome::CreatesBadDebt)
    );
    assert!(!candidates[0].suggested_liquidation_clears_maintenance);
    assert_eq!(candidates[0].suggested_post_margin_surplus, Some(-34));
    assert_eq!(candidates[0].suggested_post_under_maintenance, Some(true));
    assert_eq!(candidates[0].suggested_post_account_frozen, Some(true));
    assert_eq!(
        candidates[0].suggested_post_market_bad_debt_balance,
        Some(20)
    );
    assert_eq!(candidates[0].market_id, 7);
    assert_eq!(candidates[0].account_id, 22);
    assert!(candidates[0].under_maintenance);
    assert_eq!(candidates[0].liquidation_gap, 34);
    assert_eq!(candidates[0].margin_surplus, -34);
    let market_state = service.get_market_state(7);
    assert_eq!(market_state.liquidation_candidate_count, 1);
    assert_eq!(market_state.total_liquidation_gap, 34);
    assert_eq!(market_state.worst_liquidation_gap, 34);
    assert_eq!(market_state.total_suggested_bad_debt, 20);
    assert_eq!(candidates[1].market_id, 9);
    assert_eq!(candidates[1].account_id, 22);
    assert!(candidates[1].under_maintenance);
    assert_eq!(candidates[1].margin_surplus, -5);
}

