#[test]
fn node_rpc_lists_positions_across_markets() {
    let mut engine = single_node_engine();
    let first_ask = OrderRequest {
        market_id: 7,
        account_id: 22,
        client_order_id: 1,
        side: OrderSide::Ask,
        quantity_lots: 5,
        kind: OrderKind::Limit { price_ticks: 103 },
        time_in_force: TimeInForce::Gtc,
        post_only: false,
    };
    let first_bid = OrderRequest {
        market_id: 7,
        account_id: 33,
        client_order_id: 2,
        side: OrderSide::Bid,
        quantity_lots: 3,
        kind: OrderKind::Limit { price_ticks: 104 },
        time_in_force: TimeInForce::Gtc,
        post_only: false,
    };
    let second_bid = OrderRequest {
        market_id: 9,
        account_id: 22,
        client_order_id: 3,
        side: OrderSide::Bid,
        quantity_lots: 4,
        kind: OrderKind::Limit { price_ticks: 99 },
        time_in_force: TimeInForce::Gtc,
        post_only: false,
    };
    let second_ask = OrderRequest {
        market_id: 9,
        account_id: 44,
        client_order_id: 4,
        side: OrderSide::Ask,
        quantity_lots: 4,
        kind: OrderKind::Limit { price_ticks: 98 },
        time_in_force: TimeInForce::Gtc,
        post_only: false,
    };

    let mut service = NodeRpcService::new(&mut engine);
    service
        .submit_order(first_ask, 1_000)
        .expect("first ask should rest");
    service
        .submit_order(first_bid, 1_001)
        .expect("first bid should fill");
    service
        .submit_order(second_bid, 1_002)
        .expect("second bid should rest");
    service
        .submit_order(second_ask, 1_003)
        .expect("second ask should fill");

    let positions = service.list_positions(22, false, 10);
    assert_eq!(positions.len(), 2);
    assert_eq!(positions[0].market_id, 7);
    assert_eq!(positions[0].side, PositionSide::Short);
    assert_eq!(positions[1].market_id, 9);
    assert_eq!(positions[1].side, PositionSide::Long);
}

