#[test]
fn node_rpc_replaces_and_cancels_orders() {
    let mut engine = single_node_engine();
    let order = OrderRequest {
        market_id: 7,
        account_id: 22,
        client_order_id: 1,
        side: OrderSide::Ask,
        quantity_lots: 5,
        kind: OrderKind::Limit { price_ticks: 103 },
        time_in_force: TimeInForce::Gtc,
        post_only: false,
    };
    let replacement = OrderRequest {
        market_id: 7,
        account_id: 22,
        client_order_id: 1,
        side: OrderSide::Ask,
        quantity_lots: 7,
        kind: OrderKind::Limit { price_ticks: 102 },
        time_in_force: TimeInForce::Gtc,
        post_only: false,
    };

    let mut service = NodeRpcService::new(&mut engine);
    service
        .submit_order(order, 1_000)
        .expect("order should rest");
    let replaced = service
        .replace_order(7, 22, 1, replacement, 1_100)
        .expect("replace should succeed");
    assert_eq!(replaced.status, MatchStatus::Resting);

    let after_replace = service.get_order_status(7, 22, 1);
    assert_eq!(after_replace.stage, OrderStatusStage::Resting);
    assert_eq!(after_replace.remaining_lots, 7);

    let cancelled = service.cancel_order(7, 22, 1, 1_200);
    assert!(cancelled.cancelled);
    assert_eq!(
        cancelled.order.expect("order should exist").price_ticks,
        102
    );
    assert!(service.get_open_orders(7, 22, 10).is_empty());

    let after_cancel = service.get_order_status(7, 22, 1);
    assert_eq!(after_cancel.stage, OrderStatusStage::Cancelled);
    assert_eq!(after_cancel.remaining_lots, 0);
}

#[test]
fn json_rpc_submit_order_returns_structured_error_and_reads_book() {
    let server = JsonRpcHttpServer::new(Arc::new(Mutex::new(single_node_engine())));

    let invalid_submit = serde_json::to_string(&JsonRpcRequest {
        jsonrpc: "2.0".into(),
        method: "kombat_submitOrder".into(),
        params: json!({
            "order": {
                "market_id": 7,
                "account_id": 22,
                "client_order_id": 1,
                "side": "bid",
                "quantity_lots": 0,
                "order_kind": "limit",
                "price_ticks": 101,
                "time_in_force": { "tif": "gtc" },
                "post_only": false,
            },
            "timestamp_ms": 1_000,
        }),
        id: json!(41),
    })
    .expect("request should serialize");

    let invalid_response: JsonRpcResponse =
        serde_json::from_str(&server.handle_json_request(&invalid_submit))
            .expect("response should parse");
    let invalid_error = invalid_response.error.expect("error should exist");
    assert_eq!(invalid_error.code, -32023);
    assert_eq!(invalid_error.message, "order submission rejected");
    let invalid_data = invalid_error.data.expect("error data should exist");
    assert_eq!(invalid_data["kind"], "order_submission");
    assert_eq!(invalid_data["reason"], "zero_quantity");
    assert_eq!(invalid_data["order_reason"], "zero_quantity");

    let valid_submit = serde_json::to_string(&JsonRpcRequest {
        jsonrpc: "2.0".into(),
        method: "kombat_submitOrder".into(),
        params: json!({
            "order": {
                "market_id": 7,
                "account_id": 22,
                "client_order_id": 1,
                "side": "ask",
                "quantity_lots": 5,
                "order_kind": "limit",
                "price_ticks": 103,
                "time_in_force": { "tif": "gtc" },
                "post_only": false,
            },
            "timestamp_ms": 1_000,
        }),
        id: json!(42),
    })
    .expect("request should serialize");
    let valid_response: JsonRpcResponse =
        serde_json::from_str(&server.handle_json_request(&valid_submit))
            .expect("response should parse");
    let valid_result = valid_response.result.expect("result should exist");
    assert_eq!(valid_result["status"], "resting");
    assert_eq!(valid_result["posted_order_id"], 1);

    let book_request = serde_json::to_string(&JsonRpcRequest {
        jsonrpc: "2.0".into(),
        method: "kombat_getOrderBook".into(),
        params: json!({
            "market_id": 7,
            "depth": 5,
        }),
        id: json!(43),
    })
    .expect("request should serialize");
    let book_response: JsonRpcResponse =
        serde_json::from_str(&server.handle_json_request(&book_request))
            .expect("response should parse");
    let book_result = book_response.result.expect("result should exist");
    assert_eq!(book_result["market_id"], 7);
    assert_eq!(book_result["asks"][0]["price_ticks"], 103);

    let open_orders_request = serde_json::to_string(&JsonRpcRequest {
        jsonrpc: "2.0".into(),
        method: "kombat_getOpenOrders".into(),
        params: json!({
            "market_id": 7,
            "account_id": 22,
            "limit": 10,
        }),
        id: json!(44),
    })
    .expect("request should serialize");
    let open_orders_response: JsonRpcResponse =
        serde_json::from_str(&server.handle_json_request(&open_orders_request))
            .expect("response should parse");
    let open_orders_result = open_orders_response.result.expect("result should exist");
    assert_eq!(open_orders_result[0]["client_order_id"], 1);
    assert_eq!(open_orders_result[0]["side"], "ask");
}

