#[test]
fn json_rpc_lists_liquidation_escalation_events() {
    let mut engine = single_node_engine();
    engine.set_market_risk_parameters(
        7,
        MarketRiskParameters {
            maintenance_margin_bps: 500,
            liquidation_penalty_bps: 0,
            liquidator_fee_bps: 0,
        },
    );
    engine.set_isolated_collateral(7, 22, 40);
    engine.set_isolated_collateral(7, 33, 100);
    for (order, timestamp_ms) in [
        (
            OrderRequest {
                market_id: 7,
                account_id: 22,
                client_order_id: 1,
                side: OrderSide::Bid,
                quantity_lots: 3,
                kind: OrderKind::Limit { price_ticks: 100 },
                time_in_force: TimeInForce::Gtc,
                post_only: false,
            },
            1_000,
        ),
        (
            OrderRequest {
                market_id: 7,
                account_id: 33,
                client_order_id: 2,
                side: OrderSide::Ask,
                quantity_lots: 3,
                kind: OrderKind::Limit { price_ticks: 100 },
                time_in_force: TimeInForce::Gtc,
                post_only: false,
            },
            1_001,
        ),
    ] {
        engine
            .submit_order(order, timestamp_ms)
            .expect("order should fill");
    }
    engine.update_market_mark_price(7, 90, 1_002);
    engine
        .liquidate_position_with_size(7, 22, 99, 5, Some(1), 1_003)
        .expect("stalled liquidation should succeed");
    let server = JsonRpcHttpServer::new(Arc::new(Mutex::new(engine)));

    let body = serde_json::to_string(&JsonRpcRequest {
        jsonrpc: "2.0".into(),
        method: "kombat_listEvents".into(),
        params: json!({
            "from_seq": 0,
            "limit": 10,
            "filter": {
                "account_id": 22,
                "market_id": 7,
                "policy_id": null,
                "intent_id_hex": null,
                "topic": "liquidation_escalation_updated"
            }
        }),
        id: json!(96),
    })
    .expect("request should serialize");
    let response: JsonRpcResponse =
        serde_json::from_str(&server.handle_json_request(&body)).expect("response should parse");
    let result = response.result.expect("result should exist");
    let events = result["events"].as_array().expect("array");
    assert_eq!(events.len(), 1);
    assert_eq!(events[0]["kind"]["topic"], "liquidation_escalation_updated");
    assert_eq!(events[0]["kind"]["market_id"], 7);
    assert_eq!(events[0]["kind"]["account_id"], 22);
    assert_eq!(events[0]["kind"]["action"], "advanced");
    assert_eq!(events[0]["kind"]["stall_count"], 1);
    assert_eq!(events[0]["kind"]["freeze_threshold"], 2);
    assert_eq!(events[0]["kind"]["freeze_imminent"], true);
    assert_eq!(events[0]["kind"]["post_margin_surplus"], "-4");
    assert_eq!(events[0]["kind"]["post_under_maintenance"], true);
    assert_eq!(events[0]["kind"]["post_account_frozen"], false);
}

