#[test]
fn json_rpc_gets_liquidation_pressure_summary() {
    let mut engine = single_node_engine();
    let orders = [
        OrderRequest {
            market_id: 7,
            account_id: 22,
            client_order_id: 1,
            side: OrderSide::Bid,
            quantity_lots: 3,
            kind: OrderKind::Limit { price_ticks: 100 },
            time_in_force: TimeInForce::Gtc,
            post_only: false,
        },
        OrderRequest {
            market_id: 7,
            account_id: 33,
            client_order_id: 2,
            side: OrderSide::Ask,
            quantity_lots: 3,
            kind: OrderKind::Limit { price_ticks: 100 },
            time_in_force: TimeInForce::Gtc,
            post_only: false,
        },
        OrderRequest {
            market_id: 9,
            account_id: 22,
            client_order_id: 3,
            side: OrderSide::Ask,
            quantity_lots: 2,
            kind: OrderKind::Limit { price_ticks: 90 },
            time_in_force: TimeInForce::Gtc,
            post_only: false,
        },
        OrderRequest {
            market_id: 9,
            account_id: 44,
            client_order_id: 4,
            side: OrderSide::Bid,
            quantity_lots: 2,
            kind: OrderKind::Limit { price_ticks: 90 },
            time_in_force: TimeInForce::Gtc,
            post_only: false,
        },
        OrderRequest {
            market_id: 11,
            account_id: 66,
            client_order_id: 5,
            side: OrderSide::Bid,
            quantity_lots: 2,
            kind: OrderKind::Limit { price_ticks: 70 },
            time_in_force: TimeInForce::Gtc,
            post_only: false,
        },
        OrderRequest {
            market_id: 11,
            account_id: 77,
            client_order_id: 6,
            side: OrderSide::Ask,
            quantity_lots: 2,
            kind: OrderKind::Limit { price_ticks: 70 },
            time_in_force: TimeInForce::Gtc,
            post_only: false,
        },
    ];
    {
        let mut service = NodeRpcService::new(&mut engine);
        for (idx, order) in orders.into_iter().enumerate() {
            service
                .submit_order(order, 1_000 + idx as u64)
                .expect("order should succeed");
        }
    }
    let server = JsonRpcHttpServer::new(Arc::new(Mutex::new(engine)));

    let body = serde_json::to_string(&JsonRpcRequest {
        jsonrpc: "2.0".into(),
        method: "kombat_getLiquidationPressureSummary".into(),
        params: json!({
            "market_id": null,
            "outcome": null
        }),
        id: json!(123),
    })
    .expect("request should serialize");
    let response: JsonRpcResponse =
        serde_json::from_str(&server.handle_json_request(&body)).expect("response should parse");
    let result = response.result.expect("result should exist");
    assert_eq!(result["market_count"], 3);
    assert_eq!(result["stressed_market_count"], 3);
    assert_eq!(result["stressed_account_count"], 5);
    assert_eq!(result["total_liquidation_candidate_count"], 6);
    assert_eq!(result["worst_market_id"], 7);
    assert_eq!(result["worst_account_id"], 22);
    assert_eq!(result["suggested_clear_count"], 0);
    assert_eq!(result["suggested_still_under_count"], 6);
    assert_eq!(result["suggested_freeze_count"], 0);
    assert_eq!(result["suggested_bad_debt_count"], 0);
    assert_eq!(result["total_suggested_bad_debt"], "0");
    let top_markets = result["top_markets"]
        .as_array()
        .expect("top_markets should be an array");
    assert_eq!(top_markets.len(), 3);
    assert_eq!(top_markets[0]["market_id"], 7);
    let top_accounts = result["top_accounts"]
        .as_array()
        .expect("top_accounts should be an array");
    assert_eq!(top_accounts.len(), 5);
    assert_eq!(top_accounts[0]["account_id"], 22);
    assert!(result["latest_market_risk_transition"].is_null());
    assert_eq!(
        result["recent_market_risk_transitions"]
            .as_array()
            .expect("recent_market_risk_transitions should be an array")
            .len(),
        0
    );

    let filtered_body = serde_json::to_string(&JsonRpcRequest {
        jsonrpc: "2.0".into(),
        method: "kombat_getLiquidationPressureSummary".into(),
        params: json!({
            "market_id": 7,
            "outcome": "still_under_maintenance"
        }),
        id: json!(1231),
    })
    .expect("request should serialize");
    let filtered_response: JsonRpcResponse =
        serde_json::from_str(&server.handle_json_request(&filtered_body))
            .expect("response should parse");
    let filtered_result = filtered_response.result.expect("result should exist");
    assert_eq!(filtered_result["market_count"], 1);
    assert_eq!(filtered_result["stressed_market_count"], 1);
    assert_eq!(filtered_result["stressed_account_count"], 2);
    assert_eq!(filtered_result["total_liquidation_candidate_count"], 2);
    assert_eq!(filtered_result["worst_market_id"], 7);
    assert!(filtered_result["latest_market_risk_transition"].is_null());
    assert_eq!(
        filtered_result["recent_market_risk_transitions"]
            .as_array()
            .expect("recent_market_risk_transitions should be an array")
            .len(),
        0
    );
    let filtered_top_markets = filtered_result["top_markets"]
        .as_array()
        .expect("top_markets should be an array");
    assert_eq!(filtered_top_markets.len(), 1);
    assert_eq!(filtered_top_markets[0]["market_id"], 7);
    let filtered_top_accounts = filtered_result["top_accounts"]
        .as_array()
        .expect("top_accounts should be an array");
    assert_eq!(filtered_top_accounts.len(), 2);
    assert_eq!(filtered_top_accounts[0]["account_id"], 22);
}

