#[test]
fn json_rpc_replace_order_intent_updates_book_after_block() {
    let signer = signing_key(8);
    let mut engine = single_node_engine();
    engine
        .policy_store_mut()
        .insert(sample_policy())
        .expect("policy should insert");
    let server = JsonRpcHttpServer::new(Arc::new(Mutex::new(engine)));

    let place = signed_intent(
        &signer,
        1,
        10_000,
        IntentKind::PlaceOrder {
            market_id: 7,
            client_order_id: 99,
            side: IntentOrderSide::Ask,
            quantity_lots: 5,
            kind: IntentOrderKind::Limit { price_ticks: 103 },
            time_in_force: IntentTimeInForce::Gtc,
            post_only: false,
        },
    );
    let replace = signed_intent(
        &signer,
        2,
        10_000,
        IntentKind::ReplaceOrder {
            market_id: 7,
            target_client_order_id: 99,
            replacement_client_order_id: 100,
            side: IntentOrderSide::Ask,
            quantity_lots: 4,
            kind: IntentOrderKind::Limit { price_ticks: 102 },
            time_in_force: IntentTimeInForce::Gtc,
            post_only: false,
        },
    );

    for (id, signed, params) in [
        (
            81,
            place,
            json!({
                "kind": "place_order",
                "market_id": 7,
                "client_order_id": 99,
                "side": "ask",
                "quantity_lots": 5,
                "order_kind": "limit",
                "price_ticks": 103,
                "time_in_force": { "tif": "gtc" },
                "post_only": false
            }),
        ),
        (
            82,
            replace,
            json!({
                "kind": "replace_order",
                "market_id": 7,
                "target_client_order_id": 99,
                "replacement_client_order_id": 100,
                "side": "ask",
                "quantity_lots": 4,
                "order_kind": "limit",
                "price_ticks": 102,
                "time_in_force": { "tif": "gtc" },
                "post_only": false
            }),
        ),
    ] {
        let submit_body = serde_json::to_string(&JsonRpcRequest {
            jsonrpc: "2.0".into(),
            method: "kombat_submitIntent".into(),
            params: json!({
                "signed_intent": {
                    "intent": {
                        "chain_id": signed.intent.chain_id,
                        "account": signed.intent.account,
                        "policy_id": signed.intent.policy_id,
                        "nonce": signed.intent.nonce,
                        "expires_at": signed.intent.expires_at,
                        "predicate": null,
                        "kind": params["kind"],
                        "market_id": params["market_id"],
                        "client_order_id": params.get("client_order_id").cloned().unwrap_or(json!(null)),
                        "target_client_order_id": params.get("target_client_order_id").cloned().unwrap_or(json!(null)),
                        "replacement_client_order_id": params.get("replacement_client_order_id").cloned().unwrap_or(json!(null)),
                        "side": params["side"],
                        "quantity_lots": params["quantity_lots"],
                        "order_kind": params["order_kind"],
                        "price_ticks": params["price_ticks"],
                        "time_in_force": params["time_in_force"],
                        "post_only": params["post_only"]
                    },
                    "signature_hex": encode_hex(&signed.signature),
                },
                "timestamp_ms": 1_100 + (id as u64 - 81) * 10,
            }),
            id: json!(id),
        })
        .expect("request should serialize");
        let submit_response: JsonRpcResponse =
            serde_json::from_str(&server.handle_json_request(&submit_body))
                .expect("response should parse");
        assert!(
            submit_response.error.is_none(),
            "{:?}",
            submit_response.error
        );
    }

    let produce_body = serde_json::to_string(&JsonRpcRequest {
        jsonrpc: "2.0".into(),
        method: "kombat_produceBlock".into(),
        params: json!({
            "timestamp_ms": 1_200,
            "max_items": 10
        }),
        id: json!(83),
    })
    .expect("request should serialize");
    let produce_response: JsonRpcResponse =
        serde_json::from_str(&server.handle_json_request(&produce_body))
            .expect("response should parse");
    assert!(
        produce_response.error.is_none(),
        "{:?}",
        produce_response.error
    );

    let open_orders_body = serde_json::to_string(&JsonRpcRequest {
        jsonrpc: "2.0".into(),
        method: "kombat_getOpenOrders".into(),
        params: json!({
            "market_id": 7,
            "account_id": 11,
            "limit": 10,
        }),
        id: json!(84),
    })
    .expect("request should serialize");
    let open_orders_response: JsonRpcResponse =
        serde_json::from_str(&server.handle_json_request(&open_orders_body))
            .expect("response should parse");
    let open_orders_result = open_orders_response.result.expect("result should exist");
    assert_eq!(open_orders_result[0]["client_order_id"], 100);
    assert_eq!(open_orders_result[0]["price_ticks"], 102);
}

#[test]
fn json_rpc_create_account_returns_structured_error() {
    let signer = signing_key(8);
    let server = JsonRpcHttpServer::new(Arc::new(Mutex::new(single_node_engine())));

    let body = serde_json::to_string(&JsonRpcRequest {
        jsonrpc: "2.0".into(),
        method: "kombat_createAccount".into(),
        params: json!({
            "account_id": 11,
            "owner_hex": encode_hex(signer.verifying_key().as_bytes()),
            "code_hash_hex": encode_hex(&[9; 32]),
            "timestamp_ms": 1_000,
        }),
        id: json!(15),
    })
    .expect("request should serialize");

    let first: JsonRpcResponse =
        serde_json::from_str(&server.handle_json_request(&body)).expect("response should parse");
    assert!(first.error.is_none(), "{:?}", first.error);

    let second: JsonRpcResponse =
        serde_json::from_str(&server.handle_json_request(&body)).expect("response should parse");
    let error = second.error.expect("error should exist");
    assert_eq!(error.code, -32022);
    assert_eq!(error.message, "account creation rejected");
    let data = error.data.expect("error data should exist");
    assert_eq!(data["kind"], "account_creation");
    assert_eq!(data["reason"], "duplicate_account");
    assert_eq!(data["account_id"], 11);
}

