#[test]
fn node_rpc_reads_policy_and_runtime_events() {
    let signer = signing_key(8);
    let mut engine = single_node_engine();
    engine
        .create_account(11, signer.verifying_key().to_bytes(), [9; 32], 1_000)
        .expect("account should create");
    engine
        .submit_owner_call(
            kombat_chain_policy::SignedOwnerCall {
                account_id: 11,
                chain_id: 7,
                call: OwnerCall {
                    signer: signer.verifying_key().to_bytes(),
                    nonce: 0,
                    action: OwnerAction::CreatePolicy {
                        policy_id: 42,
                        grantee: signer.verifying_key().to_bytes(),
                        expires_at: 50_000,
                        terms: sample_policy().terms.clone(),
                    },
                },
                signature: signer
                    .sign(
                        &borsh::to_vec(&(
                            11_u64,
                            7_u64,
                            &OwnerCall {
                                signer: signer.verifying_key().to_bytes(),
                                nonce: 0,
                                action: OwnerAction::CreatePolicy {
                                    policy_id: 42,
                                    grantee: signer.verifying_key().to_bytes(),
                                    expires_at: 50_000,
                                    terms: sample_policy().terms.clone(),
                                },
                            },
                        ))
                        .expect("owner call should serialize"),
                    )
                    .to_bytes(),
            },
            1_050,
        )
        .expect("policy should create");
    engine
        .submit_intent(
            signed_intent(&signer, 1, 10_000, IntentKind::Cancel { order_id: 7 }),
            1_100,
        )
        .expect("intent should admit");

    let service = NodeRpcService::new(&mut engine);

    let policy = service
        .get_policy(42)
        .expect("policy lookup should succeed");
    assert_eq!(
        policy,
        PolicyResponse {
            id: 42,
            authority_account: 11,
            account: 11,
            execution_account_id: 11,
            execution_scope: PolicyExecutionScopeResponse {
                kind: PolicyExecutionScopeKindResponse::Account,
                delegation_id_hex: None,
            },
            parent_policy_id: None,
            state: PolicyState::Active,
            next_intent_nonce: 1,
            delegation_depth: 0,
            revoked_at: None,
            terms: PolicyTermsWireJson {
                gas_budget_per_day: 100,
                gas_refill_per_day: 100,
                max_intents_per_second: 2,
                max_intents_per_day: 10,
                max_volume_per_day: 1_000,
                max_drawdown_pct: 25,
            },
        }
    );

    let page = service.list_events(
        None,
        None,
        10,
        EventFilter {
            block_height: None,
            market_id: None,
            account_id: None,
            policy_id: Some(42),
            intent_id: None,
            client_order_id: None,
            topic: Some(RuntimeEventTopic::IntentAccepted),
        },
        false,
    );
    assert_eq!(page.events.len(), 1);
    assert_eq!(page.events[0].seq, 2);
    assert_eq!(page.next_cursor.next_seq, 3);
}

