#[test]
fn node_rpc_refreshes_and_revokes_operator_attestation() {
    let subject_signer = signing_key(1);
    let operator_signer = signing_key(2);
    let mut engine = single_node_engine();
    engine
        .create_account(
            11,
            subject_signer.verifying_key().to_bytes(),
            [0; 32],
            1_000,
        )
        .expect("subject account should create");
    engine
        .create_account(
            22,
            operator_signer.verifying_key().to_bytes(),
            [0; 32],
            1_000,
        )
        .expect("operator account should create");
    engine
        .register_agent_identity(
            RegisterAgentIdentityInput {
                account: 11,
                display_name: "Scout 001".into(),
                description: "Conservative BTC scout".into(),
                kind: AgentKind::Unknown,
                operator: Some(22),
                contact_uri: None,
            },
            1_100,
        )
        .expect("identity should register");
    let mut service = NodeRpcService::new(&mut engine);
    let mandate_id = [7_u8; 32];
    service
        .submit_identity_action(SubmitIdentityActionParams {
            signed_identity_action: sample_signed_operator_attestation_action_json(
                22,
                11,
                0,
                mandate_id,
                &operator_signer,
            ),
            timestamp_ms: 1_200,
        })
        .expect("operator attestation should register");
    let record_id_hex = service
        .list_attestations(11, Some("operator_self"), false, false, 100, None)
        .items
        .first()
        .expect("attestation should list")
        .record_id_hex
        .clone();
    let record_id = decode_hex_array::<32>(&record_id_hex).expect("record id should decode");
    let refreshed_expires_at = 7_200_000;

    let refreshed = service
        .submit_identity_action(SubmitIdentityActionParams {
            signed_identity_action: sample_signed_operator_refresh_action_json(
                22,
                1,
                record_id,
                refreshed_expires_at,
                &operator_signer,
            ),
            timestamp_ms: 1_300,
        })
        .expect("operator attestation should refresh");
    assert_eq!(refreshed.tier, IdentityTierResponse::Tier1OperatorAttested);
    let listed = service.list_attestations(11, Some("operator_self"), false, false, 100, None);
    assert_eq!(
        listed.items[0].expires_at_timestamp_ms,
        refreshed_expires_at
    );

    let revoked = service
        .submit_identity_action(SubmitIdentityActionParams {
            signed_identity_action: sample_signed_revoke_attestation_action_json(
                11,
                0,
                record_id,
                &subject_signer,
            ),
            timestamp_ms: 1_400,
        })
        .expect("subject revoke should submit");
    assert_eq!(revoked.tier, IdentityTierResponse::Tier0Unattested);
    let listed = service.list_attestations(11, Some("operator_self"), true, false, 100, None);
    assert_eq!(
        listed.items[0].revoked_at_block,
        Some(service.engine.head().header.height)
    );
}

