#[test]
fn node_rpc_rejects_tier1_mandate_without_matching_active_operator_attestation() {
    {
        let agent_signer = signing_key(3);
        let operator_signer = signing_key(2);
        let mut engine = single_node_engine();
        seed_identity_with_operator(&mut engine, 33, &agent_signer, 22, &operator_signer);
        let mut service = NodeRpcService::new(&mut engine);
        let mut params = sample_create_mandate_params(33, 7);
        params.activation_tier = Some(1);
        params.timestamp_ms = 1_300;

        service
            .submit_identity_action(SubmitIdentityActionParams {
                signed_identity_action: sample_signed_operator_attestation_action_json(
                    22,
                    33,
                    0,
                    [9_u8; 32],
                    &operator_signer,
                ),
                timestamp_ms: 1_200,
            })
            .expect("operator attestation should register");

        let err = service
            .create_mandate(params)
            .expect_err("attestation bound to another mandate should reject");
        assert_mandate_activation_error(err, "tier1_operator_attested", "tier1_operator_attested");
    }

    {
        let agent_signer = signing_key(4);
        let operator_signer = signing_key(5);
        let mut engine = single_node_engine();
        seed_identity_with_operator(&mut engine, 44, &agent_signer, 55, &operator_signer);
        let mut service = NodeRpcService::new(&mut engine);

        service
            .submit_identity_action(SubmitIdentityActionParams {
                signed_identity_action: sample_signed_operator_attestation_action_json_with_claim(
                    55,
                    44,
                    0,
                    AttestationClaim::RunsCodeHash {
                        code_hash: [8_u8; 32],
                        model_hash: None,
                    },
                    3_700_000,
                    &operator_signer,
                ),
                timestamp_ms: 1_200,
            })
            .expect("runs-code attestation should register");
        assert_eq!(
            service.get_agent_identity(44).tier,
            IdentityTierResponse::Tier1OperatorAttested
        );

        let mut params = sample_create_mandate_params(44, 7);
        params.activation_tier = Some(1);
        params.timestamp_ms = 1_300;
        let err = service
            .create_mandate(params)
            .expect_err("runs-code-only attestation should not satisfy mandate binding");
        assert_mandate_activation_error(err, "tier1_operator_attested", "tier1_operator_attested");
    }

    {
        let agent_signer = signing_key(6);
        let operator_signer = signing_key(7);
        let mut engine = single_node_engine();
        seed_identity_with_operator(&mut engine, 66, &agent_signer, 77, &operator_signer);
        let mut service = NodeRpcService::new(&mut engine);
        let mut params = sample_create_mandate_params(66, 7);
        params.activation_tier = Some(1);
        params.timestamp_ms = 1_200 + OPERATOR_ATTESTATION_MIN_EXPIRY_MS;
        let mandate_id = mandate_id_for_params(&params);
        let expires_at = params.timestamp_ms;

        service
            .submit_identity_action(SubmitIdentityActionParams {
                signed_identity_action: sample_signed_operator_attestation_action_json_with_claim(
                    77,
                    66,
                    0,
                    AttestationClaim::BoundToMandate { mandate_id },
                    expires_at,
                    &operator_signer,
                ),
                timestamp_ms: 1_200,
            })
            .expect("operator attestation should register");
        service
            .engine
            .produce_empty_block(expires_at)
            .expect("expiry block should produce");

        let err = service
            .create_mandate(params)
            .expect_err("expired attestation should reject");
        assert_mandate_activation_error(err, "tier0_unattested", "tier1_operator_attested");
    }
}

