#[test]
fn node_rpc_reads_account_history() {
    let signer = signing_key(8);
    let mut engine = single_node_engine();
    let mut service = NodeRpcService::new(&mut engine);
    service
        .create_account(11, signer.verifying_key().to_bytes(), [9; 32], None, 1_000)
        .expect("account should create");
    let pause_call = OwnerCall {
        signer: signer.verifying_key().to_bytes(),
        nonce: 0,
        action: OwnerAction::Pause,
    };
    service
        .submit_owner_call(
            kombat_chain_policy::SignedOwnerCall {
                account_id: 11,
                chain_id: 7,
                call: pause_call.clone(),
                signature: signer
                    .sign(
                        &borsh::to_vec(&(11_u64, 7_u64, &pause_call))
                            .expect("owner call should serialize"),
                    )
                    .to_bytes(),
            },
            1_100,
        )
        .expect("pause should succeed");

    let history = service.get_account_history(11, Some(0), 10);
    assert_eq!(history.len(), 2);
    assert_eq!(history[0].account_id, 11);
    match &history[0].kind {
        super::AccountHistoryKindResponse::Created { owner } => {
            assert_eq!(owner, &signer.verifying_key().to_bytes());
        }
        other => panic!("unexpected account history kind: {other:?}"),
    }
    match &history[1].kind {
        super::AccountHistoryKindResponse::Updated {
            action,
            paused,
            nonce,
            ..
        } => {
            assert_eq!(*action, super::AccountUpdateAction::Pause);
            assert!(*paused);
            assert_eq!(*nonce, 1);
        }
        other => panic!("unexpected account history kind: {other:?}"),
    }
}

#[test]
fn json_rpc_server_handles_submit_and_event_query() {
    let signer = signing_key(8);
    let grantee = signing_key(9);
    let server = JsonRpcHttpServer::new(Arc::new(Mutex::new(single_node_engine())));

    let create_account_body = serde_json::to_string(&JsonRpcRequest {
        jsonrpc: "2.0".into(),
        method: "kombat_createAccount".into(),
        params: json!({
            "account_id": 11,
            "owner_hex": encode_hex(signer.verifying_key().as_bytes()),
            "code_hash_hex": encode_hex(&[9; 32]),
            "timestamp_ms": 1_000,
        }),
        id: json!(0),
    })
    .expect("request serialization should succeed");
    let create_account_response: JsonRpcResponse =
        serde_json::from_str(&server.handle_json_request(&create_account_body))
            .expect("json-rpc response should deserialize");
    assert!(create_account_response.error.is_none());

    let create_policy_params = SubmitOwnerCallParams {
        signed_owner_call: serde_json::from_value(signed_owner_call_json(
            &signer,
            11,
            7,
            0,
            OwnerActionJson::CreatePolicy {
                policy_id: 42,
                grantee_hex: encode_hex(grantee.verifying_key().as_bytes()),
                expires_at: 50_000,
                terms: PolicyTermsWireJson {
                    gas_budget_per_day: 100,
                    gas_refill_per_day: 100,
                    max_intents_per_second: 2,
                    max_intents_per_day: 10,
                    max_volume_per_day: 1_000,
                    max_drawdown_pct: 25,
                },
            },
        ))
        .expect("signed owner call should deserialize"),
        timestamp_ms: 1_050,
    };
    let create_policy_body = serde_json::to_string(&JsonRpcRequest {
        jsonrpc: "2.0".into(),
        method: "kombat_submitOwnerCall".into(),
        params: serde_json::to_value(create_policy_params)
            .expect("owner call params should serialize"),
        id: json!(1),
    })
    .expect("request serialization should succeed");
    let create_policy_response: JsonRpcResponse =
        serde_json::from_str(&server.handle_json_request(&create_policy_body))
            .expect("json-rpc response should deserialize");
    assert!(
        create_policy_response.error.is_none(),
        "unexpected create policy error: {:?}",
        create_policy_response.error
    );
    let create_policy_result = create_policy_response
        .result
        .clone()
        .expect("create policy response should have result");
    assert_eq!(create_policy_result["accepted"], true);
    assert_eq!(create_policy_result["action"], "create_policy");
    assert_eq!(create_policy_result["account_id"], 11);
    assert_eq!(create_policy_result["policy_id"], 42);

    let submit_body = serde_json::to_string(&JsonRpcRequest {
        jsonrpc: "2.0".into(),
        method: "kombat_submitIntent".into(),
        params: json!({
            "signed_intent": {
                "intent": {
                    "chain_id": 7,
                    "account": 11,
                    "policy_id": 42,
                    "nonce": 1,
                    "expires_at": 10_000,
                    "predicate": null,
                    "kind": "cancel",
                    "order_id": 7,
                },
                "signature_hex": encode_hex(&signed_intent(&grantee, 1, 10_000, IntentKind::Cancel { order_id: 7 }).signature),
            },
            "timestamp_ms": 1_100,
        }),
        id: json!(1),
    })
    .expect("request serialization should succeed");

    let submit_wire = server.handle_json_request(&submit_body);
    let submit_response: JsonRpcResponse =
        serde_json::from_str(&submit_wire).expect("json-rpc response should deserialize");
    assert!(
        submit_response.error.is_none(),
        "{:?}",
        submit_response.error
    );
    let submit_result = submit_response
        .result
        .clone()
        .expect("submit response should have result");
    assert_eq!(submit_result["pending_reason"], Value::Null);
    assert_eq!(submit_result["current_policy_nonce"], 1);

    let produce_block_body = serde_json::to_string(&JsonRpcRequest {
        jsonrpc: "2.0".into(),
        method: "kombat_produceBlock".into(),
        params: serde_json::to_value(ProduceBlockParams {
            timestamp_ms: 1_200,
            max_items: Some(10),
        })
        .expect("produce block params should serialize"),
        id: json!(2),
    })
    .expect("request serialization should succeed");
    let produce_block_wire = server.handle_json_request(&produce_block_body);
    let produce_block_response: JsonRpcResponse =
        serde_json::from_str(&produce_block_wire).expect("json-rpc response should deserialize");
    let produce_block_result = produce_block_response
        .result
        .expect("produce block should have result");
    assert!(
        produce_block_response.error.is_none(),
        "{:?}",
        produce_block_response.error
    );
    assert_eq!(produce_block_result["height"], 1);
    assert_eq!(produce_block_result["item_count"], 1);

    let events_body = serde_json::to_string(&JsonRpcRequest {
        jsonrpc: "2.0".into(),
        method: "kombat_listEvents".into(),
        params: json!({
            "from_seq": 0,
            "limit": 10,
            "filter": {
                "policy_id": 42,
                "intent_id_hex": null,
                "topic": "intent_executed",
            }
        }),
        id: json!(3),
    })
    .expect("request serialization should succeed");

    let events_wire = server.handle_json_request(&events_body);
    let events_response: JsonRpcResponse =
        serde_json::from_str(&events_wire).expect("json-rpc response should deserialize");
    let result = events_response
        .result
        .expect("events response should have result");
    assert_eq!(result["events"].as_array().map(Vec::len), Some(1));
    assert_eq!(result["events"][0]["kind"]["topic"], "intent_executed");
    assert_eq!(result["next_cursor"]["next_seq"], 4);

    let status_body = serde_json::to_string(&JsonRpcRequest {
        jsonrpc: "2.0".into(),
        method: "kombat_getIntentStatus".into(),
        params: json!({
            "intent_id_hex": submit_result["intent_id_hex"],
        }),
        id: json!(4),
    })
    .expect("request serialization should succeed");

    let status_wire = server.handle_json_request(&status_body);
    let status_response: JsonRpcResponse =
        serde_json::from_str(&status_wire).expect("json-rpc response should deserialize");
    let status_result = status_response
        .result
        .expect("status response should have result");
    assert_eq!(status_result["stage"], "executed");
    assert_eq!(status_result["policy_id"], 42);
    assert_eq!(status_result["nonce"], 1);
    assert_eq!(status_result["currently_queued"], false);
}

