#[test]
fn hides_manual_block_production_when_disabled() {
    let router = RpcRouter::new_with_config(JsonRpcServerConfig {
        manual_block_production_enabled: false,
        mahi_enabled: false,
        operator_bearer_token: None,
        peer_relay_bearer_token: None,
        network_bootstrap: None,
        peer_transport_enabled: false,
    });
    assert!(!router.methods().contains_key("kombat_produceBlock"));

    let server = JsonRpcHttpServer::new_with_config(
        Arc::new(Mutex::new(single_node_engine())),
        JsonRpcServerConfig {
            manual_block_production_enabled: false,
            mahi_enabled: false,
            operator_bearer_token: None,
            peer_relay_bearer_token: None,
            network_bootstrap: None,
            peer_transport_enabled: false,
        },
    );
    let body = serde_json::to_string(&JsonRpcRequest {
        jsonrpc: "2.0".into(),
        method: "kombat_produceBlock".into(),
        params: serde_json::to_value(ProduceBlockParams {
            timestamp_ms: 1_200,
            max_items: Some(10),
        })
        .expect("params should serialize"),
        id: json!(9),
    })
    .expect("request should serialize");
    let response: JsonRpcResponse =
        serde_json::from_str(&server.handle_json_request(&body)).expect("response should parse");

    assert_eq!(
        response.error,
        Some(super::JsonRpcErrorObject {
            code: -32601,
            message: "method not found".into(),
            data: None,
        })
    );
}

#[test]
fn requires_operator_bearer_token_for_manual_block_production() {
    let server = JsonRpcHttpServer::new_with_config(
        Arc::new(Mutex::new(single_node_engine())),
        JsonRpcServerConfig {
            manual_block_production_enabled: true,
            mahi_enabled: false,
            operator_bearer_token: Some("secret-token".into()),
            peer_relay_bearer_token: None,
            network_bootstrap: None,
            peer_transport_enabled: false,
        },
    );
    let body = serde_json::to_string(&JsonRpcRequest {
        jsonrpc: "2.0".into(),
        method: "kombat_produceBlock".into(),
        params: serde_json::to_value(ProduceBlockParams {
            timestamp_ms: 1_200,
            max_items: Some(10),
        })
        .expect("params should serialize"),
        id: json!(10),
    })
    .expect("request should serialize");

    let unauthorized: JsonRpcResponse =
        serde_json::from_str(&server.handle_json_request(&body)).expect("response should parse");
    assert_eq!(
        unauthorized.error,
        Some(super::JsonRpcErrorObject {
            code: -32010,
            message: "operator authorization required".into(),
            data: None,
        })
    );

    let authorized_request = format!(
        "POST / HTTP/1.1\r\nHost: localhost\r\nAuthorization: Bearer secret-token\r\nContent-Type: application/json\r\nContent-Length: {}\r\n\r\n{}",
        body.len(),
        body
    );
    let listener = TcpListener::bind("127.0.0.1:0").expect("listener should bind");
    let address = listener.local_addr().expect("listener addr should exist");
    let server_thread = std::thread::spawn(move || {
        let (mut stream, _) = listener.accept().expect("client should connect");
        server
            .handle_http_connection(&mut stream)
            .expect("http connection should succeed");
    });
    let mut client = TcpStream::connect(address).expect("client should connect");
    client
        .write_all(authorized_request.as_bytes())
        .expect("request should write");
    let mut raw_response = String::new();
    client
        .read_to_string(&mut raw_response)
        .expect("response should read");
    server_thread.join().expect("server thread should join");
    let authorized: JsonRpcResponse = serde_json::from_str(
        raw_response
            .split_once("\r\n\r\n")
            .expect("http response should contain headers")
            .1,
    )
    .expect("authorized response should parse");
    assert!(authorized.error.is_none(), "{:?}", authorized.error);
}

#[test]
fn requires_operator_bearer_token_for_snapshot_methods() {
    let snapshot_path = temp_snapshot_path("auth");
    let snapshot_path_json = snapshot_path.display().to_string();
    let server = JsonRpcHttpServer::new_with_config(
        Arc::new(Mutex::new(single_node_engine())),
        JsonRpcServerConfig {
            manual_block_production_enabled: false,
            mahi_enabled: false,
            operator_bearer_token: Some("secret-token".into()),
            peer_relay_bearer_token: None,
            network_bootstrap: None,
            peer_transport_enabled: false,
        },
    );
    let save_request = JsonRpcRequest {
        jsonrpc: "2.0".into(),
        method: "kombat_saveSnapshot".into(),
        params: serde_json::to_value(SnapshotFileParams {
            path: snapshot_path_json.clone(),
            force_reset: false,
        })
        .expect("params should serialize"),
        id: json!(10_001),
    };
    let unauthorized: JsonRpcResponse = serde_json::from_str(&server.handle_json_request(
        &serde_json::to_string(&save_request).expect("request should serialize"),
    ))
    .expect("response should parse");
    assert_eq!(
        unauthorized.error,
        Some(super::JsonRpcErrorObject {
            code: -32010,
            message: "operator authorization required".into(),
            data: None,
        })
    );
    let authorized = authorized_json_rpc_response(server, &save_request, "secret-token");
    assert!(authorized.error.is_none(), "{:?}", authorized.error);

    let load_server = JsonRpcHttpServer::new_with_config(
        Arc::new(Mutex::new(single_node_engine())),
        JsonRpcServerConfig {
            manual_block_production_enabled: false,
            mahi_enabled: false,
            operator_bearer_token: Some("secret-token".into()),
            peer_relay_bearer_token: None,
            network_bootstrap: None,
            peer_transport_enabled: false,
        },
    );
    let load_request = JsonRpcRequest {
        jsonrpc: "2.0".into(),
        method: "kombat_loadSnapshot".into(),
        params: serde_json::to_value(SnapshotFileParams {
            path: snapshot_path_json.clone(),
            force_reset: false,
        })
        .expect("params should serialize"),
        id: json!(10_002),
    };
    let unauthorized_load: JsonRpcResponse =
        serde_json::from_str(&load_server.handle_json_request(
            &serde_json::to_string(&load_request).expect("request should serialize"),
        ))
        .expect("response should parse");
    assert_eq!(
        unauthorized_load.error,
        Some(super::JsonRpcErrorObject {
            code: -32010,
            message: "operator authorization required".into(),
            data: None,
        })
    );

    let _ = std::fs::remove_file(snapshot_path);
}

#[test]
fn serves_network_bootstrap_metadata_when_configured() {
    let server = JsonRpcHttpServer::new_with_config(
        Arc::new(Mutex::new(single_node_engine())),
        JsonRpcServerConfig {
            manual_block_production_enabled: false,
            mahi_enabled: false,
            operator_bearer_token: Some("secret-token".into()),
            peer_relay_bearer_token: None,
            network_bootstrap: Some(network_bootstrap_config()),
            peer_transport_enabled: false,
        },
    );
    let raw = raw_http_response(
        server,
        "GET /network/bootstrap HTTP/1.1\r\nHost: localhost\r\n\r\n",
    );
    let raw = String::from_utf8(raw).expect("bootstrap response should be utf8");
    let (headers, body) = raw
        .split_once("\r\n\r\n")
        .expect("http response should contain headers");
    assert!(
        headers.starts_with("HTTP/1.1 200 OK"),
        "unexpected response headers: {headers}\n\nbody: {body}"
    );
    let payload: Value = serde_json::from_str(body).expect("bootstrap payload should parse");
    assert_eq!(payload["chain_id"], json!(7));
    assert_eq!(payload["validator_set_epoch"], json!(7));
    assert_eq!(
        payload["validator_id_hex"],
        json!(encode_hex(&validator(9)))
    );
    assert_eq!(
        payload["public_rpc_url"],
        json!("https://validator-9.testnet.0x26.xyz/api")
    );
    assert_eq!(
        payload["snapshot_path"],
        json!("https://validator-9.testnet.0x26.xyz/api/network/snapshot")
    );
    assert_eq!(payload["peers"].as_array().map(Vec::len), Some(1));
}

