#[test]
fn mahi_round_broadcast_converges_across_four_validators() {
    let servers = start_mahi_servers();
    for (_, server) in &servers {
        let result = server
            .maybe_run_mahi_round(1_100, 10)
            .expect("mahi round should not error");
        assert!(result.is_some(), "mahi round should produce a block");
    }

    let deadline = Instant::now() + Duration::from_secs(1);
    loop {
        let metrics = servers
            .iter()
            .map(|(_, server)| consensus_metrics(server))
            .collect::<Vec<_>>();
        let dag_snapshot_hashes = metrics
            .iter()
            .map(|metrics| metrics["mahi"]["dag_snapshot_hash_hex"].clone())
            .collect::<Vec<_>>();
        let block_counts = metrics
            .iter()
            .map(|metrics| metrics["mahi"]["block_count"].as_u64().unwrap_or(0))
            .collect::<Vec<_>>();
        let pending_fetch = metrics
            .iter()
            .map(|metrics| {
                metrics["mahi"]["pending_fetch_count"]
                    .as_u64()
                    .unwrap_or(u64::MAX)
            })
            .collect::<Vec<_>>();
        let all_hashes_equal = dag_snapshot_hashes
            .iter()
            .all(|hash| hash == &dag_snapshot_hashes[0]);
        let all_blocks_present = block_counts.iter().all(|count| *count == 4);
        let all_fetch_cleared = pending_fetch.iter().all(|count| *count == 0);
        if all_hashes_equal && all_blocks_present && all_fetch_cleared {
            for metrics in &metrics {
                assert_eq!(metrics["mahi"]["next_round"], json!(2));
            }
            break;
        }
        if Instant::now() >= deadline {
            panic!(
                "mahi did not converge within 1s: dag_snapshot_hashes={dag_snapshot_hashes:?} blocks={block_counts:?} pending_fetch={pending_fetch:?}"
            );
        }
        std::thread::sleep(Duration::from_millis(20));
    }
}

#[test]
fn mahi_full_restart_resumes_from_durable_head_round() {
    let servers = start_mahi_consensus_servers();
    drive_mahi_rounds_until_converged(&servers, 12);
    let heads_before_restart = wait_for_mahi_cluster_heads(&servers, 1);
    let cloned_engines = servers
        .iter()
        .map(|(byte, server)| {
            let engine = server.engine().lock().expect("engine lock should succeed");
            (*byte, engine.clone())
        })
        .collect::<BTreeMap<_, _>>();

    let restarted = start_mahi_servers_from_engines(cloned_engines);
    for (byte, server) in &restarted {
        let head_before = heads_before_restart
            .get(byte)
            .expect("pre-restart head should exist");
        let metrics = consensus_metrics(server);
        assert_eq!(
            metrics["mahi"]["restart_boundary_round"],
            json!(head_before.head_round.saturating_add(1)),
            "validator {byte} should seed Mahi from the durable head round"
        );
        assert_eq!(
            metrics["mahi"]["next_round"],
            json!(head_before.head_round.saturating_add(1)),
            "validator {byte} should not reset Mahi production to round 1"
        );
    }

    drive_mahi_rounds_until_converged(&restarted, 12);
    let min_height = heads_before_restart
        .values()
        .map(|head| head.head_height)
        .max()
        .unwrap_or(0)
        .saturating_add(1);
    let heads_after_restart = wait_for_mahi_cluster_heads(&restarted, min_height);
    for (byte, head_after) in heads_after_restart {
        let head_before = heads_before_restart
            .get(&byte)
            .expect("pre-restart head should exist");
        assert!(
            head_after.head_height > head_before.head_height,
            "validator {byte} should commit new Mahi blocks after restart"
        );
        assert!(
            head_after.head_round > head_before.head_round,
            "validator {byte} should keep chain rounds monotonic after restart"
        );
    }
}

#[test]
fn mahi_ancestor_quorum_stall_resets_from_durable_head() {
    let server = JsonRpcHttpServer::new_with_config(
        Arc::new(Mutex::new(single_node_engine())),
        JsonRpcServerConfig {
            manual_block_production_enabled: false,
            mahi_enabled: true,
            operator_bearer_token: Some("mahi-token".into()),
            peer_relay_bearer_token: None,
            network_bootstrap: Some(network_bootstrap_config()),
            peer_transport_enabled: false,
        },
    );
    let head = server.engine().head_snapshot();
    let expected_restart_boundary = super::mahi_restart_boundary_round_from_head(head.as_ref());
    {
        let mut state_guard = server.mahi_state.lock().expect("mahi lock should succeed");
        let state = state_guard.as_mut().expect("mahi state should exist");
        let stalled_round = expected_restart_boundary.saturating_add(1);
        state.restart_boundary_round = expected_restart_boundary;
        state.next_local_round = stalled_round;
        state.producer_ancestor_wait = Some(super::MahiAncestorWait {
            target_round: stalled_round,
            quorum: 2,
            available: 0,
            since: Instant::now()
                .checked_sub(
                    super::MAHI_ANCESTOR_QUORUM_SELF_HEAL_TIMEOUT
                        .saturating_add(Duration::from_millis(1)),
                )
                .expect("stale wait timestamp should fit"),
        });
    }

    let result = server
        .maybe_run_mahi_round(1_100, 10)
        .expect("mahi round gate should not error");
    assert!(result.is_none(), "self-heal should skip this producer tick");

    let metrics = consensus_metrics(&server);
    assert_eq!(
        metrics["mahi"]["restart_boundary_round"],
        json!(expected_restart_boundary)
    );
    assert_eq!(
        metrics["mahi"]["next_round"],
        json!(expected_restart_boundary)
    );
    assert_eq!(metrics["mahi"]["producer_ancestor_wait_round"], Value::Null);
}

