#[test]
fn mahi_fetch_recovers_missing_ancestors_after_inbound_drop() {
    let servers = start_mahi_servers_with_drop(&BTreeMap::from([(1_u8, 100_u8)]));
    let receiver = servers
        .iter()
        .find(|(byte, _)| *byte == 1)
        .map(|(_, server)| server.clone())
        .expect("receiver should exist");
    let authors = [2_u8, 3, 4]
        .into_iter()
        .map(|byte| {
            (
                byte,
                servers
                    .iter()
                    .find(|(candidate, _)| *candidate == byte)
                    .map(|(_, server)| server.clone())
                    .expect("author should exist"),
            )
        })
        .collect::<Vec<_>>();

    let mut ancestor_refs = Vec::new();
    for (byte, server) in &authors {
        let block = MahiBlock::signed(
            validator(*byte),
            1,
            7,
            1_100 + u64::from(*byte),
            Vec::new(),
            Vec::new(),
            [*byte; 32],
        );
        let reference = server
            .accept_mahi_block_into_state(block.clone(), true)
            .expect("author should accept its local block");
        server
            .enqueue_mahi_sigverify(reference, &block)
            .expect("empty author block should verify immediately");
        ancestor_refs.push(reference);
    }

    let dropped_block =
        MahiBlock::signed(validator(2), 1, 7, 1_100, Vec::new(), Vec::new(), [2; 32]);
    let body = serde_json::to_string(&NetworkMahiBlockRequest {
        block_hex: encode_borsh_hex(&dropped_block),
    })
    .expect("request body should serialize");
    let raw = raw_http_response(
        receiver.clone(),
        &format!(
            "POST /network/mahi/block HTTP/1.1\r\nHost: localhost\r\nAuthorization: Bearer mahi-token\r\nContent-Type: application/json\r\nContent-Length: {}\r\n\r\n{}",
            body.len(),
            body
        ),
    );
    let raw = String::from_utf8(raw).expect("authorized response should be utf8");
    assert!(raw.starts_with("HTTP/1.1 200 OK"), "{raw}");
    assert_eq!(
        consensus_metrics(&receiver)["mahi"]["dropped_blocks"],
        json!(1)
    );

    let descendant = MahiBlock::signed(
        validator(2),
        2,
        7,
        1_200,
        ancestor_refs,
        Vec::new(),
        [2; 32],
    );
    let descendant_ref = receiver
        .accept_mahi_block_into_state(descendant.clone(), false)
        .expect("receiver should accept descendant with missing ancestors");
    receiver
        .enqueue_mahi_sigverify(descendant_ref, &descendant)
        .expect("empty descendant should verify immediately");
    receiver.ensure_mahi_missing_fetch_worker();

    let deadline = Instant::now() + Duration::from_secs(1);
    loop {
        let metrics = consensus_metrics(&receiver);
        if metrics["mahi"]["pending_fetch_count"] == json!(0)
            && metrics["mahi"]["block_count"] == json!(4)
        {
            break;
        }
        if Instant::now() >= deadline {
            panic!("mahi fetch did not recover in time: {metrics}");
        }
        std::thread::sleep(Duration::from_millis(20));
    }
}

#[test]
fn mahi_commit_log_converges_across_four_validators_in_mahi_mode() {
    let servers = start_mahi_consensus_servers();
    let metrics = drive_mahi_rounds_until_converged(&servers, 11);
    let commit_hashes = metrics
        .iter()
        .map(|metrics| metrics["mahi"]["commit_log_hash_hex"].clone())
        .collect::<Vec<_>>();
    let decided_counts = metrics
        .iter()
        .map(|metrics| {
            metrics["mahi"]["decided_leader_count"]
                .as_u64()
                .unwrap_or(0)
        })
        .collect::<Vec<_>>();
    let committed_counts = metrics
        .iter()
        .map(|metrics| {
            metrics["mahi"]["committed_leader_count"]
                .as_u64()
                .unwrap_or(0)
        })
        .collect::<Vec<_>>();
    let commit_rules = metrics
        .iter()
        .map(|metrics| metrics["mahi"]["commit_rule"].as_str().unwrap_or_default())
        .collect::<Vec<_>>();

    assert!(commit_hashes.iter().all(|hash| hash == &commit_hashes[0]));
    assert!(decided_counts
        .iter()
        .all(|count| *count == decided_counts[0]));
    assert!(committed_counts
        .iter()
        .all(|count| *count == committed_counts[0]));
    assert!(
        decided_counts[0] > 0,
        "expected non-empty commit log: {metrics:?}"
    );
    assert!(
        committed_counts[0] > 0,
        "expected committed leaders: {metrics:?}"
    );
    assert!(commit_rules.iter().all(|rule| *rule == "mahi"));
}

