#[test]
fn timeout_message_endpoint_reuses_cached_local_timeout_after_round_advances() {
    let (engine, network_bootstrap) = timeout_ready_single_node_engine();
    let validator_verifiers = super::network_validator_verifiers(&network_bootstrap)
        .expect("validator set should validate");
    let mut remote_engine = validator_engine(8);
    let head = remote_engine.head().clone();
    let remote_signature = remote_engine
        .sign_current_head_qc(block_hash(&head), head.header.round)
        .expect("remote qc signature should exist");
    let signing_bytes = quorum_certificate_signing_bytes(&QuorumCertificate {
        view: head.header.round,
        block_hash: block_hash(&head),
        signatures: vec![],
    })
    .expect("qc signing bytes should exist");
    let local_signature = Signature {
        validator: validator(9),
        bytes: consensus_signature_bytes(9, &signing_bytes),
    };
    let head_qc = assemble_quorum_certificate(
        &head,
        vec![local_signature, remote_signature],
        &validator_verifiers,
    )
    .expect("head qc should assemble");
    remote_engine
        .install_head_qc(head_qc, &validator_verifiers)
        .expect("remote engine should accept quorum qc");
    let remote_timeout = remote_engine
        .sign_timeout_message(&validator_verifiers)
        .expect("remote timeout should sign");
    let server = JsonRpcHttpServer::new_with_config(
        Arc::new(Mutex::new(engine)),
        JsonRpcServerConfig {
            manual_block_production_enabled: false,
            mahi_enabled: false,
            operator_bearer_token: Some("secret-token".into()),
            peer_relay_bearer_token: None,
            network_bootstrap: Some(network_bootstrap),
            peer_transport_enabled: false,
        },
    );
    let request_body = serde_json::to_string(&NetworkTimeoutRequest {
        head_hash_hex: None,
        head_height: None,
        round: remote_timeout.round,
        timeout_hex: Some(encode_borsh_hex(&remote_timeout)),
    })
    .expect("request should serialize");

    let first_raw = raw_http_response(
        server.clone(),
        &format!(
            "POST /network/timeout-message HTTP/1.1\r\nHost: localhost\r\nAuthorization: Bearer secret-token\r\nContent-Type: application/json\r\nContent-Length: {}\r\n\r\n{}",
            request_body.len(),
            request_body
        ),
    );
    let first_raw = String::from_utf8(first_raw).expect("response should be utf8");
    let (_, first_body) = first_raw
        .split_once("\r\n\r\n")
        .expect("response should contain headers");
    let first_payload: NetworkTimeoutResponse =
        serde_json::from_str(first_body).expect("timeout payload should parse");
    assert_eq!(first_payload.message_count, 2);
    let local_timeout = decode_borsh_hex::<TimeoutMessage>(
        first_payload
            .timeout_hex
            .as_deref()
            .expect("local timeout should be present"),
    )
    .expect("local timeout should decode");

    server
        .engine()
        .lock()
        .expect("engine lock should succeed")
        .install_timeout_messages(
            &[remote_timeout.clone(), local_timeout.clone()],
            &validator_verifiers,
            1_200,
        )
        .expect("timeout certificate should install");

    let second_raw = raw_http_response(
        server,
        &format!(
            "POST /network/timeout-message HTTP/1.1\r\nHost: localhost\r\nAuthorization: Bearer secret-token\r\nContent-Type: application/json\r\nContent-Length: {}\r\n\r\n{}",
            request_body.len(),
            request_body
        ),
    );
    let second_raw = String::from_utf8(second_raw).expect("response should be utf8");
    let (_, second_body) = second_raw
        .split_once("\r\n\r\n")
        .expect("response should contain headers");
    let second_payload: NetworkTimeoutResponse =
        serde_json::from_str(second_body).expect("timeout payload should parse");
    assert_eq!(
        second_payload.validator_id_hex,
        Some(encode_hex(&validator(9)))
    );
    let expected_local_timeout_hex = encode_borsh_hex(&local_timeout);
    assert_eq!(
        second_payload.timeout_hex.as_deref(),
        Some(expected_local_timeout_hex.as_str())
    );
    assert_eq!(second_payload.message_count, 2);
}

