#[test]
fn peer_transport_reports_connect_failures_as_unreachable() {
    let engine = single_node_engine();
    let request = NetworkTimeoutRequest {
        head_hash_hex: Some(encode_hex(&block_hash(engine.head()))),
        head_height: Some(engine.head().header.height),
        round: engine.current_round(),
        timeout_hex: None,
    };
    let server = JsonRpcHttpServer::new_with_config(
        Arc::new(Mutex::new(engine)),
        JsonRpcServerConfig {
            manual_block_production_enabled: false,
            mahi_enabled: false,
            operator_bearer_token: Some("secret-token".into()),
            peer_relay_bearer_token: None,
            network_bootstrap: None,
            peer_transport_enabled: true,
        },
    );
    let listener = TcpListener::bind("127.0.0.1:0").expect("listener should bind");
    let endpoint = format!(
        "http://{}",
        listener.local_addr().expect("listener addr should exist")
    );
    drop(listener);

    let error = server
        .send_network_json_request::<_, NetworkTimeoutResponse>(
            std::slice::from_ref(&endpoint),
            "timeout-message",
            &request,
        )
        .expect_err("dead peer should not succeed");

    assert!(
        matches!(error, NetworkRequestError::Unreachable(message) if message.contains("connect"))
    );

    let backoff_error = server
        .send_network_json_request::<_, NetworkTimeoutResponse>(
            std::slice::from_ref(&endpoint),
            "timeout-message",
            &request,
        )
        .expect_err("backoff should reject immediate retry");
    assert!(
        matches!(backoff_error, NetworkRequestError::Unreachable(message) if message.contains("backoff active"))
    );

    let metrics_body = serde_json::to_string(&JsonRpcRequest {
        jsonrpc: "2.0".into(),
        method: "kombat_getConsensusMetrics".into(),
        params: json!({}),
        id: json!(7_007),
    })
    .expect("request should serialize");
    let metrics_response: JsonRpcResponse =
        serde_json::from_str(&server.handle_json_request(&metrics_body))
            .expect("response should parse");
    let metrics = metrics_response
        .result
        .expect("metrics response should contain result");
    let backoff = metrics["peer_transport_endpoint_backoff"]
        .as_array()
        .expect("peer transport backoff should be an array");
    assert_eq!(backoff.len(), 1);
    assert_eq!(backoff[0]["endpoint"], endpoint);
    assert_eq!(backoff[0]["consecutive_failures"], 1);
    assert!(
        backoff[0]["retry_in_ms"]
            .as_u64()
            .expect("retry should be numeric")
            > 0
    );
    assert!(
        backoff[0]["last_error"]
            .as_str()
            .expect("last error should be text")
            .contains("connect"),
        "unexpected backoff error payload: {:?}",
        backoff[0]
    );
}

