#[test]
fn json_rpc_submit_intent_forwards_to_mahi_next_leader() {
    let initial_endpoints = [1_u8, 2, 3, 4]
        .into_iter()
        .map(|byte| (byte, reserve_local_endpoint()))
        .collect::<Vec<_>>();
    let initial_bootstrap = mahi_network_bootstrap_configs(&initial_endpoints)
        .remove(&1)
        .expect("bootstrap config should exist");
    let legacy_leader = select_leader_for_validator_set(1, 7, &initial_bootstrap.validator_set)
        .expect("legacy leader selection should succeed");
    let mahi_leader = super::LeaderSchedule::new(
        initial_bootstrap
            .validator_set
            .active_validators()
            .into_iter()
            .map(|validator| validator.validator_id)
            .collect(),
    )
    .leader_for_round(1);
    assert_ne!(
        legacy_leader, mahi_leader,
        "fixture must exercise a leader mismatch between legacy and mahi routing"
    );
    assert_ne!(
        mahi_leader,
        validator(1),
        "fixture must keep validator-1 in follower role so forwarding is required"
    );

    let response = JsonRpcResponse {
        jsonrpc: "2.0".into(),
        result: Some(json!({
            "intent_id_hex": "0xfacefeed",
            "policy_id": 42,
            "nonce": 1,
            "accepted_direct": true,
            "accepted_conditional": false,
            "queue_position": Value::Null,
            "pending_reason": Value::Null,
        })),
        error: None,
        id: json!(79),
    };
    let (mahi_leader_endpoint, join) = spawn_mock_json_rpc_server_with_request(response);
    let routed_endpoints = [1_u8, 2, 3, 4]
        .into_iter()
        .map(|byte| {
            let endpoint = if validator(byte) == mahi_leader {
                mahi_leader_endpoint.clone()
            } else {
                "http://127.0.0.1:1".to_owned()
            };
            (byte, endpoint)
        })
        .collect::<Vec<_>>();
    let network_bootstrap = mahi_network_bootstrap_configs(&routed_endpoints)
        .remove(&1)
        .expect("bootstrap config should exist");
    let engine = SingleNodeEngine::new_with_validator_set(
        SingleNodeConfig {
            chain_id: 7,
            validator_id: validator(1),
            consensus_signing_key: [1; 32],
            genesis_timestamp_ms: 1_000,
            genesis_state_root: [3; 32],
            pacemaker: kombat_chain_consensus::PacemakerConfig {
                base_timeout_ms: 300,
                max_timeout_ms: 20_000,
                max_exponent: 6,
                max_clock_skew_ms: 1_000,
            },
        },
        Some(&network_bootstrap.validator_set),
    );
    let server = JsonRpcHttpServer::new_with_config(
        Arc::new(Mutex::new(engine)),
        JsonRpcServerConfig {
            manual_block_production_enabled: false,
            mahi_enabled: true,
            operator_bearer_token: None,
            peer_relay_bearer_token: None,
            network_bootstrap: Some(network_bootstrap),
            peer_transport_enabled: false,
        },
    );
    let signer = signing_key(8);
    let signed = signed_intent(&signer, 1, 10_000, IntentKind::Cancel { order_id: 7 });
    let body = serde_json::to_string(&JsonRpcRequest {
        jsonrpc: "2.0".into(),
        method: "kombat_submitIntent".into(),
        params: serde_json::to_value(SubmitIntentParams {
            signed_intent: SignedIntentJson {
                intent: IntentJson {
                    chain_id: signed.intent.chain_id,
                    account: signed.intent.account,
                    policy_id: signed.intent.policy_id,
                    nonce: signed.intent.nonce,
                    expires_at: signed.intent.expires_at,
                    predicate: None,
                    kind: IntentKindJson::Cancel { order_id: 7 },
                },
                signature_hex: encode_hex(&signed.signature),
            },
            timestamp_ms: 1_100,
        })
        .expect("params should serialize"),
        id: json!(79),
    })
    .expect("request should serialize");

    let forwarded: JsonRpcResponse =
        with_env_vars(&[(MAHI_OBSERVER_ASYNC_RELAY_ENV, Some("0".into()))], || {
            serde_json::from_str(&server.handle_json_request(&body)).expect("response should parse")
        });

    assert!(forwarded.error.is_none(), "{:?}", forwarded.error);
    assert_eq!(
        forwarded.result.expect("result should exist")["intent_id_hex"],
        "0xfacefeed"
    );

    let raw_request = join.join().expect("server thread should join");
    assert_eq!(
        raw_request
            .headers
            .get(NETWORK_RELAY_HEADER)
            .map(String::as_str),
        Some(NETWORK_SUBMIT_INTENT_FORWARD)
    );
    assert!(raw_request
        .body
        .contains("\"method\":\"kombat_submitIntent\""));
}

