#[test]
fn json_rpc_submit_intent_batch_splits_by_mahi_payload_owner_from_observer_ingress() {
    let validator_nine_response = JsonRpcResponse {
        jsonrpc: "2.0".into(),
        result: Some(json!({
            "results": [{
                "accepted": true,
                "intent_id_hex": "0xbbb001",
                "response": { "intent_id_hex": "0xbbb001" },
                "error": Value::Null
            }]
        })),
        error: None,
        id: json!(180),
    };
    let validator_eight_response = JsonRpcResponse {
        jsonrpc: "2.0".into(),
        result: Some(json!({
            "results": [
                {
                    "accepted": true,
                    "intent_id_hex": "0xaaa000",
                    "response": { "intent_id_hex": "0xaaa000" },
                    "error": Value::Null
                },
                {
                    "accepted": true,
                    "intent_id_hex": "0xaaa002",
                    "response": { "intent_id_hex": "0xaaa002" },
                    "error": Value::Null
                }
            ]
        })),
        error: None,
        id: json!(180),
    };
    let (validator_nine_endpoint, validator_nine_join) =
        spawn_mock_json_rpc_server_with_request(validator_nine_response);
    let (validator_eight_endpoint, validator_eight_join) =
        spawn_mock_json_rpc_server_with_request(validator_eight_response);
    let (engine, network_bootstrap) = observer_network_fixture_with_validator_endpoints(
        &[&validator_nine_endpoint],
        &[&validator_eight_endpoint],
    );
    let server = with_env_vars(&[("KOMBAT_CONSENSUS", Some("mahi".into()))], || {
        JsonRpcHttpServer::new_with_config(
            Arc::new(Mutex::new(engine)),
            JsonRpcServerConfig {
                manual_block_production_enabled: false,
                mahi_enabled: true,
                operator_bearer_token: None,
                peer_relay_bearer_token: None,
                network_bootstrap: Some(network_bootstrap),
                peer_transport_enabled: false,
            },
        )
    });
    let signer = signing_key(8);
    let make_item = |policy_id: u64, nonce: u64, order_id: u64| {
        let mut signed = signed_intent(&signer, nonce, 10_000, IntentKind::Cancel { order_id });
        signed.intent.policy_id = policy_id;
        SubmitIntentParams {
            signed_intent: SignedIntentJson {
                intent: IntentJson {
                    chain_id: signed.intent.chain_id,
                    account: signed.intent.account,
                    policy_id: signed.intent.policy_id,
                    nonce: signed.intent.nonce,
                    expires_at: signed.intent.expires_at,
                    predicate: None,
                    kind: IntentKindJson::Cancel { order_id },
                },
                signature_hex: encode_hex(&signed.signature),
            },
            timestamp_ms: 1_100 + nonce,
        }
    };
    let body = serde_json::to_string(&JsonRpcRequest {
        jsonrpc: "2.0".into(),
        method: "kombat_submitIntentBatch".into(),
        params: serde_json::to_value(SubmitIntentBatchParams {
            items: vec![
                make_item(42, 1, 7),
                make_item(43, 2, 8),
                make_item(42, 3, 9),
            ],
        })
        .expect("params should serialize"),
        id: json!(180),
    })
    .expect("request should serialize");

    let forwarded: JsonRpcResponse =
        with_env_vars(&[(MAHI_OBSERVER_ASYNC_RELAY_ENV, Some("0".into()))], || {
            serde_json::from_str(&server.handle_json_request(&body)).expect("response should parse")
        });

    assert!(forwarded.error.is_none(), "{:?}", forwarded.error);
    let result = forwarded.result.expect("result should exist");
    assert_eq!(result["results"][0]["intent_id_hex"], "0xaaa000");
    assert_eq!(result["results"][1]["intent_id_hex"], "0xbbb001");
    assert_eq!(result["results"][2]["intent_id_hex"], "0xaaa002");

    let validator_nine_request = validator_nine_join
        .join()
        .expect("validator nine server should join");
    let validator_eight_request = validator_eight_join
        .join()
        .expect("validator eight server should join");
    assert_eq!(
        validator_nine_request
            .headers
            .get(NETWORK_RELAY_HEADER)
            .map(String::as_str),
        Some(NETWORK_SUBMIT_INTENT_FORWARD)
    );
    assert_eq!(
        validator_eight_request
            .headers
            .get(NETWORK_RELAY_HEADER)
            .map(String::as_str),
        Some(NETWORK_SUBMIT_INTENT_FORWARD)
    );

    let validator_nine_rpc: JsonRpcRequest = serde_json::from_str(&validator_nine_request.body)
        .expect("validator nine request should parse");
    let validator_eight_rpc: JsonRpcRequest = serde_json::from_str(&validator_eight_request.body)
        .expect("validator eight request should parse");
    let validator_nine_params =
        serde_json::from_value::<SubmitIntentBatchParams>(validator_nine_rpc.params)
            .expect("validator nine params should parse");
    let validator_eight_params =
        serde_json::from_value::<SubmitIntentBatchParams>(validator_eight_rpc.params)
            .expect("validator eight params should parse");

    assert_eq!(validator_nine_params.items.len(), 1);
    assert!(validator_nine_params
        .items
        .iter()
        .all(|item| item.signed_intent.intent.policy_id == 43));
    assert_eq!(validator_eight_params.items.len(), 2);
    assert!(validator_eight_params
        .items
        .iter()
        .all(|item| item.signed_intent.intent.policy_id == 42));
}

