#[test]
fn mahi_owner_relay_queue_batches_by_validator_without_global_scan() {
    fn cancel_intent_json(signed: &SignedIntent) -> SignedIntentJson {
        let IntentKind::Cancel { order_id } = signed.intent.kind else {
            unreachable!("test helper only builds cancel intents")
        };
        SignedIntentJson {
            intent: IntentJson {
                chain_id: signed.intent.chain_id,
                account: signed.intent.account,
                policy_id: signed.intent.policy_id,
                nonce: signed.intent.nonce,
                expires_at: signed.intent.expires_at,
                predicate: None,
                kind: IntentKindJson::Cancel { order_id },
            },
            signature_hex: encode_hex(&signed.signature),
        }
    }

    let signer = signing_key(8);
    let signed_one = signed_intent(&signer, 1, 10_000, IntentKind::Cancel { order_id: 7 });
    let signed_two = signed_intent(&signer, 2, 10_000, IntentKind::Cancel { order_id: 8 });
    let mut queue = super::PendingMahiOwnerRelayQueues::default();
    let validator_one = validator(1);
    let validator_two = validator(2);
    queue.insert(
        validator_one,
        intent_id(&signed_one),
        SubmitIntentParams {
            signed_intent: cancel_intent_json(&signed_one),
            timestamp_ms: 1_100,
        },
    );
    queue.insert(
        validator_two,
        intent_id(&signed_two),
        SubmitIntentParams {
            signed_intent: cancel_intent_json(&signed_two),
            timestamp_ms: 1_100,
        },
    );

    assert_eq!(queue.pending_intents(), 2);
    assert_eq!(queue.pending_targets(), 2);

    let batches = queue.take_batches(1);
    assert!(queue.is_empty());
    assert_eq!(batches.get(&validator_one).map(Vec::len), Some(1));
    assert_eq!(batches.get(&validator_two).map(Vec::len), Some(1));

    queue.requeue_front(
        validator_one,
        batches.get(&validator_one).cloned().unwrap_or_default(),
    );
    assert_eq!(queue.pending_intents(), 1);
    assert_eq!(queue.pending_targets(), 1);
}

#[test]
fn mahi_payload_owner_redundancy_selects_backup_validators() {
    let (_engine, network_bootstrap) = observer_network_fixture_with_validator_endpoints(
        &["http://127.0.0.1:1"],
        &["http://127.0.0.1:2"],
    );
    let active_validators = network_bootstrap.validator_set.active_validators();

    with_env_vars(&[(MAHI_OWNER_RELAY_REDUNDANCY_ENV, None)], || {
        assert_eq!(
            mahi_payload_owner_ids_for_policy(&active_validators, 42),
            vec![validator(8)]
        );
    });
    with_env_vars(
        &[(MAHI_OWNER_RELAY_REDUNDANCY_ENV, Some("2".into()))],
        || {
            assert_eq!(
                mahi_payload_owner_ids_for_policy(&active_validators, 42),
                vec![validator(8), validator(9)]
            );
        },
    );
    with_env_vars(
        &[(MAHI_OWNER_RELAY_REDUNDANCY_ENV, Some("99".into()))],
        || {
            assert_eq!(
                mahi_payload_owner_ids_for_policy(&active_validators, 43),
                vec![validator(9), validator(8)]
            );
        },
    );
    with_env_vars(
        &[(MAHI_OWNER_RELAY_REDUNDANCY_ENV, Some("2".into()))],
        || {
            assert_eq!(
                mahi_payload_next_owner_id_for_policy(&active_validators, 42, validator(8)),
                Some(validator(9))
            );
            assert_eq!(
                mahi_payload_next_owner_id_for_policy(&active_validators, 42, validator(9)),
                None
            );
        },
    );
}

