#[test]
fn mahi_owner_relay_redundancy_enqueues_primary_only() {
    let (engine, network_bootstrap) = observer_network_fixture_with_validator_endpoints(
        &["http://127.0.0.1:1"],
        &["http://127.0.0.1:2"],
    );
    let active_validators = network_bootstrap.validator_set.active_validators();
    let server = with_env_vars(&[("KOMBAT_CONSENSUS", Some("mahi".into()))], || {
        JsonRpcHttpServer::new_with_config(
            Arc::new(Mutex::new(engine)),
            JsonRpcServerConfig {
                manual_block_production_enabled: false,
                mahi_enabled: true,
                operator_bearer_token: None,
                peer_relay_bearer_token: None,
                network_bootstrap: Some(network_bootstrap),
                peer_transport_enabled: false,
            },
        )
    });
    let signer = signing_key(8);
    let mut signed = signed_intent(&signer, 1, 10_000, IntentKind::Cancel { order_id: 7 });
    signed.intent.policy_id = 42;
    let params = SubmitIntentParams {
        signed_intent: SignedIntentJson {
            intent: IntentJson {
                chain_id: signed.intent.chain_id,
                account: signed.intent.account,
                policy_id: signed.intent.policy_id,
                nonce: signed.intent.nonce,
                expires_at: signed.intent.expires_at,
                predicate: None,
                kind: IntentKindJson::Cancel { order_id: 7 },
            },
            signature_hex: encode_hex(&signed.signature),
        },
        timestamp_ms: 1_100,
    };

    with_env_vars(
        &[(MAHI_OWNER_RELAY_REDUNDANCY_ENV, Some("2".into()))],
        || {
            server
                .enqueue_mahi_observer_owner_relay_batch(
                    &active_validators,
                    SubmitIntentBatchParams {
                        items: vec![params],
                    },
                )
                .expect("enqueue should succeed");
        },
    );

    let deadline = Instant::now() + Duration::from_secs(1);
    loop {
        let queue = server
            .pending_mahi_owner_relays
            .lock()
            .expect("queue lock should work");
        let primary_queue_len = queue.by_validator.get(&validator(8)).map(|q| q.len());
        let backup_queue_len = queue.by_validator.get(&validator(9)).map(|q| q.len());
        if queue.pending_intents() == 1
            && primary_queue_len == Some(1)
            && backup_queue_len.is_none()
        {
            break;
        }
        if Instant::now() >= deadline {
            panic!(
                "owner relay queue did not converge: pending={} primary={primary_queue_len:?} backup={backup_queue_len:?}",
                queue.pending_intents()
            );
        }
        drop(queue);
        std::thread::sleep(Duration::from_millis(20));
    }
}

#[test]
fn mahi_local_submit_requeues_to_primary_owner_after_admit() {
    let signer = signing_key(8);
    let intent = Intent {
        chain_id: 7,
        account: 11,
        policy_id: 42,
        nonce: 1,
        expires_at: 10_000,
        predicate: None,
        kind: IntentKind::Cancel { order_id: 7 },
    };
    let session_payload = SessionPayload {
        intent_hash: intent_signing_hash(&intent),
        policy_id: 42,
        chain_id: 7,
    };
    let signed = SignedIntent {
        intent,
        signature: signer
            .sign(&borsh::to_vec(&session_payload).expect("session payload should serialize"))
            .to_bytes(),
    };
    let (mut engine, network_bootstrap) =
        follower_network_fixture_with_leader_endpoints(&["http://127.0.0.1:1"]);
    let policy = PolicyRecord::new(
        42,
        11,
        signer.verifying_key().to_bytes(),
        1_000,
        172_800_000,
        PolicyState::Active,
        sample_policy().terms.clone(),
    );
    engine
        .policy_store_mut()
        .insert(policy)
        .expect("policy should insert");
    let server = with_env_vars(&[("KOMBAT_CONSENSUS", Some("mahi".into()))], || {
        JsonRpcHttpServer::new_with_config(
            Arc::new(Mutex::new(engine)),
            JsonRpcServerConfig {
                manual_block_production_enabled: false,
                mahi_enabled: true,
                operator_bearer_token: None,
                peer_relay_bearer_token: None,
                network_bootstrap: Some(network_bootstrap),
                peer_transport_enabled: false,
            },
        )
    });
    let params = SubmitIntentParams {
        signed_intent: SignedIntentJson {
            intent: IntentJson {
                chain_id: signed.intent.chain_id,
                account: signed.intent.account,
                policy_id: signed.intent.policy_id,
                nonce: signed.intent.nonce,
                expires_at: signed.intent.expires_at,
                predicate: None,
                kind: IntentKindJson::Cancel { order_id: 7 },
            },
            signature_hex: encode_hex(&signed.signature),
        },
        timestamp_ms: 1_100,
    };

    let queued = server
        .queue_post_admit_submit_relay(validator(9), params)
        .expect("owner relay enqueue should succeed");
    assert!(queued, "mahi submit should queue a primary owner relay");
    let queue = server
        .pending_mahi_owner_relays
        .lock()
        .expect("queue lock should work");
    assert_eq!(queue.pending_intents(), 1);
    assert_eq!(
        queue.by_validator.get(&validator(8)).map(|q| q.len()),
        Some(1)
    );
}

#[test]
fn mahi_owner_relay_lag_detection_requires_backup_enabled() {
    let (engine, network_bootstrap) = observer_network_fixture_with_validator_endpoints(
        &["http://127.0.0.1:1"],
        &["http://127.0.0.1:2"],
    );
    let mut network_bootstrap = network_bootstrap;
    let bootstrap_peers = bootstrap_validator(&network_bootstrap.validator_set, validator(8))
        .expect("validator eight bootstrap should work");
    network_bootstrap.local_validator = Some(bootstrap_peers.local.clone());
    network_bootstrap.bootstrap_peers.local = bootstrap_peers.local;

    let server = with_env_vars(&[("KOMBAT_CONSENSUS", Some("mahi".into()))], || {
        JsonRpcHttpServer::new_with_config(
            Arc::new(Mutex::new(engine)),
            JsonRpcServerConfig {
                manual_block_production_enabled: false,
                mahi_enabled: true,
                operator_bearer_token: None,
                peer_relay_bearer_token: None,
                network_bootstrap: Some(network_bootstrap),
                peer_transport_enabled: false,
            },
        )
    });
    {
        let mut state_guard = server.mahi_state.lock().expect("mahi state lock works");
        let state = state_guard.as_mut().expect("mahi state should exist");
        state.last_produced = Some(MahiBlockRef {
            round: 10,
            author: validator(8),
            hash: [8; 32],
        });
        state.dag.by_round.insert(300, BTreeMap::new());
    }

    with_env_vars(
        &[
            (MAHI_OWNER_RELAY_REDUNDANCY_ENV, None),
            (MAHI_OWNER_RELAY_LAG_ROUNDS_ENV, Some("16".into())),
        ],
        || {
            assert!(!server.local_mahi_owner_fallback_enabled());
            assert!(server.local_mahi_payload_owner_lagging());
        },
    );
    with_env_vars(
        &[
            (MAHI_OWNER_RELAY_REDUNDANCY_ENV, Some("2".into())),
            (MAHI_OWNER_RELAY_LAG_ROUNDS_ENV, Some("16".into())),
        ],
        || {
            assert!(server.local_mahi_owner_fallback_enabled());
            assert!(server.local_mahi_payload_owner_lagging());
        },
    );
}

