#[test]
fn mahi_state_clears_inflight_delegations_on_execute() {
    let (_engine, network_bootstrap) = single_validator_network_fixture();
    let mut state = super::build_mahi_state(
        true,
        Some(&network_bootstrap),
        kombat_chain_consensus::mahi::CommitRule::Mahi,
        1,
    )
    .expect("mahi state should build");
    let action_id = [7; 32];
    let block = MahiBlock::signed_with_delegations(
        validator(9),
        1,
        network_bootstrap.validator_set.epoch,
        1_200,
        Vec::new(),
        Vec::new(),
        vec![kombat_chain_consensus::BlockDelegation {
            action_id,
            timestamp_ms: 1_100,
            action: BlockDelegationAction::Close {
                delegation_id: [8; 32],
            },
        }],
        [9; 32],
    );

    let block_ref = state
        .accept_block(block, true)
        .expect("local block should accept");
    assert!(
        state.inflight_delegation_actions.contains(&action_id),
        "locally produced delegation should stay inflight before execution"
    );

    state.mark_block_executed(block_ref);

    assert!(
        !state.inflight_delegation_actions.contains(&action_id),
        "executed block should clear its delegation action from inflight"
    );
}

#[test]
fn mahi_state_clears_inflight_governance_actions_on_execute() {
    let (_engine, network_bootstrap) = single_validator_network_fixture();
    let mut state = super::build_mahi_state(
        true,
        Some(&network_bootstrap),
        kombat_chain_consensus::mahi::CommitRule::Mahi,
        1,
    )
    .expect("mahi state should build");
    let tee_action_id = [5; 32];
    let real_capital_action_id = [6; 32];
    let block = MahiBlock::signed_with_all_payloads(
        validator(9),
        1,
        network_bootstrap.validator_set.epoch,
        1_200,
        Vec::new(),
        Vec::new(),
        Vec::new(),
        Vec::new(),
        Vec::new(),
        Vec::new(),
        vec![kombat_chain_consensus::BlockTeeGovernance {
            action_id: tee_action_id,
            timestamp_ms: 1_100,
            action: BlockTeeGovernanceAction::UpdateVendorCapProfile {
                vendor: BlockTeeVendor::IntelSgxDcap,
                cap_multiplier_microunits: 1,
                composition_eligibility: true,
                valid_from_block: 10,
            },
        }],
        vec![kombat_chain_consensus::BlockRealCapitalGovernance {
            action_id: real_capital_action_id,
            timestamp_ms: 1_100,
            action: BlockRealCapitalGovernanceAction::UpdateGlobalKillSwitch { disabled: true },
        }],
        [9; 32],
    );

    let block_ref = state
        .accept_block(block, true)
        .expect("local block should accept");
    assert!(
        state
            .inflight_tee_governance_actions
            .contains(&tee_action_id),
        "locally produced tee governance should stay inflight before execution"
    );
    assert!(
        state
            .inflight_real_capital_governance_actions
            .contains(&real_capital_action_id),
        "locally produced real-capital governance should stay inflight before execution"
    );

    state.mark_block_executed(block_ref);

    assert!(
        !state
            .inflight_tee_governance_actions
            .contains(&tee_action_id),
        "executed block should clear tee governance from inflight"
    );
    assert!(
        !state
            .inflight_real_capital_governance_actions
            .contains(&real_capital_action_id),
        "executed block should clear real-capital governance from inflight"
    );
}

