#[test]
fn mahi_pre_admitted_pool_drains_round_robin_across_policies() {
    fn pre_admitted_intent(policy_id: u64, nonce: u64) -> SignedIntent {
        let signer = signing_key(policy_id as u8);
        let intent = Intent {
            chain_id: 7,
            account: policy_id + 1_000,
            policy_id,
            nonce,
            expires_at: 10_000,
            predicate: None,
            kind: IntentKind::Cancel {
                order_id: policy_id * 100 + nonce,
            },
        };
        let session_payload = SessionPayload {
            intent_hash: intent_signing_hash(&intent),
            policy_id,
            chain_id: 7,
        };
        let signature = signer
            .sign(&borsh::to_vec(&session_payload).expect("session payload should serialize"))
            .to_bytes();
        SignedIntent { intent, signature }
    }

    let mut pool = MahiPreAdmittedPool::default();
    for nonce in 1..=3 {
        assert!(matches!(
            pool.insert(pre_admitted_intent(40, nonce)),
            MahiPreAdmittedInsertResult::Accepted
        ));
        assert!(matches!(
            pool.insert(pre_admitted_intent(44, nonce)),
            MahiPreAdmittedInsertResult::Accepted
        ));
    }

    let policy_next_nonces = BTreeMap::from([(40, 1), (44, 1)]);
    let first = pool.drain_for_block(
        1_100,
        4,
        &policy_next_nonces,
        &BTreeMap::new(),
        &BTreeSet::new(),
    );
    assert_eq!(
        first
            .iter()
            .map(|intent| (intent.intent.policy_id, intent.intent.nonce))
            .collect::<Vec<_>>(),
        vec![(40, 1), (44, 1), (40, 2), (44, 2)]
    );

    let policy_next_nonces = BTreeMap::from([(40, 3), (44, 3)]);
    let second = pool.drain_for_block(
        1_100,
        4,
        &policy_next_nonces,
        &BTreeMap::new(),
        &BTreeSet::new(),
    );
    assert_eq!(
        second
            .iter()
            .map(|intent| (intent.intent.policy_id, intent.intent.nonce))
            .collect::<Vec<_>>(),
        vec![(40, 3), (44, 3)]
    );
    assert_eq!(pool.stats().items, 0);
    assert_eq!(pool.stats().drained_total, 6);
}

#[test]
fn mahi_pre_admitted_pool_full_returns_retry_without_nonce_hole() {
    fn pre_admitted_intent(policy_id: u64, nonce: u64) -> SignedIntent {
        let signer = signing_key(policy_id as u8);
        let intent = Intent {
            chain_id: 7,
            account: policy_id + 1_000,
            policy_id,
            nonce,
            expires_at: 10_000,
            predicate: None,
            kind: IntentKind::Cancel {
                order_id: policy_id * 100 + nonce,
            },
        };
        let session_payload = SessionPayload {
            intent_hash: intent_signing_hash(&intent),
            policy_id,
            chain_id: 7,
        };
        let signature = signer
            .sign(&borsh::to_vec(&session_payload).expect("session payload should serialize"))
            .to_bytes();
        SignedIntent { intent, signature }
    }

    let mut pool = MahiPreAdmittedPool::default();
    assert!(matches!(
        pool.insert_with_limit(pre_admitted_intent(40, 1), 2),
        MahiPreAdmittedInsertResult::Accepted
    ));
    assert!(matches!(
        pool.insert_with_limit(pre_admitted_intent(40, 2), 2),
        MahiPreAdmittedInsertResult::Accepted
    ));
    assert!(matches!(
        pool.insert_with_limit(pre_admitted_intent(40, 3), 2),
        MahiPreAdmittedInsertResult::Full
    ));
    assert_eq!(pool.stats().items, 2);
    assert_eq!(pool.stats().dropped_oldest_total, 0);

    let first = pool.drain_for_block(
        1_100,
        2,
        &BTreeMap::from([(40, 1)]),
        &BTreeMap::new(),
        &BTreeSet::new(),
    );
    assert_eq!(
        first
            .iter()
            .map(|intent| intent.intent.nonce)
            .collect::<Vec<_>>(),
        vec![1, 2]
    );
    assert!(matches!(
        pool.insert_with_limit(pre_admitted_intent(40, 3), 2),
        MahiPreAdmittedInsertResult::Accepted
    ));
    let second = pool.drain_for_block(
        1_100,
        2,
        &BTreeMap::from([(40, 3)]),
        &BTreeMap::new(),
        &BTreeSet::new(),
    );
    assert_eq!(
        second
            .iter()
            .map(|intent| intent.intent.nonce)
            .collect::<Vec<_>>(),
        vec![3]
    );
}

