#[test]
fn json_rpc_submit_intent_relay_header_bypasses_leader_forwarding() {
    let (mut engine, network_bootstrap) = follower_network_fixture("http://127.0.0.1:1");
    engine
        .policy_store_mut()
        .insert(sample_policy())
        .expect("policy should insert");
    let server = JsonRpcHttpServer::new_with_config(
        Arc::new(Mutex::new(engine)),
        JsonRpcServerConfig {
            manual_block_production_enabled: false,
            mahi_enabled: false,
            operator_bearer_token: None,
            peer_relay_bearer_token: None,
            network_bootstrap: Some(network_bootstrap),
            peer_transport_enabled: false,
        },
    );
    let signer = signing_key(8);
    let signed = signed_intent(&signer, 1, 10_000, IntentKind::Cancel { order_id: 7 });
    let expected_intent_id = intent_id(&signed);
    let body = serde_json::to_string(&JsonRpcRequest {
        jsonrpc: "2.0".into(),
        method: "kombat_submitIntent".into(),
        params: serde_json::to_value(SubmitIntentParams {
            signed_intent: SignedIntentJson {
                intent: IntentJson {
                    chain_id: signed.intent.chain_id,
                    account: signed.intent.account,
                    policy_id: signed.intent.policy_id,
                    nonce: signed.intent.nonce,
                    expires_at: signed.intent.expires_at,
                    predicate: None,
                    kind: IntentKindJson::Cancel { order_id: 7 },
                },
                signature_hex: encode_hex(&signed.signature),
            },
            timestamp_ms: 1_100,
        })
        .expect("params should serialize"),
        id: json!(79),
    })
    .expect("request should serialize");
    let headers = BTreeMap::from([(
        NETWORK_RELAY_HEADER.to_string(),
        NETWORK_SUBMIT_INTENT_RELAY.to_string(),
    )]);

    let response: JsonRpcResponse =
        serde_json::from_str(&server.handle_json_request_with_headers(&body, &headers))
            .expect("response should parse");

    assert!(response.error.is_none(), "{:?}", response.error);
    let deadline = Instant::now() + Duration::from_secs(1);
    loop {
        let status: JsonRpcResponse = serde_json::from_str(
            &server.handle_json_request(
                &serde_json::to_string(&JsonRpcRequest {
                    jsonrpc: "2.0".into(),
                    method: "kombat_getIntentStatus".into(),
                    params: json!({
                        "intent_id_hex": encode_hex(&expected_intent_id)
                    }),
                    id: json!(80),
                })
                .expect("request should serialize"),
            ),
        )
        .expect("status response should parse");
        let status_result = status.result.expect("status result should exist");
        assert!(
            status_result["stage"] == "accepted_direct" || status_result["stage"] == "unknown",
            "unexpected stage: {:?}",
            status_result["stage"]
        );
        if status_result["currently_queued"] == json!(true)
            || status_result["stage"] == "accepted_direct"
        {
            break;
        }
        if Instant::now() >= deadline {
            panic!("relay-header submit never became queued or locally accepted: {status_result}");
        }
        std::thread::sleep(Duration::from_millis(20));
    }
}

#[test]
fn consensus_metrics_reports_live_peer_reachability() {
    let listener = TcpListener::bind("127.0.0.1:0").expect("listener should bind");
    let reachable_endpoint = format!("http://{}", listener.local_addr().expect("addr"));
    let server_thread = std::thread::spawn(move || {
        let (mut stream, _) = listener.accept().expect("client should connect");
        let request = read_http_request(&mut stream).expect("request should parse");
        assert_eq!(request.path, "/network/ping");
        let body = json!({
            "chain_id": 7,
            "current_round": 1,
            "head_height": 0,
            "head_hash_hex": format!("0x{}", hex::encode([0_u8; 32])),
        })
        .to_string();
        let raw_response = format!(
            "HTTP/1.1 200 OK\r\nContent-Type: application/json\r\nContent-Length: {}\r\n\r\n{}",
            body.len(),
            body
        );
        stream
            .write_all(raw_response.as_bytes())
            .expect("response should write");
    });

    let (engine, network_bootstrap) = follower_network_fixture_with_leader_endpoints(&[
        "http://127.0.0.1:1",
        &reachable_endpoint,
    ]);
    let server = JsonRpcHttpServer::new_with_config(
        Arc::new(Mutex::new(engine)),
        JsonRpcServerConfig {
            manual_block_production_enabled: false,
            mahi_enabled: false,
            operator_bearer_token: None,
            peer_relay_bearer_token: None,
            network_bootstrap: Some(network_bootstrap),
            peer_transport_enabled: false,
        },
    );

    let metrics_body = serde_json::to_string(&JsonRpcRequest {
        jsonrpc: "2.0".into(),
        method: "kombat_getConsensusMetrics".into(),
        params: json!({}),
        id: json!(7_003),
    })
    .expect("request should serialize");
    let metrics_response: JsonRpcResponse =
        serde_json::from_str(&server.handle_json_request(&metrics_body))
            .expect("response should parse");
    let metrics = metrics_response
        .result
        .expect("metrics response should contain result");

    assert_eq!(metrics["peer_count"], 1);
    assert_eq!(metrics["reachable_peer_count"], 1);
    assert_eq!(metrics["unreachable_peer_urls"], json!([]));
    assert_eq!(metrics["peer_transport_session_count"], 0);
    assert_eq!(metrics["peer_transport_sessions"], json!([]));
    assert_eq!(metrics["inbound_peer_transport_session_count"], 0);
    assert_eq!(metrics["inbound_peer_transport_sessions"], json!([]));

    server_thread.join().expect("server thread should join");
}

fn peer_repair_metadata(height: u64, hash_hex: &str) -> PeerTransportSessionMetadata {
    PeerTransportSessionMetadata {
        remote_chain_id: Some(7),
        remote_validator_id_hex: Some(encode_hex(&validator(1))),
        remote_current_round: Some(1),
        remote_current_view: Some(0),
        remote_head_height: Some(height),
        remote_head_hash_hex: Some(hash_hex.to_owned()),
        remote_committed_state_root_hex: Some("0xaa".into()),
        remote_last_committed_round: Some(0),
        remote_peer_count: Some(3),
    }
}

fn peer_repair_heartbeat(
    validator_byte: u8,
    height: u64,
    hash_hex: &str,
) -> PeerTransportSessionHeartbeatResponse {
    peer_repair_heartbeat_with_root(validator_byte, height, hash_hex, "0xaa")
}

fn peer_repair_heartbeat_with_root(
    validator_byte: u8,
    height: u64,
    hash_hex: &str,
    committed_state_root_hex: &str,
) -> PeerTransportSessionHeartbeatResponse {
    PeerTransportSessionHeartbeatResponse {
        alive: true,
        session_id: u64::from(validator_byte),
        chain_id: Some(7),
        validator_id_hex: Some(encode_hex(&validator(validator_byte))),
        current_round: Some(1),
        current_view: Some(0),
        head_height: Some(height),
        head_hash_hex: Some(hash_hex.to_owned()),
        committed_state_root_hex: Some(committed_state_root_hex.to_owned()),
        last_committed_round: Some(0),
        peer_count: Some(3),
    }
}

#[test]
fn peer_snapshot_repair_candidate_accepts_shallow_divergent_advance() {
    let local = peer_repair_metadata(10, "0x10");
    let heartbeat = peer_repair_heartbeat(2, 11, "0x20");

    let candidate = peer_snapshot_repair_candidate(&local, &["http://peer".into()], &heartbeat)
        .expect("one-block divergent advance should be eligible after stall");

    assert_eq!(candidate.remote_head_height, 11);
    assert_eq!(candidate.remote_head_hash_hex.as_deref(), Some("0x20"));
}

#[test]
fn peer_snapshot_repair_accepts_authoritative_same_height_majority_with_same_root() {
    let local = peer_repair_metadata(10, "0xff");
    let peer_a = peer_snapshot_repair_candidate(
        &local,
        &["http://a".into()],
        &peer_repair_heartbeat(2, 10, "0x10"),
    )
    .expect("same-height peer observation should be tracked");
    let peer_b = peer_snapshot_repair_candidate(
        &local,
        &["http://b".into()],
        &peer_repair_heartbeat(3, 10, "0x10"),
    )
    .expect("same-height peer observation should be tracked");

    let candidate =
        peer_snapshot_repair_authoritative_same_height_candidate(&local, &[peer_a, peer_b], 3)
            .expect("peer majority at same height/root should be authoritative");

    assert!(candidate.authoritative_same_height);
    assert_eq!(candidate.remote_head_height, 10);
    assert_eq!(candidate.remote_head_hash_hex.as_deref(), Some("0x10"));
    assert_eq!(
        candidate.remote_committed_state_root_hex.as_deref(),
        Some("0xaa")
    );
}

