#[test]
fn peer_snapshot_repair_authoritative_same_height_rejects_single_peer_or_root_mismatch() {
    let local = peer_repair_metadata(10, "0x20");
    let single = peer_snapshot_repair_candidate(
        &local,
        &["http://a".into()],
        &peer_repair_heartbeat(2, 10, "0x10"),
    )
    .expect("same-height peer observation should be tracked");
    let mismatched_root = peer_snapshot_repair_candidate(
        &local,
        &["http://b".into()],
        &peer_repair_heartbeat_with_root(3, 10, "0x10", "0xbb"),
    )
    .expect("same-height peer observation should be tracked");
    let equal = peer_repair_heartbeat(3, 10, "0x20");

    assert!(
        peer_snapshot_repair_authoritative_same_height_candidate(&local, &[single.clone()], 3)
            .is_none()
    );
    assert!(peer_snapshot_repair_authoritative_same_height_candidate(
        &local,
        &[single, mismatched_root],
        3
    )
    .is_none());
    assert!(peer_snapshot_repair_candidate(&local, &["http://peer".into()], &equal).is_none());
}

#[test]
fn peer_snapshot_repair_authoritative_same_height_tiebreaks_full_same_root_split() {
    let local = peer_repair_metadata(10, "0x20");
    let peer_a = peer_snapshot_repair_candidate(
        &local,
        &["http://a".into()],
        &peer_repair_heartbeat(2, 10, "0x10"),
    )
    .expect("same-height peer observation should be tracked");
    let peer_b = peer_snapshot_repair_candidate(
        &local,
        &["http://b".into()],
        &peer_repair_heartbeat(3, 10, "0x30"),
    )
    .expect("same-height peer observation should be tracked");

    let candidate = peer_snapshot_repair_authoritative_same_height_candidate(
        &local,
        &[peer_a.clone(), peer_b.clone()],
        3,
    )
    .expect("full same-root split should deterministically select a canonical peer");

    assert!(candidate.authoritative_same_height);
    assert_eq!(candidate.remote_head_height, 10);
    assert_eq!(candidate.remote_head_hash_hex.as_deref(), Some("0x30"));
    assert_eq!(candidate.endpoints, vec!["http://b".to_owned()]);

    let local_already_canonical = peer_repair_metadata(10, "0x40");
    assert!(peer_snapshot_repair_authoritative_same_height_candidate(
        &local_already_canonical,
        &[peer_a, peer_b],
        3
    )
    .is_none());
}

#[test]
fn peer_snapshot_repair_candidate_prefers_height_then_hash() {
    let lower_height = PeerSnapshotRepairCandidate {
        endpoints: vec!["http://a".into()],
        remote_validator_id_hex: Some(encode_hex(&validator(2))),
        remote_head_height: 10,
        remote_head_hash_hex: Some("0xff".into()),
        remote_committed_state_root_hex: Some("0xaa".into()),
        authoritative_same_height: false,
    };
    let higher_height = PeerSnapshotRepairCandidate {
        endpoints: vec!["http://b".into()],
        remote_validator_id_hex: Some(encode_hex(&validator(3))),
        remote_head_height: 11,
        remote_head_hash_hex: Some("0x01".into()),
        remote_committed_state_root_hex: Some("0xaa".into()),
        authoritative_same_height: false,
    };
    let same_height_higher_hash = PeerSnapshotRepairCandidate {
        endpoints: vec!["http://c".into()],
        remote_validator_id_hex: Some(encode_hex(&validator(4))),
        remote_head_height: 11,
        remote_head_hash_hex: Some("0x02".into()),
        remote_committed_state_root_hex: Some("0xaa".into()),
        authoritative_same_height: false,
    };

    assert!(peer_snapshot_repair_candidate_is_better(
        &higher_height,
        &lower_height
    ));
    assert!(peer_snapshot_repair_candidate_is_better(
        &same_height_higher_hash,
        &higher_height
    ));
    assert!(!peer_snapshot_repair_candidate_is_better(
        &lower_height,
        &same_height_higher_hash
    ));
}

#[test]
fn consensus_metrics_reports_peer_transport_sessions() {
    let (leader_endpoint, join) = spawn_mock_peer_transport_bootstrap_server();
    let (engine, network_bootstrap) = follower_network_fixture(&leader_endpoint);
    let expected_head_hash_hex = encode_hex(&kombat_chain_consensus::block_hash(engine.head()));
    let server = JsonRpcHttpServer::new_with_config(
        Arc::new(Mutex::new(engine)),
        JsonRpcServerConfig {
            manual_block_production_enabled: false,
            mahi_enabled: false,
            operator_bearer_token: None,
            peer_relay_bearer_token: None,
            network_bootstrap: Some(network_bootstrap),
            peer_transport_enabled: true,
        },
    );

    let metrics_body = serde_json::to_string(&JsonRpcRequest {
        jsonrpc: "2.0".into(),
        method: "kombat_getConsensusMetrics".into(),
        params: json!({}),
        id: json!(7_004),
    })
    .expect("request should serialize");
    let metrics_response: JsonRpcResponse =
        serde_json::from_str(&server.handle_json_request(&metrics_body))
            .expect("response should parse");
    let metrics = metrics_response
        .result
        .expect("metrics response should contain result");

    assert_eq!(metrics["peer_count"], 1);
    assert_eq!(metrics["reachable_peer_count"], 1);
    assert_eq!(metrics["unreachable_peer_urls"], json!([]));
    assert_eq!(metrics["peer_transport_session_count"], 1);
    assert_eq!(metrics["inbound_peer_transport_session_count"], 0);
    assert_eq!(metrics["inbound_peer_transport_sessions"], json!([]));
    let sessions = metrics["peer_transport_sessions"]
        .as_array()
        .expect("peer transport sessions should be an array");
    assert_eq!(sessions.len(), 1);
    assert_eq!(sessions[0]["endpoint"], leader_endpoint);
    assert_eq!(sessions[0]["request_count"], 1);
    assert_eq!(sessions[0]["remote_session_id"], 1);
    assert_eq!(sessions[0]["remote_chain_id"], 7);
    assert_eq!(
        sessions[0]["remote_validator_id_hex"],
        format!("0x{}", hex::encode([8_u8; 32]))
    );
    assert_eq!(sessions[0]["remote_current_round"], 1);
    assert_eq!(sessions[0]["remote_current_view"], 0);
    assert_eq!(sessions[0]["remote_head_height"], 0);
    assert_eq!(sessions[0]["remote_head_hash_hex"], expected_head_hash_hex);
    assert_eq!(sessions[0]["remote_last_committed_round"], 0);
    assert_eq!(sessions[0]["remote_peer_count"], 1);
    assert!(
        sessions[0]["age_ms"]
            .as_u64()
            .expect("age should be numeric")
            <= 5_000
    );
    assert!(
        sessions[0]["idle_ms"]
            .as_u64()
            .expect("idle should be numeric")
            <= 5_000
    );

    let path = join.join().expect("server thread should join");
    assert_eq!(path, "/network/ping");
}

