#[test]
fn consensus_metrics_reports_inbound_peer_transport_sessions() {
    let expected_head_hash_hex = encode_hex(&kombat_chain_consensus::block_hash(
        single_node_engine().head(),
    ));
    let server = JsonRpcHttpServer::new_with_config(
        Arc::new(Mutex::new(single_node_engine())),
        JsonRpcServerConfig {
            manual_block_production_enabled: false,
            mahi_enabled: false,
            operator_bearer_token: None,
            peer_relay_bearer_token: None,
            network_bootstrap: Some(network_bootstrap_config()),
            peer_transport_enabled: true,
        },
    );
    let listener = TcpListener::bind("127.0.0.1:0").expect("listener should bind");
    let address = listener.local_addr().expect("listener addr should exist");
    let server_clone = server.clone();
    let server_thread = std::thread::spawn(move || {
        let (mut stream, _) = listener.accept().expect("client should connect");
        server_clone
            .handle_http_connection(&mut stream)
            .expect("peer transport connection should succeed");
    });

    let mut client = TcpStream::connect(address).expect("client should connect");
    client
        .write_all(PEER_TRANSPORT_MAGIC)
        .expect("magic should write");
    write_peer_transport_request(
        &mut client,
        &PeerTransportRequest {
            path: "/network/session/open".into(),
            headers: BTreeMap::new(),
            body: serde_json::to_string(&PeerTransportSessionOpenRequest {
                chain_id: Some(7),
                validator_id_hex: Some(format!("0x{}", hex::encode([6_u8; 32]))),
                current_round: Some(1),
                current_view: Some(0),
                head_height: Some(0),
                head_hash_hex: Some(expected_head_hash_hex.clone()),
                committed_state_root_hex: None,
                last_committed_round: Some(0),
                peer_count: Some(0),
            })
            .expect("session open body should serialize"),
        },
    )
    .expect("session open should write");
    let session_open = read_peer_transport_response(&mut client).expect("session open should read");
    assert!(session_open.error.is_none(), "{:?}", session_open.error);
    let opened: PeerTransportSessionOpenResponse = serde_json::from_str(
        session_open
            .body
            .as_deref()
            .expect("session open should include body"),
    )
    .expect("session open body should parse");
    assert_eq!(opened.current_round, Some(1));
    assert_eq!(opened.current_view, Some(0));
    assert_eq!(opened.head_height, Some(0));
    assert_eq!(opened.head_hash_hex, Some(expected_head_hash_hex.clone()));
    assert_eq!(opened.last_committed_round, Some(0));
    assert_eq!(opened.peer_count, Some(0));
    let refreshed_head_hash_hex = format!("0x{}", hex::encode([9_u8; 32]));
    write_peer_transport_request(
        &mut client,
        &PeerTransportRequest {
            path: "/network/session/heartbeat".into(),
            headers: BTreeMap::new(),
            body: serde_json::to_string(&PeerTransportSessionHeartbeatRequest {
                chain_id: Some(7),
                validator_id_hex: Some(format!("0x{}", hex::encode([6_u8; 32]))),
                current_round: Some(12),
                current_view: Some(11),
                head_height: Some(6),
                head_hash_hex: Some(refreshed_head_hash_hex.clone()),
                committed_state_root_hex: None,
                last_committed_round: Some(10),
                peer_count: Some(3),
            })
            .expect("heartbeat body should serialize"),
        },
    )
    .expect("heartbeat should write");
    let session_heartbeat =
        read_peer_transport_response(&mut client).expect("heartbeat should read");
    assert!(
        session_heartbeat.error.is_none(),
        "{:?}",
        session_heartbeat.error
    );
    let heartbeat: PeerTransportSessionHeartbeatResponse = serde_json::from_str(
        session_heartbeat
            .body
            .as_deref()
            .expect("heartbeat should include body"),
    )
    .expect("heartbeat body should parse");
    assert!(heartbeat.alive);
    assert_eq!(heartbeat.session_id, opened.session_id);
    assert_eq!(heartbeat.current_round, Some(1));
    assert_eq!(heartbeat.current_view, Some(0));
    assert_eq!(heartbeat.head_height, Some(0));
    assert_eq!(
        heartbeat.head_hash_hex,
        Some(expected_head_hash_hex.clone())
    );
    assert_eq!(heartbeat.last_committed_round, Some(0));
    assert_eq!(heartbeat.peer_count, Some(0));

    let metrics_body = serde_json::to_string(&JsonRpcRequest {
        jsonrpc: "2.0".into(),
        method: "kombat_getConsensusMetrics".into(),
        params: json!({}),
        id: json!(7_005),
    })
    .expect("request should serialize");
    let metrics_response: JsonRpcResponse =
        serde_json::from_str(&server.handle_json_request(&metrics_body))
            .expect("response should parse");
    let metrics = metrics_response
        .result
        .expect("metrics response should contain result");

    assert_eq!(metrics["peer_transport_session_count"], 0);
    assert_eq!(metrics["peer_transport_sessions"], json!([]));
    assert_eq!(metrics["inbound_peer_transport_session_count"], 1);
    let inbound_sessions = metrics["inbound_peer_transport_sessions"]
        .as_array()
        .expect("inbound peer transport sessions should be an array");
    assert_eq!(inbound_sessions.len(), 1);
    assert_eq!(inbound_sessions[0]["session_id"], opened.session_id);
    assert_eq!(inbound_sessions[0]["request_count"], 2);
    assert_eq!(inbound_sessions[0]["remote_chain_id"], 7);
    assert_eq!(
        inbound_sessions[0]["remote_validator_id_hex"],
        format!("0x{}", hex::encode([6_u8; 32]))
    );
    assert_eq!(inbound_sessions[0]["remote_current_round"], 12);
    assert_eq!(inbound_sessions[0]["remote_current_view"], 11);
    assert_eq!(inbound_sessions[0]["remote_head_height"], 6);
    assert_eq!(
        inbound_sessions[0]["remote_head_hash_hex"],
        refreshed_head_hash_hex
    );
    assert_eq!(inbound_sessions[0]["remote_last_committed_round"], 10);
    assert_eq!(inbound_sessions[0]["remote_peer_count"], 3);
    assert!(
        inbound_sessions[0]["age_ms"]
            .as_u64()
            .expect("age should be numeric")
            <= 5_000
    );
    assert!(
        inbound_sessions[0]["idle_ms"]
            .as_u64()
            .expect("idle should be numeric")
            <= 5_000
    );

    write_peer_transport_request(
        &mut client,
        &PeerTransportRequest {
            path: "/network/session/close".into(),
            headers: BTreeMap::new(),
            body: String::new(),
        },
    )
    .expect("session close should write");
    let session_close =
        read_peer_transport_response(&mut client).expect("session close should read");
    assert!(session_close.error.is_none(), "{:?}", session_close.error);
    let closed: PeerTransportSessionCloseResponse = serde_json::from_str(
        session_close
            .body
            .as_deref()
            .expect("session close should include body"),
    )
    .expect("session close body should parse");
    assert!(closed.closed);
    assert_eq!(closed.session_id, opened.session_id);

    drop(client);
    server_thread.join().expect("server thread should join");

    let metrics_response_after_close: JsonRpcResponse =
        serde_json::from_str(&server.handle_json_request(&metrics_body))
            .expect("response should parse");
    let metrics_after_close = metrics_response_after_close
        .result
        .expect("metrics response should contain result");
    assert_eq!(
        metrics_after_close["inbound_peer_transport_session_count"],
        0
    );
    assert_eq!(
        metrics_after_close["inbound_peer_transport_sessions"],
        json!([])
    );
}

#[test]
fn consensus_metrics_reaps_stale_inbound_peer_transport_sessions() {
    let server = JsonRpcHttpServer::new_with_config(
        Arc::new(Mutex::new(single_node_engine())),
        JsonRpcServerConfig {
            manual_block_production_enabled: false,
            mahi_enabled: false,
            operator_bearer_token: None,
            peer_relay_bearer_token: None,
            network_bootstrap: Some(network_bootstrap_config()),
            peer_transport_enabled: true,
        },
    );
    server.touch_inbound_peer_transport_session_with_metadata(
        77,
        Some("127.0.0.1:9000"),
        &PeerTransportSessionMetadata {
            remote_chain_id: Some(7),
            remote_validator_id_hex: Some(format!("0x{}", hex::encode([6_u8; 32]))),
            remote_current_round: Some(12),
            remote_current_view: Some(11),
            remote_head_height: Some(6),
            remote_head_hash_hex: Some(format!("0x{}", hex::encode([9_u8; 32]))),
            remote_committed_state_root_hex: None,
            remote_last_committed_round: Some(10),
            remote_peer_count: Some(3),
        },
    );
    {
        let mut sessions = server
            .active_peer_transport_sessions
            .lock()
            .expect("session lock should not be poisoned");
        let session = sessions.get_mut(&77).expect("test session should exist");
        session.last_used_at =
            Instant::now() - PEER_TRANSPORT_SESSION_STALE_TIMEOUT - Duration::from_secs(1);
    }

    let metrics_body = serde_json::to_string(&JsonRpcRequest {
        jsonrpc: "2.0".into(),
        method: "kombat_getConsensusMetrics".into(),
        params: json!({}),
        id: json!(7_006),
    })
    .expect("request should serialize");
    let metrics_response: JsonRpcResponse =
        serde_json::from_str(&server.handle_json_request(&metrics_body))
            .expect("response should parse");
    let metrics = metrics_response
        .result
        .expect("metrics response should contain result");

    assert_eq!(metrics["inbound_peer_transport_session_count"], 0);
    assert_eq!(metrics["inbound_peer_transport_sessions"], json!([]));
}

#[test]
fn peer_transport_heartbeat_response_reports_alive_session() {
    let engine = single_node_engine();
    let expected_head_hash_hex = encode_hex(&block_hash(engine.head()));
    let server = JsonRpcHttpServer::new_with_config(
        Arc::new(Mutex::new(engine)),
        JsonRpcServerConfig {
            manual_block_production_enabled: false,
            mahi_enabled: false,
            operator_bearer_token: None,
            peer_relay_bearer_token: None,
            network_bootstrap: Some(network_bootstrap_config()),
            peer_transport_enabled: true,
        },
    );

    let response = raw_peer_transport_response(
        server,
        PeerTransportRequest {
            path: "/network/session/heartbeat".into(),
            headers: BTreeMap::new(),
            body: String::new(),
        },
    );
    assert!(response.error.is_none(), "{:?}", response.error);
    let heartbeat: PeerTransportSessionHeartbeatResponse = serde_json::from_str(
        response
            .body
            .as_deref()
            .expect("heartbeat should include body"),
    )
    .expect("heartbeat body should parse");
    assert!(heartbeat.alive);
    assert_eq!(heartbeat.session_id, 1);
    assert_eq!(heartbeat.chain_id, Some(7));
    assert!(heartbeat
        .validator_id_hex
        .as_deref()
        .is_some_and(|validator_id| validator_id.starts_with("0x")));
    assert_eq!(heartbeat.current_round, Some(1));
    assert_eq!(heartbeat.current_view, Some(0));
    assert_eq!(heartbeat.head_height, Some(0));
    assert_eq!(heartbeat.head_hash_hex, Some(expected_head_hash_hex));
    assert_eq!(heartbeat.last_committed_round, Some(0));
    assert_eq!(heartbeat.peer_count, Some(0));
}

#[test]
fn json_rpc_create_account_fans_out_to_network_peers() {
    let response = JsonRpcResponse {
        jsonrpc: "2.0".into(),
        result: Some(json!({
            "id": 11,
            "owner": format!("0x{}", hex::encode(signing_key(8).verifying_key().to_bytes())),
            "pending_owner": Value::Null,
            "created_at": 1_000,
            "paused": false,
            "frozen": false,
            "controllers": [],
            "nonce": 0,
            "code_hash": format!("0x{}", hex::encode([9_u8; 32])),
        })),
        error: None,
        id: json!(87),
    };
    let (peer_endpoint, join) = spawn_mock_json_rpc_server_with_request(response);
    let (engine, network_bootstrap) = follower_network_fixture(&peer_endpoint);
    let signer = signing_key(8);
    let server = JsonRpcHttpServer::new_with_config(
        Arc::new(Mutex::new(engine)),
        JsonRpcServerConfig {
            manual_block_production_enabled: false,
            mahi_enabled: false,
            operator_bearer_token: None,
            peer_relay_bearer_token: None,
            network_bootstrap: Some(network_bootstrap),
            peer_transport_enabled: false,
        },
    );
    let body = serde_json::to_string(&JsonRpcRequest {
        jsonrpc: "2.0".into(),
        method: "kombat_createAccount".into(),
        params: json!({
            "account_id": 11,
            "owner_hex": encode_hex(signer.verifying_key().as_bytes()),
            "code_hash_hex": encode_hex(&[9_u8; 32]),
            "timestamp_ms": 1_000,
        }),
        id: json!(87),
    })
    .expect("request should serialize");

    let response: JsonRpcResponse =
        serde_json::from_str(&server.handle_json_request(&body)).expect("response should parse");

    assert!(response.error.is_none(), "{:?}", response.error);
    let account_response: JsonRpcResponse = serde_json::from_str(
        &server.handle_json_request(
            &serde_json::to_string(&JsonRpcRequest {
                jsonrpc: "2.0".into(),
                method: "kombat_getAccount".into(),
                params: json!({ "account_id": 11 }),
                id: json!(90),
            })
            .expect("request should serialize"),
        ),
    )
    .expect("account response should parse");
    assert_eq!(
        account_response.result.expect("result should exist")["id"],
        json!(11)
    );

    let request = join.join().expect("server thread should join");
    assert_eq!(
        request
            .headers
            .get(NETWORK_RELAY_HEADER)
            .map(String::as_str),
        Some(NETWORK_CREATE_ACCOUNT_RELAY)
    );
    assert!(request.body.contains("\"method\":\"kombat_createAccount\""));
}

#[test]
fn json_rpc_create_account_relay_header_bypasses_network_fanout() {
    let signer = signing_key(8);
    let (engine, network_bootstrap) = follower_network_fixture("http://127.0.0.1:1");
    let server = JsonRpcHttpServer::new_with_config(
        Arc::new(Mutex::new(engine)),
        JsonRpcServerConfig {
            manual_block_production_enabled: false,
            mahi_enabled: false,
            operator_bearer_token: None,
            peer_relay_bearer_token: None,
            network_bootstrap: Some(network_bootstrap),
            peer_transport_enabled: false,
        },
    );
    let body = serde_json::to_string(&JsonRpcRequest {
        jsonrpc: "2.0".into(),
        method: "kombat_createAccount".into(),
        params: json!({
            "account_id": 11,
            "owner_hex": encode_hex(signer.verifying_key().as_bytes()),
            "code_hash_hex": encode_hex(&[9_u8; 32]),
            "timestamp_ms": 1_000,
        }),
        id: json!(86),
    })
    .expect("request should serialize");
    let headers = BTreeMap::from([(
        NETWORK_RELAY_HEADER.to_string(),
        NETWORK_CREATE_ACCOUNT_RELAY.to_string(),
    )]);

    let response: JsonRpcResponse =
        serde_json::from_str(&server.handle_json_request_with_headers(&body, &headers))
            .expect("response should parse");

    assert!(response.error.is_none(), "{:?}", response.error);
    let account_response: JsonRpcResponse = serde_json::from_str(
        &server.handle_json_request(
            &serde_json::to_string(&JsonRpcRequest {
                jsonrpc: "2.0".into(),
                method: "kombat_getAccount".into(),
                params: json!({ "account_id": 11 }),
                id: json!(91),
            })
            .expect("request should serialize"),
        ),
    )
    .expect("account response should parse");
    assert_eq!(
        account_response.result.expect("result should exist")["id"],
        json!(11)
    );
}

#[test]
fn json_rpc_submit_owner_call_fans_out_to_network_peers() {
    let response = JsonRpcResponse {
        jsonrpc: "2.0".into(),
        result: Some(json!({
            "accepted": true,
            "account_id": 11,
            "chain_id": 7,
            "nonce": 0,
            "action": "pause",
            "policy_id": Value::Null,
            "new_owner": Value::Null,
            "code_hash": Value::Null,
        })),
        error: None,
        id: json!(88),
    };
    let (peer_endpoint, join) = spawn_mock_json_rpc_server_with_request(response);
    let (mut engine, network_bootstrap) = follower_network_fixture(&peer_endpoint);
    let signer = signing_key(8);
    engine
        .create_account(11, signer.verifying_key().to_bytes(), [9; 32], 1_000)
        .expect("account should create");
    let engine = Arc::new(Mutex::new(engine));
    let server = JsonRpcHttpServer::new_with_config(
        engine.clone(),
        JsonRpcServerConfig {
            manual_block_production_enabled: false,
            mahi_enabled: false,
            operator_bearer_token: None,
            peer_relay_bearer_token: None,
            network_bootstrap: Some(network_bootstrap),
            peer_transport_enabled: false,
        },
    );
    let params = SubmitOwnerCallParams {
        signed_owner_call: serde_json::from_value(signed_owner_call_json(
            &signer,
            11,
            7,
            0,
            OwnerActionJson::Pause,
        ))
        .expect("signed owner call should deserialize"),
        timestamp_ms: 1_050,
    };
    let body = serde_json::to_string(&JsonRpcRequest {
        jsonrpc: "2.0".into(),
        method: "kombat_submitOwnerCall".into(),
        params: serde_json::to_value(params).expect("params should serialize"),
        id: json!(88),
    })
    .expect("request should serialize");

    let forwarded: JsonRpcResponse =
        serde_json::from_str(&server.handle_json_request(&body)).expect("response should parse");

    assert!(forwarded.error.is_none(), "{:?}", forwarded.error);
    let account_response: JsonRpcResponse = serde_json::from_str(
        &server.handle_json_request(
            &serde_json::to_string(&JsonRpcRequest {
                jsonrpc: "2.0".into(),
                method: "kombat_getAccount".into(),
                params: json!({ "account_id": 11 }),
                id: json!(90),
            })
            .expect("request should serialize"),
        ),
    )
    .expect("account response should parse");
    assert_eq!(
        account_response.result.expect("result should exist")["paused"],
        json!(true)
    );

    let request = join.join().expect("server thread should join");
    assert_eq!(
        request
            .headers
            .get(NETWORK_RELAY_HEADER)
            .map(String::as_str),
        Some(NETWORK_OWNER_CALL_RELAY)
    );
    assert!(request
        .body
        .contains("\"method\":\"kombat_submitOwnerCall\""));
}

