#[test]
fn json_rpc_submit_delegation_action_queues_pending_action() {
    let mut initial_engine = single_node_engine();
    seed_account_policy_usdc(&mut initial_engine, 22, 5_000_000_000);
    let mandate = {
        let mut service = NodeRpcService::new(&mut initial_engine);
        service
            .create_mandate(sample_create_mandate_params(22, 1))
            .expect("mandate should create")
            .mandate
    };
    let engine = Arc::new(Mutex::new(initial_engine));
    let server = JsonRpcHttpServer::new_with_config(
        engine.clone(),
        JsonRpcServerConfig {
            manual_block_production_enabled: false,
            mahi_enabled: false,
            operator_bearer_token: None,
            peer_relay_bearer_token: None,
            network_bootstrap: None,
            peer_transport_enabled: false,
        },
    );
    let action = BlockDelegationAction::Open {
        agent: 22,
        mandate_id: mandate.id,
        performance_share_units: 1_000,
        crystallization_cadence_ms: 7 * 86_400 * 1_000,
        notice_period_ms: 24 * 3_600 * 1_000,
        agent_bond: 5_000_000_000,
    };
    let action_id = derive_legacy_delegation_action_id(&action, 1_050);
    let params = SubmitDelegationActionParams {
        action_id_hex: encode_hex(&action_id),
        action_hex: super::encode_borsh_hex(&action),
        timestamp_ms: 1_050,
        submitter_nonce: None,
        wait_timeout_ms: None,
    };
    let body = serde_json::to_string(&JsonRpcRequest {
        jsonrpc: "2.0".into(),
        method: "kombat_submitDelegationAction".into(),
        params: serde_json::to_value(&params).expect("params should serialize"),
        id: json!(95),
    })
    .expect("request should serialize");

    let first: JsonRpcResponse = with_legacy_delegation_bridge_enabled(|| {
        serde_json::from_str(&server.handle_json_request(&body)).expect("response should parse")
    });
    assert!(first.error.is_none(), "{:?}", first.error);
    let result = first.result.as_ref().expect("result should exist");
    assert_eq!(result["action_id_hex"], encode_hex(&action_id));
    assert_eq!(result["status"], "accepted");
    assert_eq!(result["pending_delegation_actions"], 1);

    let duplicate: JsonRpcResponse = with_legacy_delegation_bridge_enabled(|| {
        serde_json::from_str(&server.handle_json_request(&body))
            .expect("duplicate response should parse")
    });
    assert!(duplicate.error.is_none(), "{:?}", duplicate.error);
    assert_eq!(
        duplicate.result.as_ref().unwrap()["status"],
        "duplicate_pending"
    );
    assert_eq!(
        engine
            .lock()
            .expect("engine lock should succeed")
            .pending_delegation_action_count(),
        1
    );

    let status_body = serde_json::to_string(&JsonRpcRequest {
        jsonrpc: "2.0".into(),
        method: "kombat_getDelegationActionStatus".into(),
        params: json!({ "action_id_hex": encode_hex(&action_id) }),
        id: json!(97),
    })
    .expect("status request should serialize");
    let status: JsonRpcResponse = serde_json::from_str(&server.handle_json_request(&status_body))
        .expect("status response should parse");
    assert!(status.error.is_none(), "{:?}", status.error);
    let status_result = status.result.as_ref().expect("status result should exist");
    assert_eq!(status_result["status"], "pending");
    assert_eq!(status_result["action_kind"], "open");
    assert_eq!(status_result["submitted_at_ms"], 1_050);

    engine
        .lock()
        .expect("engine lock should succeed")
        .produce_block_from_mempool(1_100, 1)
        .expect("queued action should commit");
    let processed: JsonRpcResponse =
        serde_json::from_str(&server.handle_json_request(&status_body))
            .expect("processed status response should parse");
    assert!(processed.error.is_none(), "{:?}", processed.error);
    let processed_result = processed
        .result
        .as_ref()
        .expect("processed result should exist");
    assert_eq!(processed_result["status"], "processed");
    assert_eq!(processed_result["receipt"]["kind"], "open");
    assert_eq!(
        processed_result["receipt"]["delegation_id_hex"],
        encode_hex(&super::derive_delegation_id(22, &mandate.id, 1_050))
    );

    let unknown_body = serde_json::to_string(&JsonRpcRequest {
        jsonrpc: "2.0".into(),
        method: "kombat_getDelegationActionStatus".into(),
        params: json!({ "action_id_hex": encode_hex(&[0xee_u8; 32]) }),
        id: json!(99),
    })
    .expect("unknown status request should serialize");
    let unknown: JsonRpcResponse = serde_json::from_str(&server.handle_json_request(&unknown_body))
        .expect("unknown status response should parse");
    assert!(unknown.error.is_none(), "{:?}", unknown.error);
    let unknown_result = unknown
        .result
        .as_ref()
        .expect("unknown result should exist");
    assert_eq!(unknown_result["status"], "unknown");
    assert_eq!(unknown_result["action_kind"], Value::Null);
    assert_eq!(unknown_result["submitted_at_ms"], Value::Null);
    assert_eq!(unknown_result["processed_at_ms"], Value::Null);
    assert_eq!(unknown_result["receipt"], Value::Null);
}

