#[test]
fn json_rpc_legacy_delegation_bridge_is_disabled_by_default_without_blocking_signed_submission() {
    let signer = signing_key(22);
    let mut initial_engine = single_node_engine();
    let mandate_id = seed_signed_delegation_open_prereqs(&mut initial_engine, &signer);
    let engine = Arc::new(Mutex::new(initial_engine));
    let server = JsonRpcHttpServer::new_with_config(
        engine.clone(),
        JsonRpcServerConfig {
            manual_block_production_enabled: false,
            mahi_enabled: false,
            operator_bearer_token: None,
            peer_relay_bearer_token: None,
            network_bootstrap: None,
            peer_transport_enabled: false,
        },
    );
    let action = signed_delegation_open_action(mandate_id);
    let legacy_action_id = super::delegation_action_id_for_submission(&action, 1_050, None);
    let legacy_body = serde_json::to_string(&JsonRpcRequest {
        jsonrpc: "2.0".into(),
        method: "kombat_submitDelegationAction".into(),
        params: serde_json::to_value(SubmitDelegationActionParams {
            action_id_hex: encode_hex(&legacy_action_id),
            action_hex: super::encode_borsh_hex(&action),
            timestamp_ms: 1_050,
            submitter_nonce: None,
            wait_timeout_ms: None,
        })
        .expect("params should serialize"),
        id: json!(115),
    })
    .expect("request should serialize");
    let signed = signed_delegation_action_json(&signer, 7, 22, action, 1_051, Some(56));
    let signed_body = serde_json::to_string(&JsonRpcRequest {
        jsonrpc: "2.0".into(),
        method: "kombat_submitSignedDelegationAction".into(),
        params: serde_json::to_value(SubmitSignedDelegationActionParams {
            signed_delegation_action: signed,
            wait_timeout_ms: None,
        })
        .expect("params should serialize"),
        id: json!(116),
    })
    .expect("request should serialize");

    let (legacy_response, signed_response): (JsonRpcResponse, JsonRpcResponse) = with_env_vars(
        &[(super::LEGACY_DELEGATION_BRIDGE_ENABLED_ENV, None)],
        || {
            (
                serde_json::from_str(&server.handle_json_request(&legacy_body))
                    .expect("legacy response should parse"),
                serde_json::from_str(&server.handle_json_request(&signed_body))
                    .expect("signed response should parse"),
            )
        },
    );

    let error = legacy_response.error.expect("legacy bridge should reject");
    assert_eq!(error.code, -32026);
    assert_eq!(
        error.data.expect("error data should exist")["reason"],
        "legacy_delegation_bridge_disabled"
    );
    assert!(
        signed_response.error.is_none(),
        "{:?}",
        signed_response.error
    );
    assert_eq!(
        signed_response.result.expect("signed result should exist")["status"],
        "accepted"
    );
    assert_eq!(
        engine
            .lock()
            .expect("engine lock should succeed")
            .pending_delegation_action_count(),
        1
    );
}

