#[test]
fn json_rpc_submit_evm_delegation_action_queues_deposit_and_rejects_invalid_wallet_cases() {
    let agent_signer = signing_key(22);
    let (principal_secret, principal_address) = evm_wallet(61);
    let principal_owner = evm_owner_principal(principal_address);
    let mut initial_engine = single_node_engine();
    let mandate_id = seed_signed_delegation_open_prereqs(&mut initial_engine, &agent_signer);
    initial_engine
        .create_account(11, principal_owner, [8; 32], 901)
        .expect("principal account should create");
    link_account_evm_address_for_test(&mut initial_engine, 11, principal_address);
    seed_policy_usdc_for_address(&mut initial_engine, principal_address, 250_000_000);
    let opened = {
        let mut service = NodeRpcService::new(&mut initial_engine);
        service
            .open_delegation(OpenDelegationParams {
                agent: 22,
                mandate_id_hex: encode_hex(&mandate_id),
                performance_share_units: 1_000,
                crystallization_cadence_ms: 7 * 86_400 * 1_000,
                notice_period_ms: 24 * 3_600 * 1_000,
                agent_bond: "5000000000".into(),
                timestamp_ms: 1_000,
                submitter_nonce: Some(60),
            })
            .expect("delegation should open")
            .delegation
    };
    list_delegation_for_real_capital(&mut initial_engine, &opened, true, true);
    {
        let service = NodeRpcService::new(&mut initial_engine);
        assert_eq!(
            service.account_evm_address(11),
            Some(principal_address),
            "principal EVM link should survive delegation open"
        );
    }
    let engine = Arc::new(Mutex::new(initial_engine));
    let server = JsonRpcHttpServer::new_with_config(
        engine.clone(),
        JsonRpcServerConfig {
            manual_block_production_enabled: false,
            mahi_enabled: false,
            operator_bearer_token: None,
            peer_relay_bearer_token: None,
            network_bootstrap: None,
            peer_transport_enabled: false,
        },
    );
    let action = BlockDelegationAction::Deposit {
        principal: 11,
        delegation_id: opened.delegation_id,
        amount: 100_000_000,
    };
    let signed = signed_evm_delegation_action_json(
        &principal_secret,
        7,
        11,
        action.clone(),
        1_050,
        61,
        u64::MAX,
    );
    let decoded_signed = super::signed_evm_delegation_action_from_json(&signed)
        .expect("signed EVM delegation action should decode");
    let digest = evm_delegation_action_eip712_digest(&decoded_signed)
        .expect("signed EVM delegation action should hash");
    assert_eq!(
        super::recover_evm_owner_call_address(&digest, &decoded_signed.signature)
            .expect("signature should recover"),
        principal_address
    );
    let body = serde_json::to_string(&JsonRpcRequest {
        jsonrpc: "2.0".into(),
        method: "kombat_submitEvmDelegationAction".into(),
        params: serde_json::to_value(SubmitEvmDelegationActionParams {
            signed_delegation_action: signed.clone(),
            wait_timeout_ms: None,
        })
        .expect("params should serialize"),
        id: json!(205),
    })
    .expect("request should serialize");

    let response: JsonRpcResponse =
        serde_json::from_str(&server.handle_json_request(&body)).expect("response should parse");

    assert!(response.error.is_none(), "{:?}", response.error);
    let result = response.result.as_ref().expect("result should exist");
    assert_eq!(result["action_id_hex"], signed.action_id_hex);
    assert_eq!(result["status"], "accepted");
    assert_eq!(result["pending_delegation_actions"], 1);

    let relay_body = serde_json::to_string(&super::NetworkRelayEvmDelegationActionsRequest {
        items: vec![signed.clone()],
    })
    .expect("relay request should serialize");
    let relay_response: super::NetworkRelayDelegationActionsResponse = serde_json::from_str(
        &server
            .process_network_relay_evm_delegation_actions(&BTreeMap::new(), &relay_body)
            .expect("relay should process"),
    )
    .expect("relay response should parse");
    assert_eq!(relay_response.results.len(), 1);
    assert_eq!(
        relay_response.results[0].action_id_hex,
        signed.action_id_hex
    );
    assert_eq!(relay_response.results[0].status, "duplicate_pending");
    assert!(relay_response.results[0].error.is_none());

    let mismatched =
        signed_evm_delegation_action_json(&principal_secret, 7, 99, action, 1_051, 62, u64::MAX);
    let mismatched_body = serde_json::to_string(&JsonRpcRequest {
        jsonrpc: "2.0".into(),
        method: "kombat_submitEvmDelegationAction".into(),
        params: serde_json::to_value(SubmitEvmDelegationActionParams {
            signed_delegation_action: mismatched,
            wait_timeout_ms: None,
        })
        .expect("params should serialize"),
        id: json!(206),
    })
    .expect("request should serialize");
    let mismatched_response: JsonRpcResponse =
        serde_json::from_str(&server.handle_json_request(&mismatched_body))
            .expect("response should parse");
    let mismatched_error = mismatched_response
        .error
        .expect("signer mismatch should reject");
    assert_eq!(
        mismatched_error.data.expect("error data should exist")["reason"],
        "evm_signer_mismatch"
    );

    let unsupported = signed_evm_delegation_action_json(
        &principal_secret,
        7,
        22,
        signed_delegation_open_action(mandate_id),
        1_052,
        63,
        u64::MAX,
    );
    let unsupported_body = serde_json::to_string(&JsonRpcRequest {
        jsonrpc: "2.0".into(),
        method: "kombat_submitEvmDelegationAction".into(),
        params: serde_json::to_value(SubmitEvmDelegationActionParams {
            signed_delegation_action: unsupported,
            wait_timeout_ms: None,
        })
        .expect("params should serialize"),
        id: json!(207),
    })
    .expect("request should serialize");
    let unsupported_response: JsonRpcResponse =
        serde_json::from_str(&server.handle_json_request(&unsupported_body))
            .expect("response should parse");
    let unsupported_error = unsupported_response
        .error
        .expect("unsupported variant should reject");
    assert_eq!(
        unsupported_error.data.expect("error data should exist")["reason"],
        "wallet_write_not_supported"
    );
}

#[test]
fn json_rpc_submit_signed_market_maker_program_action_queues_enroll_and_reports_status() {
    let signer = signing_key(31);
    let mut initial_engine = single_node_engine();
    {
        let mut service = NodeRpcService::new(&mut initial_engine);
        service
            .list_perpetual_market(ListPerpetualMarketParams {
                market_id: 7,
                base_symbol: "BTC".into(),
                quote_asset: Some(1),
                oracle_feed_id: 77,
                initial_margin_bps: 1_000,
                maintenance_margin_bps: 500,
                max_leverage: 20,
                lot_size_microunits: 1,
                tick_size_bps: 1,
                funding_interval_ms: 3_600_000,
                oracle_max_staleness_ms: Some(2_500),
                breaker_price_band_bps: Some(500),
                oracle_min_sources: Some(2),
                oracle_min_confidence: Some(50),
                oracle_min_samples: Some(3),
                oracle_feeder_ids_hex: None,
                timestamp_ms: 1_000,
            })
            .expect("market should list");
    }
    initial_engine
        .create_account(31, signer.verifying_key().to_bytes(), [9; 32], 1_050)
        .expect("market maker account should create");
    seed_account_policy_usdc(
        &mut initial_engine,
        31,
        (PROGRAM_BOND_MIN_MICRO_USDC * 2) as u64,
    );
    let program = initial_engine
        .define_market_maker_program(market_maker_program_input(), 1_100)
        .expect("market-maker program should define");
    let action = BlockMarketMakerProgramAction::Enroll {
        market_maker_identity: MarketMakerIdentity::Account(31),
        market_id: 7,
        program_id: program.program_id,
        bond_micro_usdc: MarketMakerU256::from_u128(PROGRAM_BOND_MIN_MICRO_USDC).0,
    };
    let signed = signed_market_maker_program_action_json(&signer, 7, 31, action, 1_150, Some(71));
    let engine = Arc::new(Mutex::new(initial_engine));
    let server = JsonRpcHttpServer::new_with_config(
        engine.clone(),
        JsonRpcServerConfig {
            manual_block_production_enabled: false,
            mahi_enabled: false,
            operator_bearer_token: None,
            peer_relay_bearer_token: None,
            network_bootstrap: None,
            peer_transport_enabled: false,
        },
    );
    let submit_body = serde_json::to_string(&JsonRpcRequest {
        jsonrpc: "2.0".into(),
        method: "kombat_submitSignedMarketMakerProgramAction".into(),
        params: serde_json::to_value(SubmitSignedMarketMakerProgramActionParams {
            signed_market_maker_program_action: signed.clone(),
            wait_timeout_ms: Some(0),
        })
        .expect("params should serialize"),
        id: json!(117),
    })
    .expect("request should serialize");

    let submit_response: JsonRpcResponse =
        serde_json::from_str(&server.handle_json_request(&submit_body))
            .expect("submit response should parse");

    assert!(
        submit_response.error.is_none(),
        "{:?}",
        submit_response.error
    );
    let result = submit_response
        .result
        .as_ref()
        .expect("result should exist");
    assert_eq!(result["action_id_hex"], signed.action_id_hex);
    assert_eq!(result["status"], "accepted");
    assert_eq!(result["pending_market_maker_program_actions"], 1);
    assert_eq!(result["action_status"]["status"], "pending");
    assert_eq!(result["action_status"]["action_kind"], "enroll");

    let pending_status_body = serde_json::to_string(&JsonRpcRequest {
        jsonrpc: "2.0".into(),
        method: "kombat_getMarketMakerProgramActionStatus".into(),
        params: json!({ "action_id_hex": signed.action_id_hex }),
        id: json!(118),
    })
    .expect("request should serialize");
    let pending_status: JsonRpcResponse =
        serde_json::from_str(&server.handle_json_request(&pending_status_body))
            .expect("pending status response should parse");
    assert!(pending_status.error.is_none(), "{:?}", pending_status.error);
    assert_eq!(
        pending_status.result.as_ref().expect("status should exist")["status"],
        "pending"
    );

    engine
        .lock()
        .expect("engine lock should succeed")
        .produce_block_from_mempool(1_200, 10)
        .expect("market-maker program action should commit");

    let processed_status: JsonRpcResponse =
        serde_json::from_str(&server.handle_json_request(&pending_status_body))
            .expect("processed status response should parse");
    assert!(
        processed_status.error.is_none(),
        "{:?}",
        processed_status.error
    );
    let processed = processed_status
        .result
        .as_ref()
        .expect("processed status should exist");
    assert_eq!(processed["status"], "processed");
    assert_eq!(processed["action_kind"], "enroll");
    assert_eq!(processed["receipt"]["kind"], "enroll");
    assert_eq!(
        processed["receipt"]["market_maker_identity"],
        json!({
            "kind": "account",
            "account_id": 31,
        })
    );
    assert_eq!(processed["receipt"]["market_id"], 7);
    assert_eq!(
        processed["receipt"]["program_id_hex"],
        encode_hex(&program.program_id)
    );

    let unknown_body = serde_json::to_string(&JsonRpcRequest {
        jsonrpc: "2.0".into(),
        method: "kombat_getMarketMakerProgramActionStatus".into(),
        params: json!({ "action_id_hex": encode_hex(&[55_u8; 32]) }),
        id: json!(119),
    })
    .expect("request should serialize");
    let unknown_status: JsonRpcResponse =
        serde_json::from_str(&server.handle_json_request(&unknown_body))
            .expect("unknown status response should parse");
    assert!(unknown_status.error.is_none(), "{:?}", unknown_status.error);
    assert_eq!(
        unknown_status
            .result
            .as_ref()
            .expect("unknown status should exist")["status"],
        "unknown"
    );
}

#[test]
fn json_rpc_submit_signed_market_maker_program_action_forwards_to_network_leader() {
    let signer = signing_key(31);
    let action = BlockMarketMakerProgramAction::Enroll {
        market_maker_identity: MarketMakerIdentity::Account(31),
        market_id: 7,
        program_id: [7; 32],
        bond_micro_usdc: MarketMakerU256::from_u128(PROGRAM_BOND_MIN_MICRO_USDC).0,
    };
    let signed = signed_market_maker_program_action_json(&signer, 7, 31, action, 1_050, Some(72));
    let response = JsonRpcResponse {
        jsonrpc: "2.0".into(),
        result: Some(json!({
            "action_id_hex": signed.action_id_hex.clone(),
            "status": "accepted",
            "pending_market_maker_program_actions": 1
        })),
        error: None,
        id: json!(120),
    };
    let (leader_endpoint, join) = spawn_mock_json_rpc_server_with_request(response);
    let (engine, network_bootstrap) = follower_network_fixture(&leader_endpoint);
    let engine = Arc::new(Mutex::new(engine));
    let server = JsonRpcHttpServer::new_with_config(
        engine.clone(),
        JsonRpcServerConfig {
            manual_block_production_enabled: false,
            mahi_enabled: false,
            operator_bearer_token: None,
            peer_relay_bearer_token: None,
            network_bootstrap: Some(network_bootstrap),
            peer_transport_enabled: false,
        },
    );
    let body = serde_json::to_string(&JsonRpcRequest {
        jsonrpc: "2.0".into(),
        method: "kombat_submitSignedMarketMakerProgramAction".into(),
        params: serde_json::to_value(SubmitSignedMarketMakerProgramActionParams {
            signed_market_maker_program_action: signed,
            wait_timeout_ms: None,
        })
        .expect("params should serialize"),
        id: json!(120),
    })
    .expect("request should serialize");

    let forwarded: JsonRpcResponse = with_env_vars(
        &[(super::NETWORK_SUBMIT_FORWARDING_ENV, Some("1".into()))],
        || serde_json::from_str(&server.handle_json_request(&body)).expect("response should parse"),
    );

    assert!(forwarded.error.is_none(), "{:?}", forwarded.error);
    assert_eq!(
        forwarded.result.expect("result should exist")["status"],
        "accepted"
    );
    assert_eq!(
        engine
            .lock()
            .expect("engine lock should succeed")
            .pending_market_maker_program_action_count(),
        0,
        "follower should forward rather than queue locally"
    );
    let request = join.join().expect("server thread should join");
    assert_eq!(
        request
            .headers
            .get(NETWORK_RELAY_HEADER)
            .map(String::as_str),
        Some(NETWORK_SUBMIT_INTENT_FORWARD)
    );
    assert!(request
        .body
        .contains("\"method\":\"kombat_submitSignedMarketMakerProgramAction\""));
}

