#[test]
fn json_rpc_submit_signed_delegation_action_relay_header_suppresses_gossip() {
    let signer = signing_key(22);
    let (local_server, local_engine, peer_engine, mandate_id) =
        signed_delegation_gossip_fixture(&signer);
    let signed = signed_delegation_action_json(
        &signer,
        7,
        22,
        signed_delegation_open_action(mandate_id),
        1_050,
        Some(55),
    );
    let body = serde_json::to_string(&JsonRpcRequest {
        jsonrpc: "2.0".into(),
        method: "kombat_submitSignedDelegationAction".into(),
        params: serde_json::to_value(SubmitSignedDelegationActionParams {
            signed_delegation_action: signed,
            wait_timeout_ms: None,
        })
        .expect("params should serialize"),
        id: json!(114),
    })
    .expect("request should serialize");
    // Direct relay endpoint traffic does not enter JSON-RPC dispatch; this covers the
    // defense-in-depth path where a relayed request re-enters the public method with the header.
    let headers = BTreeMap::from([(
        NETWORK_RELAY_HEADER.to_string(),
        NETWORK_SIGNED_DELEGATION_RELAY.to_string(),
    )]);

    let response: JsonRpcResponse = with_env_vars(
        &[
            (super::SIGNED_DELEGATION_GOSSIP_ENV, None),
            (super::NETWORK_SUBMIT_FORWARDING_ENV, Some("0".into())),
        ],
        || {
            serde_json::from_str(&local_server.handle_json_request_with_headers(&body, &headers))
                .expect("response should parse")
        },
    );

    assert!(response.error.is_none(), "{:?}", response.error);
    assert_eq!(
        local_engine
            .lock()
            .expect("local engine lock should succeed")
            .pending_delegation_action_count(),
        1
    );
    assert_eq!(
        peer_engine
            .lock()
            .expect("peer engine lock should succeed")
            .pending_delegation_action_count(),
        0
    );
}

