#[test]
fn json_rpc_submit_signed_delegation_action_waits_for_processed_status() {
    let signer = signing_key(22);
    let mut initial_engine = single_node_engine();
    initial_engine
        .create_account(22, signer.verifying_key().to_bytes(), [9; 32], 900)
        .expect("agent account should create");
    seed_account_policy_usdc(&mut initial_engine, 22, 5_000_000_000);
    let mandate = {
        let mut service = NodeRpcService::new(&mut initial_engine);
        service
            .create_mandate(sample_create_mandate_params(22, 1))
            .expect("mandate should create")
            .mandate
    };
    let engine = Arc::new(Mutex::new(initial_engine));
    let server = JsonRpcHttpServer::new_with_config(
        engine.clone(),
        JsonRpcServerConfig {
            manual_block_production_enabled: false,
            mahi_enabled: false,
            operator_bearer_token: None,
            peer_relay_bearer_token: None,
            network_bootstrap: None,
            peer_transport_enabled: false,
        },
    );
    let action = BlockDelegationAction::Open {
        agent: 22,
        mandate_id: mandate.id,
        performance_share_units: 1_000,
        crystallization_cadence_ms: 7 * 86_400 * 1_000,
        notice_period_ms: 24 * 3_600 * 1_000,
        agent_bond: 5_000_000_000,
    };
    let signed = signed_delegation_action_json(&signer, 7, 22, action, 1_050, Some(43));
    let action_id =
        super::decode_hex_array::<32>(&signed.action_id_hex).expect("action id should decode");
    let body = serde_json::to_string(&JsonRpcRequest {
        jsonrpc: "2.0".into(),
        method: "kombat_submitSignedDelegationAction".into(),
        params: serde_json::to_value(SubmitSignedDelegationActionParams {
            signed_delegation_action: signed,
            wait_timeout_ms: Some(1_000),
        })
        .expect("params should serialize"),
        id: json!(105),
    })
    .expect("request should serialize");
    let producer_engine = engine.clone();
    let producer = std::thread::spawn(move || {
        let deadline = Instant::now() + Duration::from_secs(2);
        loop {
            let mut guard = producer_engine.lock().expect("engine lock should succeed");
            if guard.pending_delegation_action_count() > 0 {
                guard
                    .produce_block_from_mempool(1_100, 1)
                    .expect("queued signed action should commit");
                break;
            }
            drop(guard);
            assert!(
                Instant::now() < deadline,
                "queued action did not become pending before test deadline"
            );
            std::thread::sleep(Duration::from_millis(5));
        }
    });

    let response: JsonRpcResponse =
        serde_json::from_str(&server.handle_json_request(&body)).expect("response should parse");
    producer.join().expect("producer should join");

    assert!(response.error.is_none(), "{:?}", response.error);
    let result = response.result.as_ref().expect("result should exist");
    assert_eq!(result["status"], "accepted");
    assert_eq!(result["action_id_hex"], encode_hex(&action_id));
    assert_eq!(result["action_status"]["status"], "processed");
    assert_eq!(result["action_status"]["receipt"]["kind"], "open");
    assert_eq!(
        result["action_status"]["receipt"]["delegation_id_hex"],
        encode_hex(&super::derive_delegation_id(22, &mandate.id, 1_050))
    );
}

