fn signed_delegation_action_forwarded_to_mahi_leader_converges_across_validators() {
    let signer = signing_key(22);
    let mut mandate_id = None;
    let servers = start_mahi_consensus_servers_with_env_and_setup(&[], |_, engine| {
        // Seed identical prerequisite state before consensus starts; this test exercises
        // signed delegation-action submission and replication, not mandate creation.
        engine
            .create_account(22, signer.verifying_key().to_bytes(), [9; 32], 900)
            .expect("agent account should create");
        seed_account_policy_usdc(engine, 22, 5_000_000_000);
        let mandate = {
            let mut service = NodeRpcService::new(engine);
            service
                .create_mandate(sample_create_mandate_params(22, 1))
                .expect("mandate should create")
                .mandate
        };
        if let Some(expected) = mandate_id {
            assert_eq!(mandate.id, expected);
        } else {
            mandate_id = Some(mandate.id);
        }
    });
    let mandate_id = mandate_id.expect("fixture should create a mandate");
    let action = BlockDelegationAction::Open {
        agent: 22,
        mandate_id,
        performance_share_units: 1_000,
        crystallization_cadence_ms: 7 * 86_400 * 1_000,
        notice_period_ms: 24 * 3_600 * 1_000,
        agent_bond: 5_000_000_000,
    };
    let signed = signed_delegation_action_json(&signer, 7, 22, action, 1_050, Some(48));
    let action_id =
        super::decode_hex_array::<32>(&signed.action_id_hex).expect("action id should decode");
    let leader = servers[0]
        .1
        .current_mahi_leader_snapshot()
        .expect("mahi leader should exist");
    let (_, submitter) = servers
        .iter()
        .find(|(byte, _)| validator(*byte) != leader)
        .expect("fixture should include a non-leader");
    let (_, leader_server) = servers
        .iter()
        .find(|(byte, _)| validator(*byte) == leader)
        .expect("fixture should include the leader");
    let body = serde_json::to_string(&JsonRpcRequest {
        jsonrpc: "2.0".into(),
        method: "kombat_submitSignedDelegationAction".into(),
        params: serde_json::to_value(SubmitSignedDelegationActionParams {
            signed_delegation_action: signed,
            wait_timeout_ms: None,
        })
        .expect("params should serialize"),
        id: json!(110),
    })
    .expect("request should serialize");

    let forwarded: JsonRpcResponse = with_env_vars(
        &[(super::NETWORK_SUBMIT_FORWARDING_ENV, Some("1".into()))],
        || {
            serde_json::from_str(&submitter.handle_json_request(&body))
                .expect("forwarded response should parse")
        },
    );

    assert!(forwarded.error.is_none(), "{:?}", forwarded.error);
    assert_eq!(
        forwarded.result.as_ref().expect("result should exist")["status"],
        "accepted"
    );
    assert_eq!(
        consensus_metrics(submitter)["rpc_submit_metrics"]["forwarded_submit_total"],
        1,
        "non-leader should forward signed actions to the MAHI leader"
    );
    assert_eq!(
        submitter
            .engine()
            .lock()
            .expect("submitter engine lock should succeed")
            .pending_delegation_action_count(),
        1,
        "leader gossip should relay the forwarded signed action back to the submitter"
    );
    assert_eq!(
        leader_server
            .engine()
            .lock()
            .expect("leader engine lock should succeed")
            .pending_delegation_action_count(),
        1,
        "leader should queue the forwarded signed action"
    );

    // The helper runs the requested number of rounds and waits for convergence after each
    // round. Match the existing MAHI commit-log tests' 11-round window so the commit rule has
    // enough rounds to execute the leader carrying this action.
    drive_mahi_rounds_until_converged(&servers, 11);

    let status_body = serde_json::to_string(&JsonRpcRequest {
        jsonrpc: "2.0".into(),
        method: "kombat_getDelegationActionStatus".into(),
        params: json!({ "action_id_hex": encode_hex(&action_id) }),
        id: json!(111),
    })
    .expect("status request should serialize");
    for (byte, server) in &servers {
        let status: JsonRpcResponse =
            serde_json::from_str(&server.handle_json_request(&status_body))
                .expect("status response should parse");
        assert!(status.error.is_none(), "{:?}", status.error);
        let result = status.result.as_ref().expect("status result should exist");
        assert_eq!(
            result["status"], "processed",
            "validator {byte} status: {result}"
        );
        assert_eq!(result["receipt"]["kind"], "open");
        assert_eq!(
            result["receipt"]["delegation_id_hex"],
            encode_hex(&super::derive_delegation_id(22, &mandate_id, 1_050))
        );
    }
}

#[test]
fn json_rpc_submit_signed_delegation_action_rejects_bad_signature() {
    let signer = signing_key(22);
    let mut initial_engine = single_node_engine();
    initial_engine
        .create_account(22, signer.verifying_key().to_bytes(), [9; 32], 900)
        .expect("agent account should create");
    seed_account_policy_usdc(&mut initial_engine, 22, 5_000_000_000);
    let mandate = {
        let mut service = NodeRpcService::new(&mut initial_engine);
        service
            .create_mandate(sample_create_mandate_params(22, 1))
            .expect("mandate should create")
            .mandate
    };
    let engine = Arc::new(Mutex::new(initial_engine));
    let server = JsonRpcHttpServer::new_with_config(
        engine.clone(),
        JsonRpcServerConfig {
            manual_block_production_enabled: false,
            mahi_enabled: false,
            operator_bearer_token: None,
            peer_relay_bearer_token: None,
            network_bootstrap: None,
            peer_transport_enabled: false,
        },
    );
    let action = BlockDelegationAction::Open {
        agent: 22,
        mandate_id: mandate.id,
        performance_share_units: 1_000,
        crystallization_cadence_ms: 7 * 86_400 * 1_000,
        notice_period_ms: 24 * 3_600 * 1_000,
        agent_bond: 5_000_000_000,
    };
    let mut signed = signed_delegation_action_json(&signer, 7, 22, action, 1_050, Some(44));
    let mut signature =
        super::decode_hex_array::<64>(&signed.signature_hex).expect("signature should decode");
    signature[0] ^= 0xff;
    signed.signature_hex = encode_hex(&signature);
    let body = serde_json::to_string(&JsonRpcRequest {
        jsonrpc: "2.0".into(),
        method: "kombat_submitSignedDelegationAction".into(),
        params: serde_json::to_value(SubmitSignedDelegationActionParams {
            signed_delegation_action: signed,
            wait_timeout_ms: None,
        })
        .expect("params should serialize"),
        id: json!(106),
    })
    .expect("request should serialize");

    let response: JsonRpcResponse =
        serde_json::from_str(&server.handle_json_request(&body)).expect("response should parse");

    let error = response.error.expect("error should exist");
    assert_eq!(error.code, -32026);
    assert_eq!(error.message, "delegation rejected");
    assert_eq!(
        error.data.expect("error data should exist")["reason"],
        "invalid_delegation_action_signature"
    );
    assert_eq!(
        engine
            .lock()
            .expect("engine lock should succeed")
            .pending_delegation_action_count(),
        0
    );
}

