#[test]
fn rejects_oversized_http_request_bodies() {
    let server = JsonRpcHttpServer::new(Arc::new(Mutex::new(single_node_engine())));
    let request = format!(
        "POST / HTTP/1.1\r\nHost: localhost\r\nContent-Type: application/json\r\nContent-Length: {}\r\n\r\n",
        MAX_HTTP_BODY_BYTES + 1,
    );
    let listener = TcpListener::bind("127.0.0.1:0").expect("listener should bind");
    let address = listener.local_addr().expect("listener addr should exist");
    let server_thread = std::thread::spawn(move || {
        let (mut stream, _) = listener.accept().expect("client should connect");
        server
            .handle_http_connection(&mut stream)
            .expect("http connection should return 413 cleanly");
    });
    let mut client = TcpStream::connect(address).expect("client should connect");
    client
        .write_all(request.as_bytes())
        .expect("request should write");
    let mut response = String::new();
    client
        .read_to_string(&mut response)
        .expect("response should read");
    server_thread.join().expect("server thread should join");

    assert!(response.starts_with("HTTP/1.1 413 Payload Too Large"));
    assert!(response.contains("request too large"));
}

#[test]
fn rejects_oversized_http_request_headers() {
    let server = JsonRpcHttpServer::new(Arc::new(Mutex::new(single_node_engine())));
    let padding = "A".repeat(MAX_HTTP_HEADER_BYTES + 1);
    let request = format!(
        "POST / HTTP/1.1\r\nHost: localhost\r\nX-Padding: {}\r\nContent-Type: application/json\r\nContent-Length: 0\r\n\r\n",
        padding,
    );
    let listener = TcpListener::bind("127.0.0.1:0").expect("listener should bind");
    let address = listener.local_addr().expect("listener addr should exist");
    let server_thread = std::thread::spawn(move || {
        let (mut stream, _) = listener.accept().expect("client should connect");
        server
            .handle_http_connection(&mut stream)
            .expect("http connection should return 413 cleanly");
    });
    let mut client = TcpStream::connect(address).expect("client should connect");
    client
        .write_all(request.as_bytes())
        .expect("request should write");
    let mut response = String::new();
    client
        .read_to_string(&mut response)
        .expect("response should read");
    server_thread.join().expect("server thread should join");

    assert!(response.starts_with("HTTP/1.1 413 Payload Too Large"));
    assert!(response.contains("request too large"));
}

#[test]
fn operator_can_liquidate_under_margin_position() {
    let mut engine = single_node_engine();
    engine.set_market_risk_parameters(
        7,
        MarketRiskParameters {
            maintenance_margin_bps: 500,
            liquidation_penalty_bps: 0,
            liquidator_fee_bps: 0,
        },
    );
    engine.set_isolated_collateral(7, 22, 10);
    engine.set_isolated_collateral(7, 33, 100);
    engine.set_isolated_collateral(7, 44, 100);
    engine.set_isolated_collateral(7, 55, 100);
    for (order, timestamp_ms) in [
        (
            OrderRequest {
                market_id: 7,
                account_id: 22,
                client_order_id: 1,
                side: OrderSide::Bid,
                quantity_lots: 3,
                kind: OrderKind::Limit { price_ticks: 100 },
                time_in_force: TimeInForce::Gtc,
                post_only: false,
            },
            1_000,
        ),
        (
            OrderRequest {
                market_id: 7,
                account_id: 33,
                client_order_id: 2,
                side: OrderSide::Ask,
                quantity_lots: 3,
                kind: OrderKind::Limit { price_ticks: 100 },
                time_in_force: TimeInForce::Gtc,
                post_only: false,
            },
            1_001,
        ),
        (
            OrderRequest {
                market_id: 7,
                account_id: 44,
                client_order_id: 3,
                side: OrderSide::Bid,
                quantity_lots: 3,
                kind: OrderKind::Limit { price_ticks: 90 },
                time_in_force: TimeInForce::Gtc,
                post_only: false,
            },
            1_002,
        ),
        (
            OrderRequest {
                market_id: 7,
                account_id: 55,
                client_order_id: 4,
                side: OrderSide::Ask,
                quantity_lots: 5,
                kind: OrderKind::Limit { price_ticks: 91 },
                time_in_force: TimeInForce::Gtc,
                post_only: false,
            },
            1_003,
        ),
    ] {
        engine
            .submit_order(order, timestamp_ms)
            .expect("order should succeed");
    }

    let server = JsonRpcHttpServer::new_with_config(
        Arc::new(Mutex::new(engine)),
        JsonRpcServerConfig {
            manual_block_production_enabled: false,
            mahi_enabled: false,
            operator_bearer_token: Some("secret-token".into()),
            peer_relay_bearer_token: None,
            network_bootstrap: None,
            peer_transport_enabled: false,
        },
    );
    let body = serde_json::to_string(&JsonRpcRequest {
        jsonrpc: "2.0".into(),
        method: "kombat_liquidatePosition".into(),
        params: json!({
            "market_id": 7,
            "account_id": 22,
            "liquidator_account_id": 99,
            "client_order_id": 5,
            "requested_lots": 2,
            "timestamp_ms": 1_004
        }),
        id: json!(12),
    })
    .expect("request should serialize");

    let authorized_request = format!(
        "POST / HTTP/1.1\r\nHost: localhost\r\nAuthorization: Bearer secret-token\r\nContent-Type: application/json\r\nContent-Length: {}\r\n\r\n{}",
        body.len(),
        body
    );
    let listener = TcpListener::bind("127.0.0.1:0").expect("listener should bind");
    let address = listener.local_addr().expect("listener addr should exist");
    let server_thread = std::thread::spawn(move || {
        let (mut stream, _) = listener.accept().expect("client should connect");
        server
            .handle_http_connection(&mut stream)
            .expect("http connection should succeed");
    });
    let mut client = TcpStream::connect(address).expect("client should connect");
    client
        .write_all(authorized_request.as_bytes())
        .expect("request should write");
    let mut raw_response = String::new();
    client
        .read_to_string(&mut raw_response)
        .expect("response should read");
    server_thread.join().expect("server thread should join");
    let response: JsonRpcResponse = serde_json::from_str(
        raw_response
            .split_once("\r\n\r\n")
            .expect("http response should contain headers")
            .1,
    )
    .expect("response should parse");
    let result = response.result.expect("result should exist");
    assert_eq!(result["market_id"], 7);
    assert_eq!(result["account_id"], 22);
    assert_eq!(result["liquidator_account_id"], 99);
    assert_eq!(result["requested_lots"], 2);
    assert_eq!(result["filled_lots"], 2);
    assert_eq!(result["remaining_lots"], 0);
    assert_eq!(result["post_net_lots"], 1);
    assert_eq!(result["post_under_maintenance"], true);
}

#[test]
fn json_rpc_dispatches_liquidation_pass_with_operator_auth() {
    let mut engine = single_node_engine();
    engine.set_market_risk_parameters(
        7,
        MarketRiskParameters {
            maintenance_margin_bps: 500,
            liquidation_penalty_bps: 0,
            liquidator_fee_bps: 0,
        },
    );
    engine.set_isolated_collateral(7, 22, 40);
    engine.set_isolated_collateral(7, 33, 100);
    engine.set_isolated_collateral(7, 44, 100);
    for (order, timestamp_ms) in [
        (
            OrderRequest {
                market_id: 7,
                account_id: 33,
                client_order_id: 1,
                side: OrderSide::Ask,
                quantity_lots: 3,
                kind: OrderKind::Limit { price_ticks: 100 },
                time_in_force: TimeInForce::Gtc,
                post_only: false,
            },
            1_000,
        ),
        (
            OrderRequest {
                market_id: 7,
                account_id: 22,
                client_order_id: 2,
                side: OrderSide::Bid,
                quantity_lots: 3,
                kind: OrderKind::Limit { price_ticks: 100 },
                time_in_force: TimeInForce::Gtc,
                post_only: false,
            },
            1_001,
        ),
        (
            OrderRequest {
                market_id: 7,
                account_id: 44,
                client_order_id: 3,
                side: OrderSide::Bid,
                quantity_lots: 1,
                kind: OrderKind::Limit { price_ticks: 90 },
                time_in_force: TimeInForce::Gtc,
                post_only: false,
            },
            1_002,
        ),
    ] {
        engine
            .submit_order(order, timestamp_ms)
            .expect("setup order should succeed");
    }
    engine.update_market_mark_price(7, 90, 1_003);

    let server = JsonRpcHttpServer::new_with_config(
        Arc::new(Mutex::new(engine)),
        JsonRpcServerConfig {
            manual_block_production_enabled: false,
            mahi_enabled: false,
            operator_bearer_token: Some("secret-token".into()),
            peer_relay_bearer_token: None,
            network_bootstrap: None,
            peer_transport_enabled: false,
        },
    );
    let body = serde_json::to_string(&JsonRpcRequest {
        jsonrpc: "2.0".into(),
        method: "kombat_runLiquidationPass".into(),
        params: json!({
            "liquidator_account_id": 99,
            "first_client_order_id": 10,
            "max_positions": 4,
            "timestamp_ms": 1_004
        }),
        id: json!(12),
    })
    .expect("request should serialize");

    let unauthorized: JsonRpcResponse =
        serde_json::from_str(&server.handle_json_request(&body)).expect("response should parse");
    assert_eq!(
        unauthorized.error,
        Some(super::JsonRpcErrorObject {
            code: -32010,
            message: "operator authorization required".into(),
            data: None,
        })
    );

    let operator_headers = BTreeMap::from([(
        "authorization".to_string(),
        "Bearer secret-token".to_string(),
    )]);
    let authorized: JsonRpcResponse =
        serde_json::from_str(&server.handle_json_request_with_headers(&body, &operator_headers))
            .expect("response should parse");
    assert!(authorized.error.is_none(), "{:?}", authorized.error);
    let result = authorized.result.expect("authorized result should exist");
    assert_eq!(result["liquidator_account_id"], 99);
    assert_eq!(result["scanned_positions"], 2);
    assert_eq!(result["attempted_positions"], 1);
    assert_eq!(result["succeeded_positions"], 1);
    assert_eq!(result["failed_positions"], 0);
    assert_eq!(result["skipped_stale_markets"], 0);
    assert_eq!(result["skipped_frozen_accounts"], 0);
    let steps = result["steps"].as_array().expect("steps should be array");
    assert_eq!(steps.len(), 1);
    assert_eq!(steps[0]["market_id"], 7);
    assert_eq!(steps[0]["account_id"], 22);
    assert_eq!(steps[0]["client_order_id"], 10);
    assert_eq!(steps[0]["status"], "filled");
    assert_eq!(steps[0]["filled_lots"], 1);
    assert_eq!(steps[0]["remaining_lots"], 0);
    assert_eq!(steps[0]["reason"], Value::Null);
}

#[test]
