#[test]
fn json_rpc_preview_liquidation_is_public_and_read_only() {
    let mut engine = single_node_engine();
    engine.set_market_risk_parameters(
        7,
        MarketRiskParameters {
            maintenance_margin_bps: 500,
            liquidation_penalty_bps: 0,
            liquidator_fee_bps: 0,
        },
    );
    engine.set_isolated_collateral(7, 22, 10);
    engine.set_isolated_collateral(7, 33, 100);
    engine.set_isolated_collateral(7, 44, 100);
    engine.set_isolated_collateral(7, 55, 100);
    for (order, timestamp_ms) in [
        (
            OrderRequest {
                market_id: 7,
                account_id: 22,
                client_order_id: 1,
                side: OrderSide::Bid,
                quantity_lots: 3,
                kind: OrderKind::Limit { price_ticks: 100 },
                time_in_force: TimeInForce::Gtc,
                post_only: false,
            },
            1_000,
        ),
        (
            OrderRequest {
                market_id: 7,
                account_id: 33,
                client_order_id: 2,
                side: OrderSide::Ask,
                quantity_lots: 3,
                kind: OrderKind::Limit { price_ticks: 100 },
                time_in_force: TimeInForce::Gtc,
                post_only: false,
            },
            1_001,
        ),
        (
            OrderRequest {
                market_id: 7,
                account_id: 44,
                client_order_id: 3,
                side: OrderSide::Bid,
                quantity_lots: 3,
                kind: OrderKind::Limit { price_ticks: 90 },
                time_in_force: TimeInForce::Gtc,
                post_only: false,
            },
            1_002,
        ),
        (
            OrderRequest {
                market_id: 7,
                account_id: 55,
                client_order_id: 4,
                side: OrderSide::Ask,
                quantity_lots: 5,
                kind: OrderKind::Limit { price_ticks: 91 },
                time_in_force: TimeInForce::Gtc,
                post_only: false,
            },
            1_003,
        ),
    ] {
        engine
            .submit_order(order, timestamp_ms)
            .expect("order should succeed");
    }

    let server = JsonRpcHttpServer::new(Arc::new(Mutex::new(engine)));
    let body = serde_json::to_string(&JsonRpcRequest {
        jsonrpc: "2.0".into(),
        method: "kombat_previewLiquidation".into(),
        params: json!({
            "market_id": 7,
            "account_id": 22,
            "liquidator_account_id": 99,
            "client_order_id": 5,
            "requested_lots": 2,
            "timestamp_ms": 1_004
        }),
        id: json!(12),
    })
    .expect("request should serialize");
    let response: JsonRpcResponse =
        serde_json::from_str(&server.handle_json_request(&body)).expect("response should parse");
    assert!(response.error.is_none(), "{:?}", response.error);

    let result = response.result.expect("result should exist");
    assert_eq!(result["market_id"], 7);
    assert_eq!(result["account_id"], 22);
    assert_eq!(result["liquidator_account_id"], 99);
    assert_eq!(result["requested_lots"], 2);
    assert_eq!(result["filled_lots"], 2);
    assert_eq!(result["remaining_lots"], 0);
    assert_eq!(result["post_net_lots"], 1);
    assert_eq!(result["post_under_maintenance"], true);
    assert_eq!(result["post_account_frozen"], true);
    assert_eq!(result["post_market_bad_debt_balance"], "20");

    let verify_body = serde_json::to_string(&JsonRpcRequest {
        jsonrpc: "2.0".into(),
        method: "kombat_getPosition".into(),
        params: json!({
            "market_id": 7,
            "account_id": 22
        }),
        id: json!(13),
    })
    .expect("request should serialize");
    let verify_response: JsonRpcResponse =
        serde_json::from_str(&server.handle_json_request(&verify_body))
            .expect("response should parse");
    let verify_result = verify_response.result.expect("result should exist");
    assert_eq!(verify_result["net_lots"], 3);
}

