#[test]
fn node_rpc_reads_oracle_history() {
    let mut engine = single_node_engine();
    let mut service = NodeRpcService::new(&mut engine);

    service.set_market_oracle_config(7, 2_500, 1_000);
    service.set_mark_price(7, 115, 1_001);
    service.set_index_price(7, 114, 1_002);

    let history = service.get_oracle_history(Some(7), None, Some(0), 10);
    assert_eq!(history.len(), 3);
    assert_eq!(
        history[0].kind,
        super::OracleHistoryKindResponse::OracleConfigUpdated {
            max_staleness_ms: 2_500
        }
    );
    assert_eq!(
        history[1].kind,
        super::OracleHistoryKindResponse::MarkPriceUpdated {
            mark_price_ticks: 115
        }
    );
    assert_eq!(
        history[2].kind,
        super::OracleHistoryKindResponse::IndexPriceUpdated {
            index_price_ticks: 114
        }
    );

    let filtered = service.get_oracle_history(
        Some(7),
        Some(RuntimeEventTopic::MarkPriceUpdated),
        Some(0),
        10,
    );
    assert_eq!(filtered.len(), 1);
    assert_eq!(
        filtered[0].kind,
        super::OracleHistoryKindResponse::MarkPriceUpdated {
            mark_price_ticks: 115
        }
    );
}

