#[test]
fn event_stream_endpoint_emits_matching_events() {
    let signer = signing_key(8);
    let grantee = signing_key(9);
    let mut engine = single_node_engine();
    engine
        .create_account(11, signer.verifying_key().to_bytes(), [9; 32], 1_000)
        .expect("account should create");
    engine
        .submit_owner_call(
            kombat_chain_policy::SignedOwnerCall {
                account_id: 11,
                chain_id: 7,
                call: OwnerCall {
                    signer: signer.verifying_key().to_bytes(),
                    nonce: 0,
                    action: OwnerAction::CreatePolicy {
                        policy_id: 42,
                        grantee: grantee.verifying_key().to_bytes(),
                        expires_at: 50_000,
                        terms: sample_policy().terms.clone(),
                    },
                },
                signature: signer
                    .sign(
                        &borsh::to_vec(&(
                            11_u64,
                            7_u64,
                            &OwnerCall {
                                signer: signer.verifying_key().to_bytes(),
                                nonce: 0,
                                action: OwnerAction::CreatePolicy {
                                    policy_id: 42,
                                    grantee: grantee.verifying_key().to_bytes(),
                                    expires_at: 50_000,
                                    terms: sample_policy().terms.clone(),
                                },
                            },
                        ))
                        .expect("owner call should serialize"),
                    )
                    .to_bytes(),
            },
            1_050,
        )
        .expect("policy should create");
    engine
        .submit_intent(
            signed_intent(&grantee, 1, 10_000, IntentKind::Cancel { order_id: 7 }),
            1_100,
        )
        .expect("intent should admit");
    engine
        .produce_block_from_mempool(1_200, 10)
        .expect("block should produce");

    let server = JsonRpcHttpServer::new(Arc::new(Mutex::new(engine)));
    let listener = TcpListener::bind("127.0.0.1:0").expect("listener should bind");
    let address = listener.local_addr().expect("listener addr should exist");
    let server_thread = std::thread::spawn(move || {
        let (mut stream, _) = listener.accept().expect("client should connect");
        server
            .handle_http_connection(&mut stream)
            .expect("http connection should succeed");
    });

    let mut client = TcpStream::connect(address).expect("client should connect");
    client
        .write_all(
            b"GET /events?from_seq=0&limit=10&policy_id=42&topic=intent_executed HTTP/1.1\r\nHost: localhost\r\nOrigin: http://localhost:5173\r\n\r\n",
        )
        .expect("request should write");
    let mut response = String::new();
    client
        .read_to_string(&mut response)
        .expect("response should read");
    server_thread.join().expect("server thread should join");

    assert!(response.contains("HTTP/1.1 200 OK"));
    assert!(response.contains("Content-Type: text/event-stream"));
    assert!(response.contains("Cache-Control: no-cache, no-transform"));
    assert!(response.contains("Connection: keep-alive"));
    assert!(response.contains("Access-Control-Allow-Origin: http://localhost:5173"));
    assert!(response
        .contains("Access-Control-Allow-Headers: content-type, authorization, last-event-id"));
    assert!(response.contains("X-Accel-Buffering: no"));
    assert!(response.contains("event: intent_executed"));
    assert!(response.contains("\"policy_id\":42"));
    assert!(response.contains("event: cursor"));
    assert!(response.contains("\"next_seq\":4"));
}

#[test]
fn http_options_preflight_returns_browser_headers() {
    let engine = single_node_engine();
    let server = JsonRpcHttpServer::new(Arc::new(Mutex::new(engine)));
    let listener = TcpListener::bind("127.0.0.1:0").expect("listener should bind");
    let address = listener.local_addr().expect("listener addr should exist");
    let server_thread = std::thread::spawn(move || {
        let (mut stream, _) = listener.accept().expect("client should connect");
        server
            .handle_http_connection(&mut stream)
            .expect("http connection should succeed");
    });

    let mut client = TcpStream::connect(address).expect("client should connect");
    client
        .write_all(
            b"OPTIONS /events HTTP/1.1\r\nHost: localhost\r\nOrigin: https://0x26.xyz\r\nAccess-Control-Request-Method: GET\r\n\r\n",
        )
        .expect("request should write");
    let mut response = String::new();
    client
        .read_to_string(&mut response)
        .expect("response should read");
    server_thread.join().expect("server thread should join");

    assert!(response.contains("HTTP/1.1 204 No Content"));
    assert!(response.contains("Access-Control-Allow-Origin: https://0x26.xyz"));
    assert!(response.contains("Access-Control-Allow-Methods: GET, POST, OPTIONS"));
    assert!(response
        .contains("Access-Control-Allow-Headers: content-type, authorization, last-event-id"));
}

