#[test]
fn legacy_http_serves_market_and_account_streams() {
    let mut engine = single_node_engine();
    {
        let mut service = NodeRpcService::new(&mut engine);
        service
            .submit_order(
                OrderRequest {
                    market_id: 7,
                    account_id: 22,
                    client_order_id: 1,
                    side: OrderSide::Ask,
                    quantity_lots: 5,
                    kind: OrderKind::Limit { price_ticks: 103 },
                    time_in_force: TimeInForce::Gtc,
                    post_only: false,
                },
                1_000,
            )
            .expect("ask should rest");
        service
            .submit_order(
                OrderRequest {
                    market_id: 7,
                    account_id: 33,
                    client_order_id: 2,
                    side: OrderSide::Bid,
                    quantity_lots: 3,
                    kind: OrderKind::Limit { price_ticks: 104 },
                    time_in_force: TimeInForce::Gtc,
                    post_only: false,
                },
                1_001,
            )
            .expect("bid should fill");
    }

    let server = JsonRpcHttpServer::new(Arc::new(Mutex::new(engine)));
    let listener = TcpListener::bind("127.0.0.1:0").expect("listener should bind");
    let address = listener.local_addr().expect("listener addr should exist");
    let server_for_thread = server.clone();
    let server_thread = std::thread::spawn(move || {
        let (mut stream, _) = listener.accept().expect("client should connect");
        server_for_thread
            .handle_http_connection(&mut stream)
            .expect("http connection should succeed");
    });

    let mut client = TcpStream::connect(address).expect("client should connect");
    client
        .write_all(
            b"GET /market-data/markets/stream?market_id=7&limit=50&follow=false HTTP/1.1\r\nHost: localhost\r\n\r\n",
        )
        .expect("request should write");
    let mut response = String::new();
    client
        .read_to_string(&mut response)
        .expect("response should read");
    server_thread.join().expect("server thread should join");

    assert!(response.contains("HTTP/1.1 200 OK"));
    assert!(response.contains("Content-Type: text/event-stream"));
    assert!(response.contains("event: market_snapshot"));
    assert!(response.contains("event: book"));
    assert!(response.contains("event: trade"));
    assert!(response.contains("\"price_ticks\":103"));
    assert!(response.contains("event: cursor"));

    let listener = TcpListener::bind("127.0.0.1:0").expect("listener should bind");
    let address = listener.local_addr().expect("listener addr should exist");
    let server_for_thread = server.clone();
    let server_thread = std::thread::spawn(move || {
        let (mut stream, _) = listener.accept().expect("client should connect");
        server_for_thread
            .handle_http_connection(&mut stream)
            .expect("http connection should succeed");
    });

    let mut client = TcpStream::connect(address).expect("client should connect");
    client
        .write_all(
            b"GET /market-data/accounts/stream?account_id=33&market_id=7&limit=50&follow=false HTTP/1.1\r\nHost: localhost\r\n\r\n",
        )
        .expect("request should write");
    let mut response = String::new();
    client
        .read_to_string(&mut response)
        .expect("response should read");
    server_thread.join().expect("server thread should join");

    assert!(response.contains("HTTP/1.1 200 OK"));
    assert!(response.contains("event: account_trading_state"));
    assert!(response.contains("event: fill"));
    assert!(response.contains("event: position"));
    assert!(response.contains("\"account_id\":33"));
    assert!(response.contains("event: cursor"));
}

#[test]
fn mahi_single_node_executes_committed_intents_in_mahi_mode() {
    with_env_vars(
        &[
            ("KOMBAT_CONSENSUS", Some("mahi".into())),
            ("KOMBAT_MAHI_COMMIT_RULE", Some("mahi".into())),
        ],
        || {
            let signer = signing_key(8);
            let bootstrap = single_validator_mahi_bootstrap(1);
            let mut engine = SingleNodeEngine::new_with_validator_set(
                SingleNodeConfig {
                    chain_id: 7,
                    validator_id: validator(1),
                    consensus_signing_key: [1; 32],
                    genesis_timestamp_ms: 1_000,
                    genesis_state_root: [3; 32],
                    pacemaker: kombat_chain_consensus::PacemakerConfig {
                        base_timeout_ms: 300,
                        max_timeout_ms: 20_000,
                        max_exponent: 6,
                        max_clock_skew_ms: 1_000,
                    },
                },
                Some(&bootstrap.validator_set),
            );
            engine
                .policy_store_mut()
                .insert(sample_policy())
                .expect("policy should insert");
            let intent = signed_intent(
                &signer,
                1,
                10_000,
                IntentKind::Transfer {
                    to: 12,
                    token: 1,
                    amount: 25,
                },
            );
            let intent_id = intent_id(&intent);
            engine
                .submit_intent(intent, 1_050)
                .expect("intent should admit");
            let server = JsonRpcHttpServer::new_with_config(
                Arc::new(Mutex::new(engine)),
                JsonRpcServerConfig {
                    manual_block_production_enabled: false,
                    mahi_enabled: true,
                    operator_bearer_token: Some("mahi-token".into()),
                    peer_relay_bearer_token: None,
                    network_bootstrap: Some(bootstrap),
                    peer_transport_enabled: false,
                },
            );

            let mut produced_rounds = 0_u64;
            for offset in 0..12_u64 {
                let result = server
                    .maybe_run_mahi_round(1_100 + offset * 100, 10)
                    .expect("mahi round should not error");
                if result.is_some() {
                    produced_rounds += 1;
                }
            }
            assert!(
                produced_rounds > 0,
                "single-validator mahi should eventually produce"
            );

            let deadline = Instant::now() + Duration::from_secs(2);
            loop {
                let metrics = consensus_metrics(&server);
                if metrics["mahi"]["executed_block_count"]
                    .as_u64()
                    .unwrap_or(0)
                    > 0
                {
                    let status_body = serde_json::to_string(&JsonRpcRequest {
                        jsonrpc: "2.0".into(),
                        method: "kombat_getIntentStatus".into(),
                        params: json!({
                            "intent_id_hex": encode_hex(&intent_id),
                        }),
                        id: json!(63),
                    })
                    .expect("status request should serialize");
                    let response: JsonRpcResponse =
                        serde_json::from_str(&server.handle_json_request(&status_body))
                            .expect("status response should parse");
                    let result = response.result.expect("status result should exist");
                    assert_eq!(result["stage"], json!("executed"));
                    let head = server.engine().head_snapshot();
                    assert!(
                        head.head_height > 0,
                        "mahi execution should advance the chain"
                    );
                    break;
                }
                if Instant::now() >= deadline {
                    panic!(
                        "single-validator mahi execution did not complete: {}",
                        metrics
                    );
                }
                std::thread::sleep(Duration::from_millis(25));
            }
        },
    );
}
